<?php
declare(strict_types=1);

/**
 * Общий слой поколения v5: разбор страницы на узлы, трафареты и заполнение.
 *
 * Одни и те же правила нужны трижды — экстрактору (`bloki-v5.php`), генератору
 * (`generator-v5.php`) и приёмке (`priyomka-v5.php`). Если правило маскировки
 * живёт в двух копиях, пул и генерация расходятся молча: в пуле «{ПРОЦ}», в
 * приёмке «до 500%», и ни один счётчик об этом не скажет.
 */

require_once __DIR__ . '/PersonNames.php';

const V5_TYPES = ['main', 'obzor', 'promo', 'news', 'info', 'partnery',
                  'app', 'bonus', 'registracia', 'slots', 'vhod', 'zerkalo'];

/** Узлы верхнего уровня: у корпуса они начинаются с нулевой колонки. */
function v5Uzly(string $html): array
{
    $lines = explode("\n", $html);
    $uzly = [];
    for ($i = 0, $n = count($lines); $i < $n; $i++) {
        $l = $lines[$i];
        if ($l === '' || $l[0] !== '<' || str_starts_with($l, '</')) { continue; }
        if (!preg_match('~^<([a-z0-9]+)([^>]*)>~i', $l, $m)) { continue; }
        [, $tag, $attrs] = $m;
        $класс = preg_match('~class="([^"]*)"~', $attrs, $c) ? $c[1] : '';
        $конец = "</$tag>";
        $j = $i;
        if (!str_contains($l, $конец)) {
            for ($j = $i + 1; $j < $n; $j++) { if (str_starts_with($lines[$j], $конец)) { break; } }
        }
        $j = min($j, $n - 1);
        $uzly[] = ['тег' => $tag, 'класс' => $класс,
                   'html' => implode("\n", array_slice($lines, $i, $j - $i + 1))];
        $i = $j;
    }
    return $uzly;
}

function v5Text(string $html): string
{
    return trim(preg_replace('~\s+~u', ' ',
        html_entity_decode(preg_replace('~<[^>]*>~', ' ', $html), ENT_QUOTES, 'UTF-8')));
}

/** Внутренность узла одной строкой — ссылки и выделения сохраняются. */
function v5Vnutr(string $html): string
{
    $t = preg_replace('~^<[a-z0-9]+[^>]*>~i', '', $html);
    $t = preg_replace('~</[a-z0-9]+>$~i', '', $t);
    return trim(preg_replace('~\s*\n\s*~u', ' ', $t));
}

function v5Klass(array $u): string
{
    $c = trim(explode(' ', $u['класс'])[0] ?? '');
    return $c !== '' ? $c : $u['тег'];
}

function v5Variant(array $u): string
{
    return preg_match('~\bvariant-(v\d+)~', $u['класс'], $m) ? $m[1] : 'v0';
}

/**
 * Трафарет: числа и герои заменяются прорезями, наблюдённые значения копятся
 * в банки (второй аргумент — по ссылке, можно пустой).
 *
 * Разметка стоит между числом и его словом («до <strong>75%</strong>»), поэтому
 * привязка идёт не к предлогу, а к форме самого числа: дробный процент в этой
 * нише всегда RTP, целый — бонус или кэшбэк. Порядок правил важен: каталог и
 * провайдеры ловятся раньше денег, иначе «1 394+ слотов» уйдёт в рубли.
 */
function v5Trafaret(string $t, array &$банки = []): string
{
    // Чужие прорези доноров приводятся к нашим сразу: иначе «{ИМЯ} проверил» и
    // «{NAME} проверил» остаются разными ключами пула, а после подстановки дают
    // один и тот же заголовок. На десятом наборе это выдало два одинаковых H2
    // подряд, причём второй без тела.
    foreach (V5_CHUZHIE_PROREZI as $чужой => $наш) {
        $t = str_replace('{' . $чужой . '}', '{' . $наш . '}', $t);
    }
    static $имена = null, $ном = null;
    if ($имена === null) {
        $r = new ReflectionClass('PersonNames');
        $ном = array_flip($r->getConstant('BASE'));
        $имена = PersonNames::regex();
    }
    $правила = [
        ['СЛОТОВ',      '~\b\d{1,2}\s?\d{3}(?=\+\s*(?:слот|игр|автомат))~u'],
        // Тот же размер каталога, но без плюса: «более 2000 автоматов».
        // Без этого правила число оставалось живым и расходилось со своей
        // же прорезью на соседней странице — смысловая приёмка ловит это
        // как «слотов расходится по страницам: 1 394 (main) · 2000 (vhod)».
        ['СЛОТОВ',      '~(?<=более )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=более чем )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=свыше )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=свыше чем )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=около )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=около чем )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=порядка )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['СЛОТОВ',      '~(?<=порядка чем )\d[\d ]{2,4}(?=\s*(?:слот|игр|автомат))~ui'],
        ['ПРОВАЙДЕРОВ', '~\b\d{2,3}(?=\+\s*провайдер)~u'],
        ['СУММА',       '~\b\d+(?:[.,]\d+)?\s?(?:к|тыс\.?|млн)\b~u'],
        ['РУБЛИ',       '~(?<!\d)(?<!\d )\d{1,3}(?:\s\d{3})*\s?(?:₽|рубл\w+)~u'],
        ['RTP',         '~(?<=RTP )\d{2}(?:[.,]\d)?(?=%)~u'],
        // Два знака после точки — это отдача в карточке слота («96.51%»). Без
        // отдельного правила её хвост забирал процент бонуса, и в выдаче
        // появлялось «96.286%»: целое от карточки, дробь от чужого банка.
        ['RTP2',        '~\b\d{2}[.,]\d{2}(?=%)~u'],
        ['RTP',         '~\b\d{2}[.,]\d(?=%)~u'],
        // «до 500%» и «кэшбэк 10%» — разные величины. Пока они лежали в одном
        // банке, бонус подставлялся долей, и в тексте появлялось «бонус до 13%»
        // при корпусной полосе бонуса 15–1000.
        ['ПРОЦ',        '~(?<![\d.,])\d{2,4}(?=%)~u'],
        ['МИН',         '~(?<=за )\d{1,3}(?= мин)~u'],
        ['МИН',         '~(?<=от )\d{1,3}(?= мин)~u'],
        ['ВЕЙДЖЕР',     '~(?<=x)\d{2}\b~u'],
    ];
    foreach ($правила as [$имя, $re]) {
        $t = preg_replace_callback($re, function ($m) use ($имя, &$банки, $t) {
            // «RTP достигает 92%» — это отдача, а не бонус: между словом и
            // числом стоит глагол, и лобовое правило уводило значение в банк
            // процентов, откуда потом приезжало «RTP 445%».
            $до = mb_substr($t, 0, (int) mb_strpos($t, $m[0]));
            if ($имя === 'ПРОЦ') {
                $хвост = preg_replace('~<[^>]*>~', '', mb_substr($до, -40));
                // «отдача ниже 90%» и «возврат игроку выше 96%» — тоже RTP:
                // без этого в FAQ приезжало «отдача ниже 30%» из банка долей.
                if (preg_match('~(?:RTP|отдач\w*|возврат\w*)[^%]{0,40}$~ui', $до)) { $имя = 'RTP'; }
                elseif (!preg_match('~\bдо\s*$~u', $хвост)) { $имя = 'ДОЛЯ'; }
            }
            $банки[$имя][$m[0]] = ($банки[$имя][$m[0]] ?? 0) + 1;
            return '{' . $имя . '}';
        }, $t);
    }
    // «между 94% и 97%», «от 94% до 97%» — второй процент из той же пары, что
    // и первый: иначе в FAQ приезжало «между 94.8% и 333%».
    $t = (string) preg_replace('~\{RTP\}%(\s+(?:и|до)\s+)\{(?:ДОЛЯ|ПРОЦ)\}%~u', '{RTP}%$1{RTP2}%', $t);
    // Имя героя: 94 % вхождений в именительном, остальные — с окончанием,
    // и окончание переносится в прорезь, чтобы генератор склонил своё имя.
    return preg_replace_callback($имена, function ($m) use ($ном, &$банки) {
        $форма = $m[0];
        if (isset($ном[$форма])) {
            $прорезь = v5Rod($форма) === 'ж' ? 'ИМЯЖ' : 'ИМЯ';
            $банки[$прорезь][$форма] = ($банки[$прорезь][$форма] ?? 0) + 1;
            return '{' . $прорезь . '}';
        }
        // «Люди» разбирались как «Люда» в косвенном падеже, и в выдачу уходило
        // «Елени хвалят скорость» вместо «Люди хвалят скорость». Совпадение
        // корня с именем из банка ещё не делает форму именем.
        if (isset(V5_NE_IMENA[mb_strtolower($форма)])) { return $форма; }
        foreach (['ом', 'ей', 'ой', 'а', 'у', 'е', 'ы', 'и', 'ю', 'я'] as $ок) {
            if (mb_substr($форма, -mb_strlen($ок)) !== $ок) { continue; }
            $корень = mb_substr($форма, 0, mb_strlen($форма) - mb_strlen($ок));
            foreach ([$корень, $корень . 'й', $корень . 'ь', $корень . 'а', $корень . 'я'] as $кандидат) {
                if (isset($ном[$кандидат])) {
                    return '{' . (v5Rod($кандидат) === 'ж' ? 'ИМЯЖ' : 'ИМЯ') . ':' . $ок . '}';
                }
            }
        }
        return '{ИМЯ}';
    }, $t);
}

/**
 * Соседние предложения-двойники. Отбор фраз считает близость по цепочкам из
 * четырёх слов, и пара вроде «Если нужны гарантии — вам не сюда» и «Если
 * нужны гарантии — это не сюда» через неё проходит: общая только одна
 * цепочка. Рядом они читаются как заедание. У доноров и у конкурента таких
 * пар 0.02 на страницу, поэтому режем по составу знаменательных слов.
 */
function v5UbratSosedniiPovtor(string $html, float $порог = 0.55): string
{
    $знач = static function (string $ф): array {
        preg_match_all('~[а-яё]{4,}~u', mb_strtolower(strip_tags($ф), 'UTF-8'), $m);
        return array_flip($m[0]);
    };
    $двойник = static function (array $a, array $b) use ($порог): bool {
        if (!$a || !$b) { return false; }
        $всех = count($a + $b);
        return $всех > 0 && count(array_intersect_key($a, $b)) / $всех > $порог;
    };
    // Хвост предыдущего блока помним между вызовами: пара «последняя фраза
    // абзаца — первая фраза следующего» читается так же плохо, как пара
    // внутри одного абзаца, а разделяет их только перевод строки.
    $прошлое = null;
    return preg_replace_callback('~(?s)(<(p|li)\b[^>]*>)(.*?)(</\2>)~',
        function ($m) use ($знач, $двойник, &$прошлое) {
            // Режем по границам предложений прямо в разметке: выброшенный
            // кусок уходит вместе со своими ссылками и выделениями.
            // Точка нередко стоит внутри выделения: «…не сюда.</strong> Но…».
            // Закрывающие теги пропускаем, иначе два предложения слипаются в
            // один кусок и разница по словам размывается.
            // Точка нередко стоит внутри выделения: «…не сюда.</strong> Но…».
            // Закрывающие теги забираем в разделитель, иначе два предложения
            // слипаются в один кусок и разница по словам размывается.
            $куски = preg_split('~(?<=[.!?;])((?:\s*</[a-zA-Z]+>)*\s+)~u', $m[3], -1,
                PREG_SPLIT_NO_EMPTY | PREG_SPLIT_DELIM_CAPTURE);
            $оставить = []; $последнее = $прошлое;
            // Куски идут парами «предложение + разделитель». Выбрасываем пару
            // целиком: закрывающий тег предложения лежит в его разделителе.
            for ($i = 0; $i < count($куски); $i += 2) {
                $фраза = $куски[$i];
                $хвост = $куски[$i + 1] ?? '';
                if (trim(strip_tags($фраза)) === '') { $оставить[] = $фраза . $хвост; continue; }
                $с = $знач($фраза);
                if ($последнее !== null && $двойник($с, $последнее)) { continue; }
                $оставить[] = $фраза . $хвост;
                $последнее = $с;
            }
            $прошлое = $последнее;
            $тело = implode('', $оставить);
            // Блок, от которого ничего не осталось, убираем целиком.
            return trim(strip_tags($тело)) === '' ? '' : $m[1] . $тело . $m[4];
        }, $html);
}

/**
 * Перевод куска текста на «вы». Часть площадок корпуса пишет читателю на
 * «вы» — vavada, gama и девять комплектов конкурента, — но не сплошь: у них
 * на странице и «вы», и «ты» рядом, просто доля «вы» выше. Поэтому переводим
 * блоками: внутри абзаца регистр один, а по странице их смесь.
 *
 * Глаголы правятся по правилу: «-ешь/-ёшь» → «-ете/-ёте», «-ишь» → «-ите»,
 * возвратные — «-ешься» → «-етесь». Исключения русского языка на этом узком
 * словаре сводятся к «хочешь»; «лишь» и «тишь» — не глаголы, их не трогаем.
 */
const V5_VY_МЕСТОИМЕНИЯ = [
    'тебя' => 'вас', 'тебе' => 'вам', 'тобой' => 'вами', 'тобою' => 'вами',
    'твой' => 'ваш', 'твоя' => 'ваша', 'твоё' => 'ваше', 'твое' => 'ваше',
    'твои' => 'ваши', 'твоего' => 'вашего', 'твоей' => 'вашей', 'твоему' => 'вашему',
    'твоим' => 'вашим', 'твоими' => 'вашими', 'твоих' => 'ваших', 'твою' => 'вашу',
    'твоём' => 'вашем', 'твоем' => 'вашем', 'ты' => 'вы',
];
const V5_VY_ИСКЛЮЧЕНИЯ = ['ной' => 'нойте', 'трать' => 'тратьте', 'выводи' => 'выводите', 'проверь' => 'проверьте', 'подумай' => 'подумайте',
                          'хочешь' => 'хотите', 'хочешься' => 'хотите', 'захочешь' => 'захотите',
                          'ешь' => 'едите', 'лишь' => 'лишь', 'тишь' => 'тишь',
                          // существительные и наречия, которые ловились правилами императива
                          'раздел' => 'раздел', 'полей' => 'полей', 'долей' => 'долей', 'запись' => 'запись',
                          'роспись' => 'роспись', 'подпись' => 'подпись', 'надпись' => 'надпись', 'пропись' => 'пропись',
                          'мысль' => 'мысль', 'повесть' => 'повесть', 'пожалуй' => 'пожалуй', 'обойтись' => 'обойтись',
                          'увлечься' => 'увлечься', 'отвлечься' => 'отвлечься', 'ось' => 'ось', 'высь' => 'высь'];
/**
 * Императив единственного числа. Ключи — основы, а не целые слова: русский
 * приставочный императив спрягается так же, поэтому «забери» ловится основой
 * «бери» и даёт «заберите», а «посмотри» — основой «смотри». Метрика корпуса
 * считает императивом только «-йте/-ите», так что без этой правки перевод на
 * «вы» поднимал бы местоимения и оставлял глаголы в прежнем регистре.
 */
/**
 * Слова на «-ай/-яй», которые императивом не являются. Правило для этого
 * окончания взято общим — глаголов на «-ай» в тексте десятки и списком их не
 * закрыть, — а исключения, наоборот, наперечёт, и «случай» среди них главный.
 */
const V5_VY_НЕ_ИМПЕРАТИВ = ['случай', 'сарай', 'трамвай', 'урожай', 'обычай',
    'попугай', 'лишай', 'каравай', 'самурай', 'негодяй', 'нагоняй', 'разгильдяй',
    'полицай', 'пускай', 'китай', 'дунай', 'алтай', 'завсегдатай',
    // Имя героя: банк ИМЯ отдаёт «Николая», и без этой строки правило
    // превращало его в «Николайте» посреди отзыва.
    'николай', 'мамай'];
/** Глагольные приставки: только с ними основа императива считается словом. */
const V5_VY_ПРИСТАВКИ = ['за', 'по', 'про', 'при', 'с', 'у', 'на', 'до', 'от', 'вы',
    'пере', 'раз', 'рас', 'под', 'об', 'из', 'во', 'в', 'со', 'подо', 'ото', 'пред', 'на­'];
/** Служебные слова, которые допустимо пропустить между «вы» и его глаголом. */
const V5_VY_ЗАЗОР = ['не', 'уже', 'ещё', 'еще', 'просто', 'тоже', 'сразу', 'давно',
    'только', 'всегда', 'обычно', 'точно', 'лишь', 'вообще', 'однажды', 'когда-нибудь',
    'когда-то', 'тут', 'там', 'потом', 'сначала', 'вряд', 'ли', 'же', 'бы', 'сам', 'сами'];
/** Краткие формы и «сам»: при «вы» они обязаны стоять во множественном. */
const V5_VY_КРАТКИЕ = ['сам' => 'сами', 'сама' => 'сами', 'готов' => 'готовы',
    'готова' => 'готовы', 'должен' => 'должны', 'должна' => 'должны',
    'обязан' => 'обязаны', 'уверен' => 'уверены', 'прав' => 'правы',
    'рад' => 'рады', 'доволен' => 'довольны', 'согласен' => 'согласны',
    'свободен' => 'свободны', 'знаком' => 'знакомы', 'один' => 'одни',
    'виноват' => 'виноваты', 'застрахован' => 'застрахованы', 'ограничен' => 'ограничены',
    'защищён' => 'защищены', 'защищен' => 'защищены', 'зарегистрирован' => 'зарегистрированы',
    'авторизован' => 'авторизованы', 'подписан' => 'подписаны', 'обязана' => 'обязаны',
    'уверена' => 'уверены', 'права' => 'правы', 'вправе' => 'вправе', 'пристёгнут' => 'пристёгнуты', 'пристегнут' => 'пристегнуты',
    'мог' => 'могли', 'смог' => 'смогли', 'хотел' => 'хотели', 'хотела' => 'хотели'];
const V5_VY_ИМПЕРАТИВ = ['заходи', 'смотри', 'читай', 'проверь', 'открой', 'загляни',
                         'сверь', 'начни', 'держи', 'считай', 'выбирай', 'помни',
                         'следи', 'бери', 'жми', 'играй', 'пиши', 'сравни', 'ищи',
                         'зайди', 'лови', 'ставь', 'жди', 'укажи', 'введи', 'выбери',
                         'получи', 'изучи', 'реши', 'узнай', 'сохрани', 'учти', 'будь', 'пробуй',
                         'сравнивай', 'решай', 'закинь', 'подтверди', 'заведи', 'настрой',
                         'бирай', 'ставь', 'дай', 'делай', 'думай', 'знай', 'слушай',
                         'спроси', 'крути', 'клади', 'меняй', 'веди', 'ходи', 'носи',
                         'иди', 'войди', 'найди', 'закрой', 'глянь', 'строй', 'бросай', 'кидай', 'спеши', 'сиди', 'беги', 'верь', 'установи', 'смотри', 'жми', 'пополни', 'пройди', 'выведи', 'внеси',
                         // короткие императивы, не покрытые общими окончаниями: «не лезь», «не тяни», «запусти»
                         'лезь', 'тяни', 'запусти', 'отпусти', 'уточни', 'отключи', 'включи', 'заполни', 'восстанови', 'защити', 'рискни', 'верни', 'обнови',
                         'оцени', 'выйди', 'положи', 'спи', 'тормози', 'успей', 'пойми', 'вводи', 'заводи', 'проси',
                         'готовь', 'займи', 'оставь', 'заскочи', 'упусти', 'извини', 'подсекай',
                         'пропусти', 'залей', 'привяжи', 'смени', 'очисти', 'лей', 'гони', 'создай', 'заведи', 'обнови', 'сохрани'];

// Императивы, которых нет в V5_VY_ИМПЕРАТИВ. Список там общий: его же читает
// чистка штампов в генераторе, и расширение того списка сдвигало объём страниц
// (words и sections на восьми сидах). Поэтому добор живёт отдельно и виден
// только переводу на «вы».
const V5_VY_ИМПЕРАТИВ_ДОП = ['лети', 'забери', 'успей', 'скачай', 'активируй', 'сыграй',
                            'оцени', 'посмотри', 'попробуй', 'заверши', 'подбери', 'отыграй', 'соблюдай'];

function v5NaVy(string $кусок): string
{
    $правка = static function (string $слово): string {
        $низ = mb_strtolower($слово, 'UTF-8');
        if (isset(V5_VY_ИСКЛЮЧЕНИЯ[$низ])) { return V5_VY_ИСКЛЮЧЕНИЯ[$низ]; }
        if (isset(V5_VY_МЕСТОИМЕНИЯ[$низ])) { return V5_VY_МЕСТОИМЕНИЯ[$низ]; }
        if (mb_strlen($низ) >= 5 && in_array(mb_substr($низ, -2), ['ай', 'яй', 'уй'], true)
            && !in_array($низ, V5_VY_НЕ_ИМПЕРАТИВ, true)) {
            return $низ . 'те';
        }
        foreach (array_merge(V5_VY_ИМПЕРАТИВ, V5_VY_ИМПЕРАТИВ_ДОП) as $основа) {
            if (mb_substr($низ, -mb_strlen($основа)) !== $основа) { continue; }
            // Остаток слева обязан быть глагольной приставкой, иначе основа
            // «будь» ловится в «когда-нибудь», а «бери» — в чём угодно.
            $приставка = mb_substr($низ, 0, mb_strlen($низ) - mb_strlen($основа));
            if ($приставка === '' || in_array($приставка, V5_VY_ПРИСТАВКИ, true)) {
                return $низ . 'те';
            }
        }
        foreach (['ешься' => 'етесь', 'ёшься' => 'ётесь', 'ишься' => 'итесь',
                  'ешь' => 'ете', 'ёшь' => 'ёте', 'ишь' => 'ите'] as $от => $до) {
            if (mb_substr($низ, -mb_strlen($от)) === $от && mb_strlen($низ) > mb_strlen($от) + 1) {
                return mb_substr($низ, 0, mb_strlen($низ) - mb_strlen($от)) . $до;
            }
        }
        // Возвратный императив: «регистрируйся» → «регистрируйтесь». Проверка
        // идёт ПОСЛЕ общих окончаний: «боишься» тоже кончается на «-ься», и
        // раньше них это правило давало «боишьтесь» вместо «боитесь».
        // «учиться» и «сдались» под правило не попадают: инфинитив на «-ться»
        // и прошедшее на «-лись» — не императив.
        if (mb_strlen($низ) >= 5 && mb_substr($низ, -4) !== 'ться' && mb_substr($низ, -4) !== 'чься' && mb_substr($низ, -4) !== 'тись'
            && !preg_match('~(?:щ|вш|ш)(?:ий|ей|ая|ую|ем|им|их|ие)ся$~u', $низ)) {
            foreach (['йся' => 'йтесь', 'ься' => 'ьтесь'] as $от => $до) {
                if (mb_substr($низ, -3) === $от) {
                    return mb_substr($низ, 0, -3) . $до;
                }
            }
            if (mb_substr($низ, -3) === 'ись' && mb_substr($низ, -4, 1) !== 'л') {
                return mb_substr($низ, 0, -3) . 'итесь';
            }
        }
        return $слово;
    };
    // «готов(а)», «сам(а)», «выиграл(а)» — на «вы» скобка не нужна: готовы, сами, выиграли.
    $кусок = (string) preg_replace_callback('~(?<![а-яё])([а-яёА-ЯЁ]+)\(а\)~u', function ($m) {
        $н = mb_strtolower($m[1]);
        // Глагол с «(а)» относится к герою («Как Борис отыграл(а)») — мужской род, не множественное.
        $итог = $н === 'готов' ? 'готовы' : ($н === 'сам' ? 'сами' : $н);
        return preg_match('~^\p{Lu}~u', $m[1]) ? mb_strtoupper(mb_substr($итог, 0, 1)) . mb_substr($итог, 1) : $итог;
    }, $кусок);
    // «проблема не в тебе» → «не в вас»: после предлога — предложный, не дательный.
    $кусок = (string) preg_replace('~(?<![а-яё])(в|во|о|об|обо|на|при)\s+тебе(?![а-яё])~ui', '$1 вас', $кусок);
    $кусок = preg_replace_callback('~(?<![а-яёА-ЯЁ])[а-яёА-ЯЁ]{2,}(?![а-яёА-ЯЁ])~u',
        function ($m) use ($правка) {
            $новое = $правка($m[0]);
            if ($новое === $m[0]) { return $m[0]; }
            // «НЕ ЗАХОДИ, ЕСЛИ БОИШЬСЯ!» остаётся капсом: «НЕ Заходите, ЕСЛИ Боитесь» читалось поломкой.
            if (mb_strlen($m[0]) >= 3 && mb_strtoupper($m[0]) === $m[0]) { return mb_strtoupper($новое); }
            // Заглавная в начале предложения остаётся заглавной.
            return preg_match('~^\p{Lu}~u', $m[0])
                ? mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1) : $новое;
        }, $кусок);
    // Согласование соседей. Пословная замена даёт «помнил вы сам»: прошедшее
    // время и краткие формы стоят при «ты» в единственном числе и обязаны
    // уехать во множественное вслед за местоимением.
    // Между местоимением и глаголом обычно стоит наречие («ты когда-нибудь
    // думал»), поэтому зазор в два служебных слова допускается; список
    // закрытый, иначе правило дотянется до чужого подлежащего.
    $зазор = '(?:\s+(?:' . implode('|', V5_VY_ЗАЗОР) . ')){0,2}';
    $перед = '(?<![а-яё])((?:вы|сами|[а-яё]+(?:йте|ите|ьте|тесь))' . $зазор . '\s+)';
    foreach (V5_VY_КРАТКИЕ as $ед => $мн) {
        $кусок = (string) preg_replace('~' . $перед . $ед . '(?![а-яё])~ui', '$1' . $мн, $кусок);
        $кусок = (string) preg_replace('~(?<![а-яё])' . $ед . '(\s+вы)(?![а-яё])~ui',
            $мн . '$1', $кусок);
    }
    // «зашёл» во множественном теряет «ё»: «зашли», а не «зашёли». У прочих
    // основ на «-ёл» беглая гласная переходит в «е»: «привёл» → «привели».
    $мн = static fn(string $основа, string $хвост): string => $хвост === 'ёл'
        ? (mb_substr($основа, -1) === 'ш' ? mb_substr($основа, 0, -1) . 'шли' : $основа . 'ели')
        : $основа . 'ли';
    // «А если готов играть — смотрите новости»: краткая форма стоит без
    // местоимения, антецедента у неё нет, и по соседству её не поймать. Но
    // после «если/раз/когда» она всегда об читателе — третье лицо потребовало
    // бы местоимения между союзом и формой.
    $союзы = '(?<![а-яё])((?:если|раз|когда|пока|чтобы|коли)\s+(?:не\s+)?)';
    foreach (V5_VY_КРАТКИЕ as $одна => $много) {
        if (in_array($одна, ['сам', 'сама', 'один'], true)) { continue; }
        $кусок = (string) preg_replace('~' . $союзы . $одна . '(?![а-яё])~ui', '$1' . $много, $кусок);
    }
    // «вы собирался» → «вы собирались»: возвратное прошедшее идёт тем же путём.
    // «Хотите сначала разобраться»: наречие на «-ла» — не глагол.
    $неГлагол = '(?!(?:' . implode('|', V5_VY_ЗАЗОР) . '|дела|тела|мало|около|после|пока|зала|стола|была|было|начала|сначала|правила|числа|сила|мила|раздел|отдел|предел|узел|канал|финал|капитал|стол|пол|угол|металл|орёл|котёл|штрек|пепел|цикл|зеркало|крыло|стекло|кресло|масло|тепло|весло|сало|мыло|ремесло|одеяло)(?![а-яё]))';
    $кусок = (string) preg_replace_callback('~' . $перед . $неГлагол . '([а-яё]{2,}?)(ёл|л[ао]?)(ся)?(?![а-яё])~ui',
        fn($m) => $m[1] . $мн($m[2], $m[3]) . (($m[4] ?? '') !== '' ? 'сь' : ''), $кусок);
    $кусок = (string) preg_replace_callback('~(?<![а-яё])([а-яё]{2,}?)(ёл|л[ао]?)(ся)?(\s+вы)(?![а-яё])~ui',
        fn($m) => $мн($m[1], $m[2]) . ($m[3] !== '' ? 'сь' : '') . $m[4], $кусок);
    // «вы остались и поиграл подольше», «прошли верификацию и не нарушал»: второй глагол после «и»
    // идёт тем же числом, что первый.
    $кусок = (string) preg_replace_callback('~(?<![а-яё])([а-яё]+ли(?:сь)?(?:\s+[а-яё]+){0,2}\s+и\s+(?:не\s+)?)' . $неГлагол . '([а-яё]{2,}?)(ёл|л[ао]?)(ся)?(?![а-яё])~ui',
        fn($m) => $m[1] . $мн($m[2], $m[3]) . (($m[4] ?? '') !== '' ? 'сь' : ''), $кусок);
    // Краткая форма без местоимения об читателе: «Готов проверить удачу?»,
    // «которую готов потерять», «не готов — закрой вкладку», «Готов(а) — заходите».
    // Третье лицо здесь всегда с подлежащим («кто готов», «он готов», «Тимур сам
    // скажет»), поэтому запрет — на предыдущее слово.
    $неЧитатель = '(?<!кто )(?<!он )(?<!она )(?<!тот )(?<!каждый )(?<!игрок )(?<!человек )(?<!партнёр )(?<!автомат )(?<!сайт )(?<!казино )(?<!сервис )(?<!бренд )(?<!кабинет )(?<!клуб )(?<!куш )(?<!один )(?<!был )(?<!я )(?<!«я )(?<!уже )(?<!всегда )';
    $кусок = (string) preg_replace('~(?<![а-яё])' . $неЧитатель . 'готов(?:\(а\))?(?![а-яё])~u', 'готовы', $кусок);
    $кусок = (string) preg_replace('~(?<![а-яё])' . $неЧитатель . 'Готов(?:\(а\))?(?![а-яё])~u', 'Готовы', $кусок);
    // «проверить сам», «прочувствуй атмосферу сам» — «сам» об читателе стоит
    // после инфинитива или императива во множественном; после имени или «он» — нет.
    $кусок = (string) preg_replace_callback('~(?<![а-яё])([А-ЯЁа-яё]+)(\s+)сам(?![а-яё])~u', function ($m) {
        $слово = mb_strtolower($m[1]);
        if (preg_match('~^[А-ЯЁ]~u', $m[1]) || in_array($слово, ['он', 'кто', 'каждый', 'игрок', 'тот', 'который', 'человек', 'партнёр'], true)) { return $m[0]; }
        return preg_match('~(?:ть|ться|чь|йте|ите|ьте|тесь|ете|ёте)$~u', $слово) ? $m[1] . $m[2] . 'сами' : $m[0];
    }, $кусок);
    // То же через дополнение: «проверить всё сам», «прочувствуйте атмосферу сам».
    // После инфинитива или императива во множественном «сам» через одно слово — всегда о читателе.
    $кусок = (string) preg_replace('~(?<![а-яё])([а-яё]+(?:ть|ться|чь|йте|ите|ьте|тесь))((?:\s+[а-яё]+){1,2})(\s+)сам(?![а-яё])~u', '$1$2$3сами', $кусок);
    // Идиома «как ни крути» — не императив.
    $кусок = (string) preg_replace('~(?<![а-яё])(как ни) крутите(?![а-яё])~ui', '$1 крути', $кусок);
    // «проходите один раз» → «одни раз»: краткая форма «один» не о читателе, когда после неё «раз».
    $кусок = (string) preg_replace('~(?<![а-яё])одни(\s+раз)(?![а-яё])~ui', 'один$1', $кусок);
    // «аккаунт готовы», «кто понимает риски и готовы»: подлежащее — не читатель.
    $кусок = (string) preg_replace('~(?<![а-яё])(аккаунт|счёт|профиль|бонус|вывод|пакет|код|доступ|сайт|слот|автомат|турнир|результат|итог|вечер|клиент)(\s+(?:уже\s+|не\s+)?)готовы(?![а-яё])~ui', '$1$2готов', $кусок);
    $кусок = (string) preg_replace('~(?<![а-яё])(кто\s+(?:[а-яё]+\s+){0,4})готовы(?![а-яё])~ui', '$1готов', $кусок);
    // «пока вы сами отдашь» → «отдадите»: у «дать» личная форма не на «-ешь».
    $кусок = (string) preg_replace('~(?<![а-яё])(от|про|пере|соз|с|по|за|у|раз|под|вы)?дашь(?![а-яё])~ui', '$1дадите', $кусок);
    // «если забыл пароль», «раз решил» — условие о читателе, а не о герое: герой стоит между «если» и глаголом.
    $кусок = (string) preg_replace_callback('~(?<![а-яё])([Ее]сли|[Кк]огда|[Рр]аз)\s+(?:вдруг\s+|уже\s+)?(забыл|потерял|решил|зашёл|выиграл|проиграл|передумал|устал|понял)(?![а-яё])~u',
        fn($m) => $m[1] . ' ' . (str_contains($m[0], 'вдруг') ? 'вдруг ' : (str_contains($m[0], 'уже') ? 'уже ' : '')) . ['забыл' => 'забыли', 'потерял' => 'потеряли', 'решил' => 'решили', 'зашёл' => 'зашли', 'выиграл' => 'выиграли', 'проиграл' => 'проиграли', 'передумал' => 'передумали', 'устал' => 'устали', 'понял' => 'поняли'][$m[2]], $кусок);
    // «вы за час сменил», «вы его застал»: прошедшее после «вы» с дополнением между ними.
    $кусок = (string) preg_replace_callback('~(?<![а-яё])(вы\s+(?:его|её|их|это|сами|тоже|уже|ещё|не|за\s+[а-яё]+)\s+(?:не\s+)?)' . $неГлагол . '([а-яё]{2,}?)(ёл|л[ао]?)(ся)?(?![а-яё])~ui',
        fn($m) => $m[1] . $мн($m[2], $m[3]) . (($m[4] ?? '') !== '' ? 'сь' : ''), $кусок);
    return $кусок;
}

/**
 * Обратный перевод — «вы» → «ты» для «ты»-набора. Записи с «вы»-императивами
 * («Не отыгрывайтесь и остановитесь») попадали в «ты»-страницу как есть.
 * Правятся местоимения, императивы на -йте/-ьте/-йтесь/-ьтесь/-итесь и
 * личные формы на -ете/-ёте; «-ите» — только не после предлога и не у
 * существительных («на сайте», «в лимите», «о депозите»).
 */
const V5_TY_МЕСТОИМЕНИЯ = ['вы' => 'ты', 'вас' => 'тебя', 'вам' => 'тебе', 'вами' => 'тобой',
    'ваш' => 'твой', 'ваша' => 'твоя', 'ваше' => 'твоё', 'ваши' => 'твои', 'вашего' => 'твоего',
    'вашей' => 'твоей', 'вашему' => 'твоему', 'вашим' => 'твоим', 'вашими' => 'твоими',
    'ваших' => 'твоих', 'вашу' => 'твою', 'вашем' => 'твоём', 'сами' => 'сам'];
const V5_TY_НЕ_ГЛАГОЛ = ['сайте' => 1, 'лимите' => 1, 'депозите' => 1, 'кредите' => 1, 'визите' => 1,
    'аудите' => 1, 'ките' => 1, 'орбите' => 1, 'элите' => 1, 'граните' => 1, 'магните' => 1,
    'реквизите' => 1, 'бите' => 1, 'ките' => 1, 'суите' => 1, 'сателлите' => 1, 'колорите' => 1,
    'паразите' => 1, 'фаворите' => 1, 'дефиците' => 1, 'профиците' => 1, 'опыте' => 1, 'бюджете' => 1,
    'защите' => 1, 'комплекте' => 1, 'паркете' => 1, 'банкете' => 1, 'планшете' => 1, 'транзите' => 1, 'кабинете' => 1,
    'интернете' => 1, 'билете' => 1, 'монете' => 1, 'планете' => 1, 'ракете' => 1, 'диете' => 1, 'пакете' => 1, 'букете' => 1, 'приоритете' => 1, 'тильте' => 1, 'свите' => 1, 'корте' => 1, 'сорте' => 1, 'борте' => 1, 'чарте' => 1, 'старте' => 1, 'аккаунте' => 1];

/** Предложения записи (от пяти слов) и её начало (три слова) — ключи повтора на странице. */
function v5KlyuchiPovtora(string $t): array
{
    $чист = mb_strtolower(preg_replace('~\s+~u', ' ', strip_tags($t)));
    $ключи = [];
    foreach (preg_split('~(?<=[.!?])\s+~u', $чист) as $пр) {
        $слова = preg_split('~[^\p{L}\d{}]+~u', $пр, -1, PREG_SPLIT_NO_EMPTY);
        if (count($слова) >= 5) { $ключи[] = implode(' ', $слова); }
    }
    $слова = preg_split('~[^\p{L}\d{}]+~u', $чист, -1, PREG_SPLIT_NO_EMPTY);
    if (count($слова) >= 3) { $ключи[] = '^' . implode(' ', array_slice($слова, 0, 3)); }
    return $ключи;
}

// Зачины-вопросы на «вы» без местоимения: «Ищете слот без сказок?» — в
// «ты»-наборе они переводятся и без «вы» рядом.
const V5_TY_ЗАЧИНЫ = ['ищете' => 'ищешь', 'хотите' => 'хочешь', 'думаете' => 'думаешь', 'знаете' => 'знаешь',
    'любите' => 'любишь', 'планируете' => 'планируешь', 'мечтаете' => 'мечтаешь', 'ждёте' => 'ждёшь',
    'играете' => 'играешь', 'боитесь' => 'боишься', 'сомневаетесь' => 'сомневаешься', 'надеетесь' => 'надеешься',
    'верите' => 'веришь', 'считаете' => 'считаешь', 'решаете' => 'решаешь', 'можете' => 'можешь', 'готовы' => 'готов',
    'задумывались' => 'задумывался', 'слышали' => 'слышал', 'услышите' => 'услышишь', 'помните' => 'помнишь', 'хотели' => 'хотел', 'видели' => 'видел'];

// Личные формы и императивы на «-ите», которые триггер перекрута по «-йте/-ьте» не
// ловит: «смотрите не на баннер», «что получите и чем рискуете», «идите в депозит».
// У донора A их 5 на набор, у нас было 15.
const V5_TY_ЛИЧНЫЕ = ['смотрите' => 'смотри', 'получите' => 'получишь', 'забираете' => 'забираешь', 'нажмите' => 'нажми',
    'идите' => 'иди', 'изучите' => 'изучи', 'пропустите' => 'пропусти', 'рискуете' => 'рискуешь', 'узнаёте' => 'узнаёшь',
    'предпочитаете' => 'предпочитаешь', 'заберите' => 'забери', 'установите' => 'установи', 'начните' => 'начни',
    'следите' => 'следи', 'держите' => 'держи', 'берите' => 'бери', 'помните' => 'помни', 'любите' => 'любишь',
    'играете' => 'играешь', 'выводите' => 'выводишь', 'заходите' => 'заходи', 'хотите' => 'хочешь', 'можете' => 'можешь',
    'привлекаете' => 'привлекаешь', 'получаете' => 'получаешь', 'выбираете' => 'выбираешь', 'ставите' => 'ставишь',
    'понимаете' => 'понимаешь', 'теряете' => 'теряешь', 'делаете' => 'делаешь', 'читаете' => 'читаешь',
    'начинаете' => 'начинаешь', 'проверяете' => 'проверяешь', 'тестируете' => 'тестируешь', 'приводите' => 'приводишь', 'ждите' => 'жди', 'боитесь' => 'боишься', 'ищете' => 'ищешь',
    'слышали' => 'слышал', 'услышите' => 'услышишь', 'задумывались' => 'задумывался', 'считаете' => 'считаешь', 'обращайтесь' => 'обращайся',
    'ставьте' => 'ставь', 'выбирайте' => 'выбирай', 'читайте' => 'читай', 'откройте' => 'открой', 'проверяйте' => 'проверяй', 'решайте' => 'решай', 'заходите' => 'заходи', 'считайте' => 'считай'];

function v5NaTy(string $кусок, bool $императивы = true): string
{
    $предлог = '~(?:^|[^а-яё])(?:на|в|во|о|об|обо|при|по|к|ко|от|до|из|у|за|со|с)\s+$~ui';
    $итог = (string) preg_replace_callback('~(?<![а-яёА-ЯЁ])[а-яёА-ЯЁ]{2,}(?![а-яёА-ЯЁ])~u',
        function ($m) use ($кусок, $предлог, $императивы) {
            $низ = mb_strtolower($m[0]);
            $новое = null;
            if (isset(V5_TY_МЕСТОИМЕНИЯ[$низ])) { $новое = V5_TY_МЕСТОИМЕНИЯ[$низ]; }
            elseif (isset(V5_TY_ЛИЧНЫЕ[$низ])) { $новое = V5_TY_ЛИЧНЫЕ[$низ]; }
            elseif ($низ === 'готовы' && preg_match('~(?<![а-яё])(?:если|которой|которую|когда|вы)\s+(?:[а-яё]+\s+)?$~ui', mb_substr($кусок, 0, (int) mb_strpos($кусок, $m[0])))) { $новое = 'готов'; }
            elseif (isset(V5_TY_ЗАЧИНЫ[$низ]) && preg_match('~^\p{Lu}~u', $m[0])) { $новое = V5_TY_ЗАЧИНЫ[$низ]; }
            elseif (mb_strlen($низ) >= 5 && !isset(V5_TY_НЕ_ГЛАГОЛ[$низ])) {
                foreach (['йтесь' => 'йся', 'ьтесь' => 'ься', 'итесь' => 'ись', 'йте' => 'й', 'ьте' => 'ь',
                          'етесь' => 'ешься', 'ётесь' => 'ёшься', 'ете' => 'ешь', 'ёте' => 'ёшь'] as $от => $до) {
                    // Вежливый императив («проверьте», «не забудьте») — норма и
                    // «ты»-страницы доноров (189 «проверьте» в корпусе, поле
                    // imperatives считает именно их); переводится только по флагу.
                    if (!$императивы && !in_array($от, ['ете', 'ёте', 'етесь', 'ётесь'], true)) { continue; }
                    if (mb_substr($низ, -mb_strlen($от)) === $от) {
                        // «-ете» у существительных: «в комплекте», «на паркете» — только после «вы».
                        if (in_array($от, ['ете', 'ёте'], true)) {
                            $до_ = mb_substr($кусок, 0, (int) mb_strpos($кусок, $m[0]));
                            if (!preg_match('~(?<![а-яё])вы\s+(?:[а-яё]+\s+){0,2}$~ui', $до_)) { break; }
                        }
                        $новое = mb_substr($низ, 0, -mb_strlen($от)) . $до; break;
                    }
                }
                if ($новое === null && mb_substr($низ, -3) === 'ите' && !isset(V5_TY_НЕ_ГЛАГОЛ[$низ])) {
                    $до_ = mb_substr($кусок, 0, (int) mb_strpos($кусок, $m[0]));
                    $послеВы = (bool) preg_match('~(?<![а-яё])вы\s+(?:[а-яё]+\s+){0,2}$~ui', $до_);
                    if (!preg_match($предлог, $до_) && ($императивы || $послеВы)) {
                        // После «вы» — личная форма («вы говорите» → «говоришь»), иначе императив.
                        $новое = mb_substr($низ, 0, -3) . (preg_match('~(?<![а-яё])вы\s+(?:[а-яё]+\s+){0,2}$~ui', $до_) ? 'ишь' : 'и');
                    }
                }
            }
            if ($новое === null || $новое === $низ) { return $m[0]; }
            return preg_match('~^\p{Lu}~u', $m[0]) ? mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1) : $новое;
        }, $кусок);
    // «будьте честны» → «будь честен»: краткое прилагательное тоже меняет число.
    $итог = (string) preg_replace('~(?<![а-яё])([Бб]удь)\s+честны(?![а-яё])~u', '$1 честен', $итог);
    $итог = (string) preg_replace('~(?<![а-яё])([Бб]удь)\s+готовы(?![а-яё])~u', '$1 готов', $итог);
    // «чтобы вы могли» → «чтобы ты могли»: после «ты» множественное прошедшее и краткие формы — в единственное.
    static $ед = ['могли' => 'мог', 'смогли' => 'смог', 'хотели' => 'хотел', 'решили' => 'решил', 'забыли' => 'забыл',
        'зашли' => 'зашёл', 'выиграли' => 'выиграл', 'проиграли' => 'проиграл', 'видели' => 'видел', 'знали' => 'знал',
        'готовы' => 'готов', 'сами' => 'сам', 'должны' => 'должен', 'уверены' => 'уверен'];
    return (string) preg_replace_callback('~(?<![а-яё])(ты)\s+(' . implode('|', array_keys($ед)) . ')(?![а-яё])~u',
        fn($m) => $m[1] . ' ' . $ед[$m[2]], $итог);
}

/**
 * Регистр обращения — свойство площадки, а не страницы. Из 76 разобранных
 * комплектов на «вы» пишут одиннадцать, и внутри такого комплекта «вы»
 * держится на всех двенадцати типах, меняется только плотность; «ты» при
 * этом никуда не девается — на registracia его у них вдвое больше, чем
 * «вы». Поэтому регистр выбирается один раз на набор.
 *
 * Раскладка идёт по НОМЕРУ набора, а не по сиду. Прежний ключ — crc32 от
 * сида — сам по себе честен: на шести использованных блоках он даёт 12.8%
 * «вы» при ожидаемых 14.3%, а «вы»-набор проходит приёмку не хуже «ты»
 * (замер на 14 сидах: полных 4/14 против 3/14, страниц 11.00 против 11.14).
 * Плох он другим: в партии из пяти наборов доля — лотерея, и партия 264–268
 * вышла целиком на «ты». Номер набора не лотерея: каждый седьмой — «вы»,
 * ровно 14.3%, и это видно и проверяемо в любой партии.
 *
 * Сид остаётся запасным ключом для безымянных прогонов (A/B, замеры).
 */
function v5ObrashchenieNabora(int $сид, string $имя = ''): string
{
    if (preg_match('~(\d+)$~', $имя, $m)) {
        return (int) $m[1] % 7 === 0 ? 'вы' : 'ты';
    }
    return $сид > 0 && crc32('обращение|' . $сид) % 7 === 0 ? 'вы' : 'ты';
}

/**
 * Подмена целей регистра для «вы»-набора. Абсолютные числа образцов
 * недостижимы: обращений на странице у них 20–43, у нас около двенадцати, а
 * перевод «ты» → «вы» этой суммы не меняет. Достижима доля — её и держим,
 * полем `vy_share`, где оба регистра считаются местоимениями и потому
 * сравнимы между собой.
 *
 * Поля `vy`, `ty` и `imperatives` получают числа подгруппы для отчёта, но
 * держать их нельзя: `vy` в базовом профиле стоит нулём (корпус доноров
 * пишет на «ты»), и «вы»-набор проваливал бы его при любом переводе.
 */
/**
 * Абзацы страницы как очередь блоков. Строка у нас — не абзац: абзац разложен
 * на несколько строк, и перевод одной из них даёт ровно тот брак, ради
 * которого всё и затевалось («Хочешь деталей? Выполняйте регистрацию»).
 * Заголовки, кнопки и разметка виджетов в блок не входят: закрывающий тег
 * абзаца стоит в конце текстовой строки, и по «следующему открывающему» блок
 * растягивался бы на полстраницы вместе с h2.
 *
 * Возвращает список блоков: «пер» — строки, которые имеет смысл переводить
 * (от двенадцати знаков), «все» — все строки блока.
 */
function v5OcheredAbzatsev(array $строки): array
{
    $очередь = []; $текущий = []; $текущийВсе = []; $внутри = false;
    $закрыть = function () use (&$очередь, &$текущий, &$текущийВсе) {
        if ($текущий) { $очередь[] = ['пер' => $текущий, 'все' => $текущийВсе]; }
        $текущий = []; $текущийВсе = [];
    };
    foreach ($строки as $н => $строка) {
        $t = ltrim($строка);
        if ($t === '') { continue; }
        $тег = $t[0] === '<' && !str_starts_with($t, '<strong>');
        if ($тег && preg_match('~^<(p|li|td|dd|blockquote)\b~i', $t)) { $закрыть(); $внутри = true; }
        elseif ($тег) {
            if (preg_match('~^</(p|li|td|dd|blockquote)\b~i', $t)) { $закрыть(); $внутри = false; }
            continue;
        }
        if ($внутри) { $текущийВсе[] = $н; }
        if (mb_strlen($t) >= 12) { $текущий[] = $н; }
        if ($внутри && preg_match('~</(p|li|td|dd|blockquote)>~i', $строка)) { $закрыть(); $внутри = false; }
    }
    $закрыть();
    return $очередь;
}

/**
 * Смешана ли эта страница «ты»-набора. У корпуса смесь не сплошная и не
 * случайная по абзацам: часть страниц набора идёт чистым «ты», часть держит
 * заметную долю «вы». Доля смешанных страниц своя у каждого типа — от 31 % на
 * registracia до 81 % на bonus, — и розыгрыш по сиду набора эту долю
 * воспроизводит. Сид нулевой (старые наборы, разовые прогоны) — смеси нет.
 */
function v5StranitsaSoSmesyu(array $профиль, string $тип, int $сид): bool
{
    if ($сид <= 0) { return false; }
    $доля = (float) ($профиль['обращение_ты']['типы'][$тип]['доля_смешанных'] ?? 0);
    if ($доля <= 0.0) { return false; }
    return (crc32('смесь|' . $тип . '|' . $сид) % 100) < $доля;
}

function v5PoliaObrashcheniya(array $поля, array $профиль, string $тип,
                              string $обращение, array $карта = [], int $сид = 0): array
{
    if ($обращение !== 'вы') {
        // «Ты»-набор без вежливых форм: императивы на -йте/-ите/-ьте не держим.
        if (isset($поля['imperatives'])) { $поля['imperatives']['держат'] = false; }
        // Поле vy снято с двенадцати доноров, и полоса у него [0,0]–[0,2] —
        // смесь оно запрещает прямо. Корпус из 102 наборов говорит обратное:
        // из 45 «ты»-наборов монолитных только 10, у остальных «вы» держится
        // в части страниц (медиана по набору 6.5 %, 48 % страниц со смесью).
        // Регистр «ты»-набора ведётся той же долей, что и «вы»-набора.
        if (isset($поля['vy'])) { $поля['vy']['держат'] = false; }
        $ц = v5StranitsaSoSmesyu($профиль, $тип, $сид)
            ? (float) ($профиль['обращение_ты']['типы'][$тип]['vy_share_на_смешанной'] ?? 0.0)
            : 0.0;
        // Долю приёмка у «ты»-набора не держит: на странице с десятком
        // обращений одно местоимение — это восемь процентов, и любая полоса
        // здесь либо пропускает всё, либо валит набор на округлении. Цель
        // остаётся рычагом перекрута, а проверяет её замер по набору.
        $поля['vy_share'] = [
            'подпись' => 'доля «вы» среди обращений, %',
            'цель'    => $ц,
            'дробное' => true,
            'держат'  => false,
            'полоса'  => [0.0, max(1.0, $ц * 2)],
            'край'    => [0.0, max(1.0, $ц * 2)],
        ];
        return $поля;
    }
    $цели = $профиль['обращение_вы']['типы'][$тип] ?? null;
    if (!$цели || !isset($цели['vy_share'])) { return $поля; }
    foreach (['vy', 'ty', 'imperatives'] as $ключ) {
        if (!isset($поля[$ключ], $цели[$ключ])) { continue; }
        $поля[$ключ]['цель'] = (float) $цели[$ключ];
        // Ни одно из трёх счётом не держим. Базовый профиль запрещает «вы» на
        // всех типах и императивы на promo и slots, а «вы»-подгруппа пишет
        // там и то и другое: две цели прямо противоречат друг другу, и
        // держать обе нельзя. Регистр держится долей — vy_share, — а эти
        // числа остаются ориентиром для рычагов перекрута и для отчёта.
        $поля[$ключ]['держат'] = false;
    }
    // Страница почти без обращений — регистру не на чем проявиться, и
    // требовать доли значит требовать вписать «вы» туда, где его нет.
    if ((int) ($карта['address_total'] ?? 0) < 4) { return $поля; }
    // Доля «вы» — та, что у образцов подгруппы: 43.9 % на main, 73.7 % на obzor,
    // 45 % на promo. Раньше здесь стояло 100 % («один регистр на набор»), и
    // «вы»-набор выходил переводом, а не смесью. Корпус из 102 наборов говорит
    // обратное: у «вы»-набора «ты» держится в 36–41 % обращений, в 96 % h2 и в
    // 43 % абзацев, и смешаны регистры на 11 страницах из 12. Полоса шире
    // прежней: при десятке местоимений на страницу одно «ты» — это десять
    // процентов доли, и узкая полоса заставляла дожимать страницу до конца.
    $ц = (float) $цели['vy_share'];
    $полуполоса = 15.0;
    $поля['vy_share'] = [
        'подпись' => 'доля «вы» среди обращений, %',
        'цель'    => $ц,
        'дробное' => true,
        'держат'  => true,
        'полоса'  => [max(0.0, $ц - $полуполоса), min(100.0, $ц + $полуполоса)],
        'край'    => [max(0.0, $ц - $полуполоса), min(100.0, $ц + $полуполоса)],
    ];
    return $поля;
}

/**
 * Чужая метафорическая шкура. Один донор писал всю площадку в королевских
 * образах — трон, скипетр, корона, дворец, — другой в кладоискательских.
 * Внутри своего набора это цельный приём, но в общем пуле фразы разъезжаются
 * по чужим комплектам, и «условия отыгрыша — это страж у врат сокровищницы»
 * оказывается в тексте про бонусы рядом с обычной прозой.
 *
 * Замер: такой лексики у нас 1.24 на страницу против 0.90 у конкурента и
 * 0.53 у доноров, и весь перевес — на этих фразах.
 *
 * Третья шкура — подводная: Атлантида, жемчуг, затонувший клад, погружение
 * за сокровищами. В пулах её 215 записей (0,24 %), и в чужом наборе она
 * читается так же чужеродно: «Готовы нырнуть за своим главным сокровищем?»
 * посреди страницы про верификацию.
 *
 * Ловим только существительные шкуры. Прилагательное «королевский» —
 * обычный усилитель («королевский джекпот», «королевская сумма»), его
 * доноры пишут вне всякой сказки, и трогать его нельзя. По той же причине
 * не ловим «глубину» и «подводный»: «без подводных камней» — жанровая
 * идиома, а не сказка, и таких записей в пулах три десятка.
 */
function v5ChuzhayaShkura(string $текст): bool
{
    return (bool) preg_match(
        '~\b(трон[ае]?\b|скипетр\w*|корон[аыуое]\w*|коронаци\w*|дворц\w*|дворец\b'
        . '|королевств\w*|сокровищ\w*|врата\w*|стражник\w*|заклинани\w*'
        . '|колдовств\w*|атлантид\w*|затонувш\w*|русалк\w*'
        . '|нептун\w*|погружени\w*|погрузи\w*|нырну\w*'
        // «жемчуг» ловился, «жемчужный» и «жемчужина» — нет: в корне
        // чередование г→ж. На странице проходил «Наш Жемчужный Бонус».
        . '|жемчуг\w*|жемчуж\w*'
        // Кошачья линейка шла мимо списка целиком: «деньги капают, пока кот
        // ещё мурлычет», «уйдёшь с пустыми лапками». В пулах таких записей
        // было больше, чем жемчужных.
        . '|кот\b|кота\b|коту\b|котом\b|коты\b|котов\b|кошач\w*|кошк\w*'
        . '|лапк\w*|лапах\b|мурлы\w*|мяу\w*|усат\w*'
        // Царская линейка — та же дыра, что была с жемчугом. Фильтр ловил
        // «королевство», «корону» и «трон», но не прилагательное: «королевский
        // дар на старте», «входной билет в королевский зал», «тронный зал для
        // аристократов риска», «дар для новых подданных». На пяти наборах это
        // 15 попаданий в текст, у двенадцати доноров на 144 страницах — ноль.
        // «тронн» обязательно с границей слова: без неё ловится «элекТРОННые
        // кошельки», которых в пулах много.
        . '|королевск\w*|подданн\w*|царск\w*|вельмож\w*'
        . '|придворн\w*|монарх\w*|тронн\w*|величеств\w*'
        // Звериная и морская линейки из вычитки набора 306: «когти», «клубок»,
        // «рифы», «штурвал», «якорь», «гавань», «шторм». У доноров — ноль.
        . '|когт\w*|клубк\w*|клубок\b|риф\b|рифы\b|рифов\b|рифах\b'
        . '|штурвал\w*|якор\w*|гаван\w*|шторм\w*'
        // Рудничная и рыцарская линейки — из чтения набора 563. Эти два мира у
        // нас свои (miry.json), и вписывает их отдельный проход; но те же
        // образы вшиты и в общие записи пула, а они уходят в любой набор.
        // В партии 555–564 это дало 79 рудничных вхождений в наборе с миром
        // «Салун»: «намыть самородок», «уйти с пустым лотком», «карта прииска»
        // посреди ковбойской страницы, — и «поддержка — твои верные оруженосцы»
        // в наборе с миром «Лаборатория». Слово «турнир» не трогаем: турниры у
        // казино настоящие, это не метафора.
        . '|самород\w*|прииск\w*|шурф\w*|штольн\w*|namyt\w*|намы(?:ть|л|ла|ли)\b'
        . '|оруженосц\w*|герольд\w*|копь[её]\b|копи[ийя]\b|рыцар\w*|ристалищ\w*)~ui', $текст);
}

/**
 * Одно начало у двух соседних фраз: «{ИМЯ} однажды зашёл на автомат ради
 * теста…» и «{ИМЯ} однажды зашёл просто проверить…» — фабрика писала пул по
 * одному шаблону, и близость по словам их не ловит. У доноров пар с общим
 * началом 0.1 на сто, у нас было 0.4, а с предпочтением одного донора в
 * абзаце — 0.9. Сравниваются первые два слова без разметки и прорезей.
 */
function v5OdnoNachalo(string $a, string $b): bool
{
    $нач = function (string $t): string {
        $t = mb_strtolower(trim(preg_replace('~\s+~u', ' ', strip_tags($t))));
        preg_match_all('~[\p{L}\p{N}{}:]+~u', $t, $m);
        return implode(" ", array_slice($m[0], 0, 2));
    };
    $x = $нач($a); $y = $нач($b);
    return $x !== '' && mb_substr_count($x, " ") >= 1 && $x === $y;
}

/**
 * Виджет «Прогрессивные джекпоты + Последние выплаты». Трафарет обобщал все
 * рублёвые суммы виджета в {РУБЛИ}, а имена — в {ИМЯ}, и узел заполнял их
 * одним героем и суммами из банка ставок: «МИНИ 16 154 198 ₽» над «МЕГА
 * 125 457 ₽», «Николай» шесть раз подряд, выплата в 16 млн из «обычной»
 * строки. У доноров три джекпота идут по убыванию (16.0 / 4.4 / 0.8 млн),
 * шесть выплат — шесть разных имён, суммы по разряду строки (mega 229–429
 * тыс, big 59–139 тыс, normal 3.8–40 тыс по p10–p90 доноров).
 */
function v5VidzhetVyplat(string $html, Rng $rng, array $герои, array $героини): string
{
    if (!str_contains($html, 'jackpot-cell-amount') && !str_contains($html, 'payout-row')) { return $html; }
    $руб = fn(int $v) => number_format($v, 0, '', ' ') . ' ₽';
    // Диапазоны — по 111 виджетам доноров: МЕГА 15.8–16.4 млн, СУПЕР 4.3–4.6 млн, МИНИ 758–821 тыс.
    $ярусы = [[15_000_000, 17_500_000], [4_000_000, 4_900_000], [700_000, 880_000], [60_000, 150_000]];
    $i = 0;
    $html = preg_replace_callback('~(<span class="jackpot-cell-amount">\s*)([^<]*?)(\s*</span>)~u',
        function ($m) use (&$i, $ярусы, $rng, $руб) {
            [$а, $б] = $ярусы[min($i++, count($ярусы) - 1)];
            return $m[1] . $руб($rng->int($а, $б)) . $m[3];
        }, $html);
    // Доля женских имён в ленте выплат. Замер по 30 чужим наборам: медиана
    // 50 %, полоса 22–67 %. У нас выходило 13 % — лента брала общий список
    // героев, а он в наборе на сорок мужчин и шесть женщин, потому что герой
    // ведёт рассказ, а в рассказах банк такой. Лента — не рассказ, ей нужен
    // свой расклад: имена чередуются, доля разыгрывается на набор.
    $мужские = array_values(array_unique($герои));
    $женские = array_values(array_unique($героини));
    $rng->shuffle($мужские);
    $rng->shuffle($женские);
    $имена = [];
    if ($женские === []) {
        $имена = $мужские;
    } else {
        $доляЖ = $rng->int(30, 60);
        $всего = count($мужские) + count($женские);
        $жи = $ми = 0;
        for ($i = 0; $i < $всего; $i++) {
            $берёмЖ = ($жи * 100) < ($i + 1) * $доляЖ;
            if ($берёмЖ && $женские !== []) { $имена[] = $женские[$жи++ % count($женские)]; }
            else { $имена[] = $мужские[$ми++ % max(1, count($мужские))]; }
        }
    }
    // Лента — не перепись: у чужих в ней 27 разных сумм на 45 строк набора
    // (повтор 1.67), у нас каждая строка несла свою сумму и разных выходило 45
    // при корпусных 45 на весь набор. Имена там же: лента давала 26 разных из
    // общего списка, и вместе с прозой набор выходил на 52 имени при их 40.
    // Роспись набора считается один раз: генератор — один процесс на набор.
    static $роспись = null;
    // По строкам доноров (p10–p90): mega 229–429 тыс, big 59–139 тыс, normal 3.8–40 тыс, jackpot 0.8–2.0 млн.
    $разряд = ['jackpot' => [800_000, 2_000_000], 'mega' => [220_000, 450_000], 'big' => [55_000, 145_000], 'normal' => [3_500, 42_000]];
    if ($роспись === null) {
        $роспись = ['суммы' => [], 'имена' => array_slice($имена, 0, 14)];
        foreach ($разряд as $имяР => [$а, $б]) {
            $роспись['суммы'][$имяР] = [];
            for ($k = 0; $k < 12; $k++) { $роспись['суммы'][$имяР][] = $rng->int($а, $б); }
        }
    }
    $имена = $роспись['имена'] ?: $имена;
    $n = 0;
    return preg_replace_callback('~<div class="payout-row payout-row-(\w+)".*?</div>~su',
        function ($m) use (&$n, $имена, $разряд, $роспись, $rng, $руб) {
            $строка = $m[0];
            [$а, $б] = $разряд[$m[1]] ?? $разряд['normal'];
            $банк = $роспись['суммы'][$m[1]] ?? $роспись['суммы']['normal'];
            $имя = $имена[$n % max(1, count($имена))] ?? '';
            $сумма = $банк[$n % count($банк)];
            $n++;
            if ($имя !== '') {
                $строка = preg_replace('~(<span class="payout-row-name"[^>]*>\s*)([^<]*?)(\s*</span>)~u',
                    '${1}' . $имя . '${3}', $строка, 1);
            }
            return preg_replace('~(<span class="payout-row-amount">\s*)([^<]*?)(\s*</span>)~u',
                '${1}' . $руб($сумма) . '${3}', $строка, 1);
        }, $html);
}

/**
 * Клише в узде. Плотность штампов у A/motor на страницу: «движ для смелых» 2.2,
 * «по-честному» 2.75, «гарантий нет» 2.6, «не заходи» 3.2, «без развода» 0.5,
 * «можно выиграть, можно проиграть» 0.8, «без сказок» 0.75, «холодной головой»
 * 0.2, «сегодня плюс, завтра минус» и «никто ничего не обещает» — 0. У нас в 383
 * было 43 / 52 / 24 / 36 / 38 / 21 / 19 / 14 / 15 / 16 на набор: текст всё время
 * извинялся. Прежняя узда меняла лишний штамп на другой штамп — плотность
 * гуляла по кругу. Теперь лишнее сверх лимита УДАЛЯЕТСЯ вместе со своей
 * пунктуацией: отдельное предложение — целиком, зачин перед двоеточием —
 * с заглавной у следующего слова, хвост после запятой или тире — без хвоста,
 * наречие посреди фразы — просто выпадает. Только там, где удалить нельзя
 * без потери грамматики (именная группа посреди предложения), ставится
 * нейтральная замена, не входящая ни в один штамп.
 *
 * Поля: регулярка (без ограничителей), лимит на страницу, можно ли выбрасывать
 * посреди предложения (наречия — да, именные группы — нет), замены.
 */
const V5_SHTAMPY = [
    // Лимит дробный: целая часть — на каждой странице, дробная — доля страниц с ещё одним.
    // Пересмотр по корпусу N102 (70 полных чужих наборов, медианы на страницу):
    // по-честному 3.6, гарантий нет 1.8, без развода 1.5, без сказок 0.3,
    // «можно выиграть, можно проиграть» 0.5; у нас было 2.4 / 2.6 / 0.8 / 0.8 / 1.3.
    // Лимит «можно выиграть, можно проиграть» оставлен 0.8: при 0.4 main терял
    // «проиграть» из счётчика honest приёмки (21 при цели 37) и падал в 65 % попыток.
    // Замена «по-честному» на «честно» давала 5 «честно» на страницу при их 1.9 — снята.
    // Замены для «движ» мужского рода: «движ тебе понятен» → «драйв тебе понятен».
    ['движ\s+для\s+смелых',                 2.2,  false, ['риск без подушки', 'азарт без страховки', 'драйв на нервах']],
    ['по-честному',                            3.6,  true,  ['прямо', 'без прикрас']],
    ['гарантий\s+(?:здесь\s+|тут\s+)?нет|нет\s+(?:никаких\s+)?гарантий', 2.4, false, ['без гарантий', 'обещать нечего']],
    ['без\s+развода',                          1.2,  true,  ['без обмана', 'без подвоха']],
    ['без\s+сказок',                           0.3, true,  ['без прикрас', 'без красивых слов']],
    ['без\s+магии',                            0.6,  true,  ['без чудес', 'без волшебства']],
    ['(?:с\s+)?холодной\s+головой',            0.2,  true,  ['с трезвым расчётом', 'спокойно']],
    ['сегодня\s+плюс,?\s+завтра\s+минус',     0.0,  false, ['итог не задан заранее', 'результат гуляет']],
    ['никто\s+ничего\s+не\s+обещает|обещаний\s+(?:тут|здесь)\s+не\s+раздают', 0.0, false, ['обещать нечего', 'без обещаний']],
    ['история\s+про\s+риск|затея\s+для\s+крепких\s+нервов|игра\s+без\s+подстраховки|риск\s+в\s+обе\s+стороны\s+настоящий', 0.5, false, ['риск без подушки', 'азарт без страховки']],
    ['красивая\s+история',                     0.5,  false, ['звучит красиво', 'история хорошая']],
    ['розовых\s+очков',                        0.5,  false, ['лишнего оптимизма', 'иллюзий']],
    // «Можно выиграть, можно проиграть» у A 0.8 на страницу; замены нейтральные, без штампа.
    ['можно\s+выиграть[,—–\s]*(?:а\s+)?можно\s+(?:и\s+)?(?:проиграть|слить|уйти\s+в\s+минус)', 0.8, false, ['исход в обе стороны', 'результат не обещан']],
];

/**
 * Сквозная тема набора: имя приветственного пакета и имя программы лояльности.
 * У A на всех страницах «Дары Фараона» и «Династии», и текст читается как один
 * сайт; у нас были «приветственный пакет» и «программа лояльности» без имён.
 */
const V5_TEMY = [
    ['Северное сияние', 'Полярный круг'], ['Золотая жила', 'Рудник'], ['Красная дорожка', 'Ложа'],
    ['Первый спин', 'Лига постоянных'], ['Стартовый залп', 'Гвардия'], ['Ключ от кассы', 'Круг доверия'],
    ['Тёплый старт', 'Круг своих'], ['Огненный старт', 'Пламя'], ['Ночная смена', 'Ночной клуб'],
    ['Открытый сезон', 'Ветераны'], ['Разгон', 'Экипаж'], ['Семь ключей', 'Совет семи'],
];
function v5Tema(int $сид): array
{
    [$пакет, $программа] = V5_TEMY[crc32('тема|' . $сид) % count(V5_TEMY)];
    return ['пакет' => $пакет, 'программа' => $программа];
}

/**
 * Побуждающие предложения в записи. Замер по корпусу: в последнем абзаце
 * раздела у чужих 0.76 побуждения, у нас 1.26, и в худших наших концовках
 * призыв стоит в шести предложениях из семи подряд — «читай отзывы, выбирай
 * игру и заходи… смотри отзывы, сравнивай рейтинг и начинай… проверь сам…
 * начни с малого». У чужих худшее, что нашлось, — четыре побуждения на
 * двенадцать предложений, и они перемешаны с содержанием.
 *
 * Роль `cta` в пулах размечена, но её мало: «Не заходи, если боишься
 * проиграть» и «Читай отзывы, сверяй рейтинг и решай сам» размечены иначе,
 * а читаются ровно как призыв. Поэтому считаем по самому тексту.
 */
function v5PobuzhdeniyaVZapisi(string $т): int
{
    static $re = '~(?<![а-яё])(?:заходи|заходите|входи|войди|жми|жмите|нажми|нажмите|проверь|проверьте|проверяй|смотри|смотрите|читай|читайте|решай|решайте|реши|выбирай|выбери|пройди|пройдите|проходи|пробуй|попробуй|попробуйте|начни|начните|начинай|бери|возьми|забери|заберите|лови|открывай|открой|сверь|сверяй|изучи|изучай|следи|следите|дерзай|не\s+заходи|не\s+тяни|не\s+жди|не\s+начинай|не\s+скачивай)(?![а-яё])~ui';
    $чист = strip_tags($т);
    $предложения = preg_split('~(?<=[.!?])\s+~u', $чист, -1, PREG_SPLIT_NO_EMPTY) ?: [];
    $н = 0;
    foreach ($предложения as $п) { if (preg_match($re, $п)) { $н++; } }
    return $н;
}

const V5_БРЕНДЫ = '__бренды';

/**
 * Выбор бренда набора по журналу: из списка пар «пакет / программа» берётся
 * та, чьи имена дольше всего не выходили. Имён в обороте немного — двенадцать
 * у миров и двенадцать у тем, — и чистый розыгрыш по сиду ставил в одну
 * поставку два набора с одним пакетом: замер по 163 наборам дал «Северное
 * сияние / Полярный круг» 24 раза, «Золотая жила / Рудник» 12, и в каждой
 * десятке был повтор.
 *
 * Давность считается по обоим именам сразу — и по пакету, и по программе:
 * «Ложа» стоит и в мире «Шапито», и в теме «Красная дорожка», так что
 * учитывать только пакет мало. Розыгрыш остаётся, но идёт по трети самых
 * давних пар: очередь была бы строгой и предсказуемой.
 *
 * @param array $пары список ['пакет' => …, 'программа' => …] или [пакет, программа]
 */
function v5BrendDavniy(array $пары, array $журнал, array $порядок, int $сид, string $зерно): int
{
    if ($пары === []) { return 0; }
    $владельцы = is_array($журнал[V5_БРЕНДЫ] ?? null) ? $журнал[V5_БРЕНДЫ] : [];
    $поз = static function (?string $имя) use ($владельцы, $порядок): int {
        if ($имя === null || $имя === '') { return -1; }
        $хозяин = $владельцы[$имя] ?? null;
        if ($хозяин === null) { return -1; }
        $и = array_search($хозяин, $порядок, true);
        return $и === false ? -1 : (int) $и;
    };
    $вес = [];
    foreach ($пары as $и => $пара) {
        $пакет = (string) ($пара['пакет'] ?? $пара[0] ?? '');
        $программа = (string) ($пара['программа'] ?? $пара[1] ?? '');
        // Свежее из двух имён и решает: пара с недавно выданной программой
        // остаётся «свежей», даже если её пакет давно не выходил.
        $вес[$и] = max($поз($пакет), $поз($программа));
    }
    asort($вес);
    $давние = array_slice(array_keys($вес), 0, max(1, intdiv(count($пары), 3)));
    return (int) $давние[crc32($зерно . '|' . $сид) % count($давние)];
}

/** Тема набора с оглядкой на журнал: имена пакета и программы не повторяются в поставке. */
function v5TemaZhurnalom(int $сид, array $журнал, array $порядок): array
{
    $и = v5BrendDavniy(V5_TEMY, $журнал, $порядок, $сид, 'тема');
    [$пакет, $программа] = V5_TEMY[$и];
    return ['пакет' => $пакет, 'программа' => $программа];
}

/** Записать в журнал, кому ушли имена пакета и программы. */
function v5ZapisatBrend(array &$журнал, array $тема, string $имяНабора): void
{
    if (!is_array($журнал[V5_БРЕНДЫ] ?? null)) { $журнал[V5_БРЕНДЫ] = []; }
    foreach (['пакет', 'программа'] as $к) {
        $имя = (string) ($тема[$к] ?? '');
        if ($имя !== '') { $журнал[V5_БРЕНДЫ][$имя] = $имяНабора; }
    }
}
function v5VpisatTemu(string $html, array $тема, int $предел = 4): string
{
    $п = $тема['пакет'] ?? ''; $пр = $тема['программа'] ?? '';
    if ($п === '' || $пр === '') { return $html; }
    $н1 = 0; $н2 = 0;
    // «Бонусы до 300 %», «приветственный бонус», «пакет до 175 %» — всё это у A зовётся
    // именем пакета; здесь до четырёх подстановок на страницу.
    $html = (string) preg_replace_callback('~(?<![а-яё])(?:приветственн\w+|стартов\w+|бонусн\w+)\s+(пакет\w*)(?![а-яё])|(?<![а-яё])(пакет\w*)(?=\s+(?:до|на|в)\s+(?:<strong>)?\d)|(?<![а-яё])(?:приветственн\w+|стартов\w+)\s+(бонус\w*)(?![а-яё])|(?<![а-яё])(?<!пакет )(?<!Пакет )(?<!пакет <strong>)(?<!Пакет <strong>)(бонус\w*)(?=\s+(?:до|в размере)\s+(?:<strong>)?\d+\s*%)~ui',
        function ($m) use (&$н1, $п, $предел) {
            if (++$н1 > $предел) { return $m[0]; }
            // Заглавная в начале предложения переходит на «Пакет».
            $слово = ''; foreach ([1, 2, 3, 4] as $г) { if (($m[$г] ?? '') !== '') { $слово = $m[$г]; break; } }
            if ($слово === '') { return $m[0]; }
            // «бонус до 300 %» → «пакет «Имя» до 300 %»: слово меняется на «пакет» с тем же окончанием.
            // «Бонусы до 175 % выглядят бодро» → «Пакет … выглядят»: множественное не подменяем.
            if (mb_stripos($слово, 'бонус') === 0 && preg_match('~(?:ы|ов|ам|ами|ах)$~u', mb_strtolower($слово))) { $н1--; return $m[0]; }
            if (mb_stripos($слово, 'бонус') === 0) { $слово = 'пакет'; }
            $первая = mb_substr($m[0], 0, 1);
            if ($первая === mb_strtoupper($первая) && preg_match('~^[А-ЯЁ]~u', $первая)) { $слово = mb_strtoupper(mb_substr($слово, 0, 1)) . mb_substr($слово, 1); }
            return $слово . ' «' . $п . '»';
        }, $html);
    $html = (string) preg_replace_callback('~(?<![а-яё])(программ\w+)\s+лояльности(?![а-яё])(?!\s*(?:</strong>)?\s*«)|(?<![а-яё])VIP[- ]?(программ\w+|статус\w*|уровн\w*|клуб\w*)(?![а-яё])(?!\s*(?:</strong>)?\s*«)~ui',
        function ($m) use (&$н2, $пр, $предел) {
            if (++$н2 > $предел) { return $m[0]; }
            $слово = $m[1] !== '' ? $m[1] : ($m[2] ?? 'программа'); $первая = mb_substr($m[0], 0, 1);
            if ($первая === mb_strtoupper($первая) && preg_match('~^[А-ЯЁ]~u', $первая)) { $слово = mb_strtoupper(mb_substr($слово, 0, 1)) . mb_substr($слово, 1); }
            return $слово . ' «' . $пр . '»';
        }, $html);
