/**
 * Игры и студии на странице slots. У A имена игр стоят в двух разделах из шести
 * (7 имён, 5 студий на motor; по корпусу 0–13 имён), у нас — 1–3. Набор получает
 * четыре игры со студиями; на slots герой открывает не «слот», а Sweet Bonanza,
 * «популярные слоты» становятся «популярными слотами вроде X и Y», «свежий
 * релиз» — «свежим релизом от Nolimit City». До пяти подстановок на страницу,
 * метки ссылок не трогаем.
 */
const V5_IGRY = [
    ['Sweet Bonanza', 'Pragmatic Play'], ['Gates of Olympus', 'Pragmatic Play'],
    ['Book of Dead', "Play'n GO"], ['Razor Shark', 'Push Gaming'],
    ["Gonzo's Quest", 'NetEnt'], ['Starburst', 'NetEnt'],
    ['Dead or Alive 2', 'NetEnt'], ['Big Bass Bonanza', 'Pragmatic Play'],
    ['The Dog House', 'Pragmatic Play'], ['Reactoonz', "Play'n GO"],
    ['Legacy of Dead', "Play'n GO"], ['Money Train 3', 'Relax Gaming'],
    ['Wanted Dead or a Wild', 'Hacksaw Gaming'], ['San Quentin', 'Nolimit City'],
    ['Buffalo King Megaways', 'Pragmatic Play'], ['Fruit Party', 'Pragmatic Play'],
    ['Sugar Rush', 'Pragmatic Play'], ['Wolf Gold', 'Pragmatic Play'],
    ['Le Bandit', 'Hacksaw Gaming'], ["Jammin' Jars", 'Push Gaming'],
    ['Bonanza Megaways', 'Big Time Gaming'], ['Mega Moolah', 'Microgaming'],
    ['Divine Fortune', 'NetEnt'], ['Wild West Gold', 'Pragmatic Play'],
];
function v5Igry(int $сид): array
{
    $список = V5_IGRY; $x = crc32('игры|' . $сид);
    for ($i = count($список) - 1; $i > 0; $i--) {
        $x = ($x * 1103515245 + 12345) & 0x7fffffff;
        $j = $x % ($i + 1); [$список[$i], $список[$j]] = [$список[$j], $список[$i]];
    }
    return array_slice($список, 0, 4);
}
function v5VpisatIgry(string $html, array $игры, int $запасИгр, int $запасСтудий, int $запасРазных): string
{
    if (count($игры) < 2) { return $html; }
    // Запас — сколько имён страница ещё может принять, не выпав из своей цели
    // (цель разыграна от сида в корпусной полосе, допуск приёмки ±2). Каждое
    // правило стоит имён игр, студий и разных имён; без запаса оно не идёт.
    $студияБыла = []; $ход = 0;
    $имя = function (bool $соСтудией) use ($игры, &$ход, &$студияБыла): string {
        [$и, $ст] = $игры[$ход++ % count($игры)];
        if ($соСтудией && !isset($студияБыла[$ст])) { $студияБыла[$ст] = true; return "$и ($ст)"; }
        return $и;
    };
    $студии = array_values(array_unique(array_column($игры, 1)));
    $пара = fn() => $имя(false) . ' и ' . $имя(false);
    $правила = [
        // герой открывает игру: «открыл слот» → «открыл Sweet Bonanza (Pragmatic Play)»; игра 1, студия 1
        ['~(?<![а-яё])(открыл\w*|запустил\w*|выбрал\w*|включил\w*|зашёл в|зашла в|сел за|села за|крутил\w*)\s+(?:новый\s+|свежий\s+|один\s+|какой-то\s+)?(?:слот|автомат|игровой автомат|релиз)(?![а-яё-])(?!\s*[A-Z«(])~u',
            fn($m) => $m[1] . ' ' . $имя(true), 1, 1, 2],
        // «популярные слоты дают разный темп» → «популярные слоты вроде X и Y дают…»; игры 2
        ['~(?<![а-яё])(популярны\w+|топов\w+|известны\w+|любимы\w+)\s+(слот\w*|автомат\w*|игровы\w+\s+автомат\w*)(?![а-яё])(?!\s+(?:вроде|типа|уровня|—|-|[A-Z]))(?=\s+[а-яё])~u',
            fn($m) => $m[1] . ' ' . $m[2] . ' вроде ' . $пара(), 2, 0, 2],
        // «свежий релиз» → «свежий релиз от Nolimit City»; студия 1
        ['~(?<![а-яё])(свеж\w+\s+релиз\w*|нов\w+\s+релиз\w*)(?![а-яё])(?!\s+(?:от|[A-Z]))~u',
            fn($m) => $m[1] . ' от ' . $студии[0], 0, 1, 1],
        // «провайдеры» один раз → «провайдеры вроде Pragmatic Play и NetEnt»; студии 2
        ['~(?<![а-яё])(провайдер(?:ы|ов|ами|ам)|студи(?:и|й|ям|ями))(?![а-яё])(?!\s+(?:вроде|типа|уровня|[A-Z]))(?=\s+[а-яё])~u',
            fn($m) => $m[1] . ' вроде ' . $студии[0] . (isset($студии[1]) ? ' и ' . $студии[1] : ''), 0, min(2, count($студии)), min(2, count($студии))],
    ];
    // Снаружи ссылок и заголовков: метка ссылки остаётся меткой.
    $куски = preg_split('~(<a\b[^>]*>.*?</a>|<h[1-6][^>]*>.*?</h[1-6]>)~su', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    foreach ($правила as [$регулярка, $замена, $ценаИгр, $ценаСтудий, $ценаРазных]) {
        $разОдин = str_contains($регулярка, 'провайдер') ? 1 : 2;   // одно правило — не больше двух раз
        $свой = 0;
        foreach ($куски as $k => $кусок) {
            if ($k % 2 === 1 || $свой >= $разОдин) { continue; }
            if ($запасИгр < $ценаИгр || $запасСтудий < $ценаСтудий || $запасРазных < $ценаРазных) { break; }
            $куски[$k] = (string) preg_replace_callback($регулярка, function ($m) use (&$свой, &$запасИгр, &$запасСтудий, &$запасРазных, $замена, $разОдин, $ценаИгр, $ценаСтудий, $ценаРазных) {
                if ($свой >= $разОдин || $запасИгр < $ценаИгр || $запасСтудий < $ценаСтудий || $запасРазных < $ценаРазных) { return $m[0]; }
                $свой++; $запасИгр -= $ценаИгр; $запасСтудий -= $ценаСтудий; $запасРазных -= $ценаРазных;
                return $замена($m);
            }, $кусок);
        }
    }
    return implode('', $куски);
}

function v5UkrotitShtampy(string $html, int $предел = 2): string
{
    $заглавная = fn(string $x): string => mb_strtoupper(mb_substr($x, 0, 1)) . mb_substr($x, 1);
