        $лимит = (int) floor($лимитДробный) + ($жребий < (int) round(($лимитДробный - floor($лимитДробный)) * 100) ? 1 : 0);
        // Штамп-предложение («гарантий нет», «никто ничего не обещает», «можно выиграть…»):
