            $куски[$k] = (string) preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su', function ($a) use ($тело, $лимит, $наречие, $клауза, $замены, &$счёт, &$круг, $заглавная, $слева) {
                $т = $a[2];
