                $гр = '(?<=^|[.!?…]\s|[.!?…]\s<strong>|[.!?…]\s<em>|^<strong>|^<em>)';
                $союз = '(?!\s*(?:а|но|и|зато|однако|хотя|котор\w+|кто|что|чтобы|где|когда)\s)';
                // Формы вхождения: отдельное предложение; зачин перед двоеточием; зачин после
                // двоеточия или тире; хвост после запятой или тире (с союзом); «штамп и …»;
                // «… и штамп»; наречие в конце фразы; наречие посреди фразы; иначе — как есть.
                $рег = '~(?<sent>' . $гр . '(?:' . $тело . ')[.!](?:\s+|$|(?=\s*</(?:strong|em)>)))'
                     . '|(?<lead>' . $гр . '(?:' . $тело . ')\s*[:,—–-]\s*' . $союз . '(?=[а-яё]))'
                     . '|(?<clead>(?<=[:—–])\s*(?:' . $тело . ')\s*[,:—–]\s*' . $союз . '(?=[а-яё]))'
                     . '|(?<tail>\s*[,—–:;-]\s*(?:и\s+|а\s+|но\s+)?(?:' . $тело . ')(?=\s*(?:</strong>|</em>)?\s*[.!?;]))'
                     . '|(?<midi>(?<![.!?…>:;])\s*,?\s+(?:' . $тело . ')\s+и(?=\s))'
                     . '|(?<imid>\s+и\s+(?:' . $тело . ')(?=\s*[,.!?;:—–]|\s+[а-яё]))'
                     . '|(?<end>(?<![.!?…>:;,—–])\s+(?:' . $тело . ')(?=\s*(?:</strong>|</em>)?\s*[.!?]))'
                     . '|(?<mid>(?<![.!?…>:;])\s+(?:' . $тело . ')(?=\s))'
