                    if (++$счёт <= $лимит) { return $m[0][0]; }
                    $после = strip_tags(substr($т, $m[0][1] + strlen($m[0][0])));
                    $до = strip_tags(substr($т, 0, $m[0][1]));
                    $безX = (bool) preg_match('~^[\s,]*(?:и\s+|а\s+|но\s+)?без\s~ui', $m[0][0]);
