                    $глаголДальше = (bool) preg_match('~^\s+(?:не\s|[а-яё]+(?:ть|ться|ешь|ёшь|ет|ёт|ут|ют|ишь|ит|ат|ят|ай|яй|уй|йте|йся|йтесь|ись|итесь)(?![а-яё])|[а-яё]*(?:' . implode('|', V5_VY_ИМПЕРАТИВ) . ')(?![а-яё]))~ui', $после);
