                        // Наречие с зависимым («без сказок про лёгкие деньги», «по-честному с собой», «без развода
                        // на «обязательные» ставки»), перед тире или запятой, или единственное слово фразы
                        // («Давай по-честному.») — не выбрасывается, а заменяется.
                        $зависимое = preg_match('~^\s+(?:про|о|об|насчёт|относительно|с\s+собой|перед\s+собой)(?=[\s.,!?;:])~ui', $после)
                            || ($безX && preg_match('~^\s+(?:на|в|во|с|со|для|от|перед|при)\s~ui', $после))
                            || ($г($m, 'mid') !== '' && preg_match('~^\s*[—–,;:]~u', $после))
                            || ($г($m, 'end') !== '' && preg_match_all('~[а-яё]+~ui', $начало) < 2)
                            // «затянется, тут без магии» → «затянется, тут.» — голое «тут/здесь» перед штампом.
                            || ($г($m, 'end') !== '' && preg_match('~(?<![а-яё])(?:тут|здесь|там|это|всё)\s*$~ui', $до));
