/**
 * Падежи у ссылок. Метка ссылки — глагольная («играть бесплатно», «войти в
 * казино»), и предлог перед ней читается как обрыв: «проверить через играть
 * бесплатно», «следить за новости казино». У конкурента таких сочетаний 0.38
 * на страницу, у нас было 1.03.
 *
 * Чиним заменой метки на именную того же адреса: одна метка — один адрес,
 * это правило сохраняется.
 */
function v5PochinitPadezhi(string $html): string
{
    $правила = [
        // глагольная метка каталога после предлога → «демо-режим»
        '~\bчерез\s+(<a href="/slots"[^>]*>)играть бесплатно</a>~ui'    => 'через $1демо-режим</a>',
        '~\bу\s+(<a href="/slots"[^>]*>)играть бесплатно</a>~ui'         => 'у $1демо-режима</a>',
        '~\b(в|во)\s+(<a href="/slots"[^>]*>)играть бесплатно</a>~ui'    => '$1 $2демо-режиме</a>',
        '~\b(на|за)\s+(<a href="/slots"[^>]*>)играть бесплатно</a>~ui'   => 'в $2демо-режим</a>',
        // «особенно с промокоды» → «с промокодами»
        '~\b(с|со)\s+(<a href="[^"]*"[^>]*>)промокоды</a>~ui'          => '$1 $2промокодами</a>',
        '~\b(с|со)\s+(<a href="[^"]*"[^>]*>)промо акции</a>~ui'        => '$1 $2промо акциями</a>',
        // глагольная метка входа после «через» → именная
        '~\bчерез\s+(<a href="/vhod"[^>]*>)(?:войти в казино|войти и активировать|войти)</a>~ui'
            => 'через $1вход в личный кабинет</a>',
        // «следить за слоты» → «за слотами», «за новости казино» → «новостями»
        '~\bза\s+(<a href="/slots"[^>]*>)слоты</a>~ui'   => 'за $1слотами</a>',
        '~\bза\s+(<a href="/"[^>]*>)новости казино</a>~ui' => 'за $1новостями казино</a>',
        // «вход с рабочее зеркало» → «с рабочим зеркалом»
        '~\b(с|со)\s+(<a href="/zerkalo"[^>]*>)рабочее зеркало</a>~ui' => '$1 $2рабочим зеркалом</a>',
        // «удобный приложение» → «удобное приложение»
        '~\bудобн(?:ый|ая)\s+(<a href="/app"[^>]*>)приложение</a>~ui'   => 'удобное $1приложение</a>',
        '~\b(нормальн|стабильн|быстр|надёжн|надежн|удобн)(?:ый|ая)\s+(<a href="/app"[^>]*>)мобильное приложение</a>~ui' => '$1ое $2мобильное приложение</a>',
        '~\bнаш\s+(<a href="/zerkalo"[^>]*>)рабочее зеркало</a>~ui' => 'наше $1рабочее зеркало</a>',
        // «есть регистрацию», «пригодится партнерскую программу»: после этих глаголов — именительный.
        '~\b(есть|пригодится|выручает|выручит|поможет|нужна|доступна|открыта)(\s+(?:ещё\s+и\s+|ещё\s+|и\s+|только\s+)?)(<a href="/registracia"[^>]*>)регистрацию</a>~ui' => '$1$2$3регистрация</a>',
        '~\b(есть|пригодится|выручает|выручит|поможет|нужна|доступна|открыта)(\s+(?:ещё\s+и\s+|ещё\s+|и\s+|только\s+)?)(<a href="/partnery"[^>]*>)партн([её])рскую программу</a>~ui' => '$1$2$3партн$4рская программа</a>',
        '~\b(есть|пригодится|выручает|выручит|поможет|нужна|доступна|открыта)(\s+(?:ещё\s+и\s+|ещё\s+|и\s+|только\s+)?)(<a href="/[a-z]*"[^>]*>)информацию о~ui' => '$1$2$3информация о',
        // «начни с регистрацию» → «с регистрации»
        '~\b(с|со)\s+(<a href="/app"[^>]*>)мобильное приложение</a>~ui'   => '$1 $2мобильного приложения</a>',
        '~\b(с|со)\s+(<a href="/registracia"[^>]*>)регистрацию</a>~ui'   => '$1 $2регистрации</a>',
        // «нужен промокоды», «нужен рабочее зеркало», «нужны информацию о …» — число и род
        '~\bнужен\s+(<a href="[^"]*"[^>]*>)промокоды</a>~ui'             => 'нужны $1промокоды</a>',
        '~\bнужен\s+(<a href="[^"]*"[^>]*>)рабочее зеркало</a>~ui'       => 'нужно $1рабочее зеркало</a>',
        '~\b(?:нужен|нужны|нужна)\s+(<a href="[^"]*"[^>]*>)информацию о~ui' => 'нужна $1информация о',
        '~\b(устроен[аы]?|работа(?:ет|ют))\s+(<a href="[^"]*"[^>]*>)информацию о~ui' => '$1 $2информация о',
        // «после регистрацию» → «после регистрации»
        '~\b(после|без|для|из|от|около|кроме)\s+(<a href="/registracia"[^>]*>)регистрацию</a>~ui'
            => '$1 $2регистрации</a>',
        // Якорь «регистрация» в именительном после глагола и предлога:
        // «прошёл регистрация», «через регистрация», «перед регистрацию».
        '~\b(прош[её]л|прошла|пройти|пройди|пройдя|проходишь|проходи|оформи|оформил|оформила|заверши|завершил|завершила|начни|начал|начала|сделай|сделал|сделала|через|про|под)\s+(<a href="/registracia"[^>]*>)регистрация</a>~ui'
            => '$1 $2регистрацию</a>',
        '~\b(после|без|для|из|от|около|кроме|до|вместо|у|шаге|момента|минуту|секунд|минут|с|со)\s+(<a href="/registracia"[^>]*>)регистрация</a>~ui'
            => '$1 $2регистрации</a>',
        '~\b(перед|за)\s+(<a href="/registracia"[^>]*>)регистраци(?:я|ю)</a>~ui'
            => '$1 $2регистрацией</a>',
        // «быстрый регистрация» → «быстрая регистрация»
        '~\b(быстр|нормальн|понятн|прост|удобн|честн|коротк|обычн|стандартн|полн|бесплатн)(?:ый|ое|ой)\s+(<a href="/registracia"[^>]*>)регистрация</a>~ui'
            => '$1ая $2регистрация</a>',
        '~\b(нужен|нужно)\s+(<a href="/registracia"[^>]*>)регистрация</a>~ui' => 'нужна $2регистрация</a>',
    ];
    return preg_replace(array_keys($правила), array_values($правила), $html);
}

/** Формы, у которых корень совпадает с именем из банка, а сами они не имена. */
const V5_NE_IMENA = ['люди' => 1, 'дети' => 1, 'гости' => 1, 'кости' => 1,
                     'игры' => 1, 'веры' => 1, 'славы' => 1, 'розы' => 1];

/**
 * Цель поля для конкретного набора. Профиль хранит медиану корпуса, и если
 * целиться всем наборам в неё, они сходятся в одну точку: замер по держимым
 * полям давал медиану CV 8,1 % против 19,1 % у самих доноров — наши комплекты
 * выходили вдвое однообразнее корпуса, который они изображают.
 *
 * Поэтому цель разыгрывается внутри корпусной полосы (10–90 перцентиль,
 * профиль её уже посчитал) треугольным распределением с вершиной в медиане:
 * большинство наборов остаётся около центра, единицы уходят к краям — так же,
 * как расположены сами доноры. Набор перестаёт изображать среднего донора и
 * начинает изображать какого-то одного.
 *
 * Ширина розыгрыша выбрана замером, и замер вышел неожиданным. Формально
 * ближе всех к корпусу равномерный розыгрыш по краю доноров: на трёхстах
 * полях сами доноры дают медиану CV 15,5 %, он даёт 14,8 %. Но собранные им
 * наборы дали разброс НИЖЕ — 10,2 % против 11,9 % у полосы, — и приёмка на
 * них падала до 3–5 страниц из двенадцати. Цель у края материалом пулов не
 * берётся: генератор до неё не дотягивается и садится там же, где сел бы и
 * так, только теперь мимо своей цели.
 *
 * Отсюда второе ограничение: розыгрыш идёт по пересечению корпусной полосы с
 * тем, что движок реально достаёт («достижимое» в профиле, считает
 * `dostizhimoe-v5.php` по собранным страницам). На 660 полях медиана покрытия
 * — 100 %, движок почти везде свободен; но шестнадцать полей закрывают полосу
 * на 29–60 %: сборка из готовых кусков даёт абзацы в 33–42 слова, а доноры
 * пишут по 39–54, и цель в пятьдесят слов на абзац не берётся ни одной
 * попыткой. Целиться туда — не разнообразие, а гарантированный провал
 * страницы. Где пересечение вырождается, остаётся медиана.
 *
 * Ширина коридора приёмки при этом остаётся корпусной: она свойство метрики,
 * а не набора, и профиль строился именно по ней.
 *
 * Розыгрыш детерминирован от сида и КЛЮЧА ПОЛЯ, без типа страницы. Это
 * намеренно: донор пишет длинными абзацами на всех двенадцати страницах
 * сразу, а не на одной. Один и тот же розыгрыш даёт разные абсолютные цели
 * по типам, потому что полоса у каждого типа своя.
 *
 * Нулевая цель — запрет, а не полоса, и розыгрышу не подлежит.
 */
/**
 * Поля, которые растут вместе с объёмом страницы. Их цель набора разыгрывается
 * тем же u, что и words: «многословный» набор получает высокие цели и по
 * анкорам, и по вопросам, и по абзацам. Раньше у каждого поля было своё u, и
 * пока объём не двигался, это не мешало; как только характер набора начал
 * тянуть слова на ±10 %, счётчики в штуках уехали от своих целей — на восьми
 * комплектах anchors/faq/questions валили по 8–10 страниц. Плотность на 1000
 * слов при этом не менялась (anchors 3.78 → 4.00, вопросы 6.52 → 6.41).
 * Доли и проценты (…_pct, …_per100, spread) сюда не входят — они от объёма
 * не зависят и живут своим розыгрышем.
 */
const V5_IMENA = ['games_named', 'providers_named', 'names_uniq'];
const V5_S_OBJEMOM = ['words', 'paragraphs', 'sections', 'anchors', 'questions_total', 'faq',
    'strong', 'honest', 'terms_total', 'address_total', 'ty', 'imperatives', 'cta', 'lists', 'h2'];

function v5CelNabora(array $поле, int $сид, string $ключ): float
{
    $цель = (float) ($поле['цель'] ?? 0.0);
    // Нулевая медиана — не всегда запрет: у доноров имена игр на slots
    // держат 9 из 11 в нуле, но двое называют до десяти. Розыгрыш идёт
    // внутри полосы, обрезанной достижимым; где полоса [0,0] — остаётся ноль.
    if ($сид <= 0 || ($цель <= 0.0 && !in_array($ключ, V5_IMENA, true))) { return $цель; }
    $дробное = !empty($поле['дробное']);
    // Три поля имён тянутся из одного зерна: разных имён на странице не
    // бывает меньше, чем игр, и розыгрыш «игр 3, а всего имён 1» им запрещён.
    $ключЗерна = in_array($ключ, V5_S_OBJEMOM, true) ? 'words'
        : (in_array($ключ, V5_IMENA, true) ? 'names' : $ключ);
    $зерно = crc32($ключЗерна . '|' . $сид);
    $u = ($зерно % 100000) / 100000;                 // [0, 1)

    $полоса = $поле['полоса'] ?? null;
    $низ = is_array($полоса) ? (float) ($полоса[0] ?? 0) : 0.0;
    $верх = is_array($полоса) ? (float) ($полоса[1] ?? 0) : 0.0;
    // Обрезаем полосу достижимым: цель, до которой движок не дотягивается,
    // разброса не даёт, а страницу валит.
    $дост = $поле['достижимое'] ?? null;
    if (is_array($дост) && count($дост) === 2) {
        $низ = max($низ, (float) $дост[0]);
        $верх = min($верх, (float) $дост[1]);
    }
    // Полоса вырожденная — либо корпус по этому полю не расходится, либо
    // движок не расходится вместе с ним. Выдумывать разброс там, где его
    // нет, значит писать не в жанре. Остаётся медиана.
    if ($верх - $низ < ($дробное ? 0.2 : 1.0)) { return $цель; }
    // Вершина треугольника — корпусная медиана, прижатая внутрь отрезка:
    // если медиана вне достижимого, целимся в ближний к ней край.
    $вершина = min(max($цель, $низ), $верх);
    // Имена при нулевой медиане: вершина в середине полосы, а не в нуле.
    // С вершиной в нуле половина наборов получала цель 0–1 и бюджет имён
    // в одно название — раздел «Провайдеры» выходил без единой студии.
    // Полоса остаётся донорской (82 % доноров внутри), меняется только
    // частота, с которой набор берёт её верхнюю половину.
    if ($цель <= 0.0 && in_array($ключ, V5_IMENA, true)) { $вершина = ($низ + $верх) / 2; }
    $итог = max(0.0, v5Treugolnik($низ, $вершина, $верх, $u));
    return $дробное ? round($итог, 2) : round($итог);
}

/** Треугольное распределение: обратная функция от равномерного u. */
function v5Treugolnik(float $низ, float $вершина, float $верх, float $u): float
{
    $ширина = $верх - $низ;
    if ($ширина <= 0.0) { return $низ; }
    // Вершина на краю вырождает треугольник в половину: обе ветви ниже
    // сводятся к правильному пределу, деления на ноль тут не возникает.
    $порог = ($вершина - $низ) / $ширина;
    return $u < $порог
        ? $низ + sqrt($u * $ширина * ($вершина - $низ))
        : $верх - sqrt((1 - $u) * $ширина * ($верх - $вершина));
}

/** Число из денежной строки: «2 000 рублей» → 2000, «500₽» → 500. */
function v5Rubli(string $s): int
{
    return (int) preg_replace('~\D~u', '', $s);
}

/**
 * Сумма из банка СУММА в рублях: «3.2 млн» → 3 200 000, «290к» → 290 000,
 * «83 тыс» → 83 000. v5Rubli для них не годится — она снимает всё, кроме
 * цифр, и «120.0 млн» выходило 1200, меньше «290к»: рост «внёс X, снял Y»
 * и отбор скромных сумм героя сравнивали разряды вслепую.
 */
/** Сумма в стиле банка: 7 749 ₽, 2.5 тыс, 38к, 1.2 млн. */
function v5FormatSumma(int $n): string
{
    if ($n < 1_000) { return number_format($n, 0, '.', ' ') . ' ₽'; }
    if ($n < 10_000) { return rtrim(rtrim(number_format($n / 1_000, 1, '.', ''), '0'), '.') . ' тыс'; }
    if ($n < 1_000_000) { return (string) round($n / 1_000) . 'к'; }
    return rtrim(rtrim(number_format($n / 1_000_000, 1, '.', ''), '0'), '.') . ' млн';
}

function v5Summa(string $s): int
{
    if (!preg_match('~([\d][\d ]*(?:[.,]\d+)?)\s*(млн|тыс|к)?~ui', $s, $m)) { return v5Rubli($s); }
    $x = (float) str_replace([' ', ','], ['', '.'], $m[1]);
    $ед = mb_strtolower($m[2] ?? '');
    return (int) round($x * ($ед === 'млн' ? 1_000_000 : ($ед !== '' ? 1_000 : 1)));
}

/**
 * Род имени. Донор пишет «Елена зашла», и если подставить мужское имя, глагол
 * останется женским: пол героя — часть прорези, а не украшение. Правило —
 * окончание «а/я», за вычетом мужских имён с той же формой.
 */
function v5Rod(string $имя): string
{
    static $мужскиеНаА = ['Никита' => 1, 'Илья' => 1, 'Данила' => 1, 'Гриша' => 1, 'Паша' => 1,
        'Миша' => 1, 'Саша' => 1, 'Женя' => 1, 'Сева' => 1, 'Толя' => 1, 'Коля' => 1, 'Витя' => 1,
        'Слава' => 1, 'Дима' => 1, 'Лёша' => 1, 'Леша' => 1, 'Ваня' => 1, 'Юра' => 1, 'Костя' => 1,
        'Стёпа' => 1, 'Петя' => 1, 'Вася' => 1, 'Боря' => 1, 'Серёжа' => 1, 'Рома' => 1];
    if (isset($мужскиеНаА[$имя])) { return 'м'; }
    return in_array(mb_substr($имя, -1), ['а', 'я'], true) ? 'ж' : 'м';
}

/**
 * Склонение имени под окончание, снятое с донора. Разбор трёх типов основы
 * покрывает весь словарь: согласная (Виктор), «й» (Григорий, Андрей) и
 * «а/я» (Ольга, Илья). Падеж угадывается по окончанию донора, потому что
 * в корпусе он всегда однозначен: «у {ИМЯ:а}», «{ИМЯ:у} повезло».
 */
function v5Sklonenie(string $имя, string $ок): string
{
    // Беглая гласная: Пётр — Петра, Павел — Павла, Лев — Льва.
    static $основы = ['Пётр' => 'Петр', 'Петр' => 'Петр', 'Павел' => 'Павл', 'Лев' => 'Льв'];
    $мягкая = ['а' => 'я', 'у' => 'ю', 'ом' => 'ем', 'е' => 'е', 'ы' => 'и', 'и' => 'и', 'ю' => 'ю', 'я' => 'я', 'ей' => 'ем', 'ой' => 'ем'];
    $последняя = mb_substr($имя, -1);
    if ($последняя === 'я') {
        // Илья — Ильи, Илье, Илью, Ильёй; Женя — Жени, Жене, Женю, Женей.
        $наЯ = ['а' => 'и', 'я' => 'и', 'у' => 'е', 'ю' => 'е', 'ом' => 'ей', 'ем' => 'ей', 'ой' => 'ей', 'ей' => 'ей', 'е' => 'е', 'ы' => 'и', 'и' => 'и'];
        return mb_substr($имя, 0, -1) . ($наЯ[$ок] ?? $ок);
    }
    if ($последняя === 'а') {
        // Марина — Марины, Марине, Мариной; после г/к/х/ж/ш/щ/ч — Ольги, Наташи.
        $основа = mb_substr($имя, 0, -1);
        $и = preg_match('~[гкхжшщч]$~u', $основа) ? 'и' : 'ы';
        $наА = ['а' => $и, 'я' => $и, 'у' => 'е', 'ю' => 'е', 'ом' => 'ой', 'ем' => 'ой', 'ой' => 'ой', 'ей' => 'ой', 'е' => 'е', 'ы' => $и, 'и' => 'и'];
        return $основа . ($наА[$ок] ?? $ок);
    }
    if ($последняя === 'й' || $последняя === 'ь') {
        return mb_substr($имя, 0, -1) . ($мягкая[$ок] ?? $ок);
    }
    return ($основы[$имя] ?? $имя) . $ок;
}

/**
 * Заполнение трафарета: `$значение('ПРОЦ')` возвращает значение прорези.
 * Имя выдаётся через `$значение('ИМЯ')` и склоняется здесь же.
 */
/**
 * Прорези доноров. В корпусе остались плейсхолдеры чужой шаблонизации —
 * `{NAME}` в заголовках слотов, `{AMOUNT}` рядом с ним. Своими именами мы их
 * не знаем, а подставить надо: заголовок «Джекпот слоты — {NAME} сорвал
 * {AMOUNT} здесь» уехал в выдачу как «— 0 сорвал 0 здесь».
 */
const V5_CHUZHIE_PROREZI = ['NAME' => 'ИМЯ', 'AMOUNT' => 'СУММА'];

function v5Zapolnit(string $t, callable $значение): string
{
    // Имя прорези может содержать цифру (`{RTP2}`) — без этого подстановка
    // молча проходит мимо, и в выдачу уезжает сам плейсхолдер.
    // Позиция текущей прорези в исходнике: одинаковые прорези («{РУБЛИ} …
    // {РУБЛИ}») ищутся от места прошлой, иначе обе находят первую и вторая
    // тоже читает контекст ставки.
    $от = 0;
    return preg_replace_callback('~\{([А-ЯA-Z][А-ЯA-Z0-9_]*)(?::([а-я]{1,2}))?\}~u', function ($m) use ($значение, $t, &$от) {
        $ключ = V5_CHUZHIE_PROREZI[$m[1]] ?? $m[1];
        $поз = mb_strpos($t, $m[0], $от);
        if ($поз !== false) { $от = $поз + 1; }
        // Рубли в контексте ставки — отдельный ключ: узел даёт на него
        // ставочный слой банка. Если заполнитель ключа не знает (вернул
        // пусто), берём обычные рубли — поведение прежнее.
        if ($ключ === 'РУБЛИ') {
            $до = $поз === false ? '' : mb_substr($t, max(0, $поз - 40), min(40, $поз));
            if (preg_match('~(?:ставк\w*|поставил\w*|закинул\w*|внёс|внесл\w*|депозит\w*)\s+(?:в\s+|на\s+|—\s+|:\s+)?$~ui', strip_tags($до))) {
                $v = (string) $значение('РУБЛИ_СТАВКА');
                if ($v !== '' && $v !== '0') { return $v; }
            }
            // Рубли после «сорвал» — это куш, а не ставка: H2 «{ИМЯ} сорвал
            // {РУБЛИ} здесь» давал «сорвал 3 031 ₽». Берём сумму истории
            // узла. Только «сорвал»: с «вывел/снял/забрал» правило уводило
            // vhod с рублёвых выводов на суммы в «к» и валило страницу
            // (vhod 7 провалов из 8 против 2–3).
            // «Забрал/поднял/выиграл {РУБЛИ}» — тоже куш: H2 «сорвал 56к» шёл
            // над телом «забрал 350 тысяч рублей». «Вывел/снял» — без «куш»
            // не трогаем: на vhod это вывод.
            // В истории героя (запись с {ИМЯ}) и «вывел/снял {РУБЛИ}» — его выигрыш:
            // «поднял 38к … Через полтора часа вывел 270 тысяч рублей».
            // И продолжение его истории без имени: «Через два дня вывел {РУБЛИ}».
            $вИстории = str_contains($t, '{ИМЯ') || (bool) preg_match('~^\s*(?:через|спустя|потом|затем|после|а через|в итоге)\b~ui', strip_tags($t));
            // Оборот отыгрыша = бонус × вейджер: «вейджер x45 значит, что прокрутить надо {СУММА}».
            if (preg_match('~(?:прокрутить|отыграть|проставить|оборот\w*)\s+(?:надо|нужно|придётся|в\s+размере|—|:)?\s*(?:сумму\s+)?$~ui', strip_tags($до))) {
                $v = (string) $значение('СУММА_ОБОРОТ');
                if ($v !== '' && $v !== '0') { return $v; }
            }
            // Бонус считается от депозита: «закинул 15к и получил бонусы на {СУММА}» — не ставочный слой.
            if (preg_match('~(?:бонус\w*|пакет\w*|подар\w*)\s+(?:на|в\s+размере|до|—|:)?\s*$|получил\w*\s+(?:ещё\s+)?(?:бонус\w*\s+)?(?:на\s+)?$~ui', strip_tags($до))) {
                $v = (string) $значение('СУММА_БОНУС');
                if ($v !== '' && $v !== '0') { return $v; }
            }
            if (preg_match('~(?:(?:сорвал|забрал|поднял|выиграл|вынес|унёс|выбил)\w*\s+(?:куш\s+(?:в\s+|на\s+)?(?:—\s+)?|около\s+|почти\s+|целых\s+)?|(?:вывел|снял|поймал)\w*\s+куш\s+(?:в\s+|на\s+)?)$~ui', strip_tags($до))
                || ($вИстории && preg_match('~(?:вывел|вывела|снял|сняла|получил|получила|составил|составила|принесл[аио]\w*\s+(?:ему|ей)|итог\w*\s*[—:-]?)\s+(?:на\s+карту\s+|около\s+|почти\s+|целых\s+|свои\s+)?$~ui', strip_tags($до)))) {
                $v = (string) $значение('СУММА');
                if ($v !== '' && $v !== '0') { return $v; }
            }
        }
        // Сумма в контексте старта — тоже ставка: «начал с {СУММА}»,
        // «пополнил баланс на {СУММА}», «поставил {СУММА}». Сумма раздела
        // делала их равными выигрышу: «начал с 40к … вывел 40к».
        if ($ключ === 'СУММА' || $ключ === 'СУММАМАЛ') {
            $до = $поз === false ? '' : mb_substr($t, max(0, $поз - 50), min(50, $поз));
            // Сумма проигрыша — своя роль: ниже выигрыша героя.
            if (preg_match('~(?:бонус\w*|пакет\w*|подар\w*)\s+(?:на|в\s+размере|до|—|:)?\s*$|получил\w*\s+(?:ещё\s+)?(?:бонус\w*\s+)?(?:на\s+)?$~ui', strip_tags($до))) {
                $v = (string) $значение('СУММА_БОНУС');
                if ($v !== '' && $v !== '0') { return $v; }
            }
            if (preg_match('~(?:слил\w*|сливал\w*|проиграл\w*|проигрывал\w*|потерял\w*|терял\w*|ушл[оа]|спустил\w*|минус\w*\s+на|в\s+трубу|отдал\w*\s+обратно)\s*(?:около\s+|почти\s+|целых\s+|ещё\s+|весь\s+|все\s+|свои\s+)?$~ui', strip_tags($до))) {
                $v = (string) $значение('СУММА_ПРОИГРЫШ');
                if ($v !== '' && $v !== '0') { return $v; }
            }
            if (preg_match('~(?:начал\w*\s+с|стартовал\w*\s+с|зашёл\s+с|зашла\s+с|заш[ёе]л\w*[^.]{0,25}?\s+с|заход\w*\s*[—–-]?\s*с|поставил\w*|внёс|внесл\w*|закинул\w*|депозит\w*|пополнил\w*[^.]{0,20}?на|пополнени\w*\s+(?:на|в)|с\s+балансом|баланс\s+на|стартов\w+\s+(?:депозит\w*|банк\w*)|играть\s+от|ставк\w*\s+от|со\s+ставки|лимит\w*\s+(?:в|на|—|–|:)?\s*|потратишь\s+(?:максимум\s+)?|бюджет\w*\s+(?:в|на|—|–|:)?\s*|не\s+жалко\s+потерять\s+|банк\w*\s+(?:в|на|из|от)\s+|банкролл\w*\s+(?:в|на)\s+|бонус\w*\s+(?:на|в\s+размере|до)\s+)\s*(?:в\s+|на\s+|—\s+|:\s+|всего\s+|скромные\s+|первые\s+|свои\s+|стартовые\s+|туда\s+)?$~ui', strip_tags($до))) {
                $v = (string) $значение('СУММА_СТАВКА');
                if ($v !== '' && $v !== '0') { return $v; }
            }
        }
        $v = (string) $значение($ключ);
        // Незнакомая прорезь остаётся собой: ноль вместо имени приёмка не
        // ловит, а сам плейсхолдер — ловит.
        if ($v === '' || $v === '0') { return $m[0]; }
        $имя = $ключ === 'ИМЯ' || $ключ === 'ИМЯЖ';
        return ($имя && ($m[2] ?? '') !== '') ? v5Sklonenie($v, $m[2]) : $v;
    }, $t);
}

/**
 * Близость двух кусков по четырёхсловным цепочкам. Пул одного раздела набран
 * с одиннадцати доноров, а фабрика писала их по одному шаблону: «Джекпот до X
 * звучит громко, однако вероятность не равна гарантии» встречается в трёх
 * переписываниях. Рядом в одном списке они читаются как заедание.
 */
function v5Blizost(string $a, string $b): float
{
    $ц = function (string $t): array {
        $w = preg_split('~\s+~u', mb_strtolower(preg_replace('~[^а-яёa-z0-9 ]+~u', ' ',
            preg_replace('~<[^>]*>~', ' ', $t))), -1, PREG_SPLIT_NO_EMPTY);
        $o = [];
        for ($i = 0; $i + 4 <= count($w); $i++) { $o[implode(' ', array_slice($w, $i, 4))] = 1; }
        return $o;
    };
    $x = $ц($a); $y = $ц($b);
    if (!$x || !$y) { return 0.0; }
    return count(array_intersect_key($x, $y)) / min(count($x), count($y));
}

/**
 * Разбор абзаца на предложения с сохранением встроенной разметки.
 *
 * Перенос абзацев целиком даёт с донором столько же совпадения, сколько доля
 * его абзацев в нашей странице, — на замере это 16–26 % против корпусного
 * потолка 8–11 %. Шингл в шесть слов рвётся на границе предложения, поэтому
 * абзац собирается из предложений разных доноров, и доля каждого падает втрое.
 *
 * Теги вынимаются перед разрезкой и возвращаются после: точка внутри
 * `href="сайт.com"` — не конец предложения. Предложение с непарным тегом
 * отбрасывается: собирать из него абзац нельзя.
 */
function v5Predlozheniya(string $html): array
{
    $теги = [];
    $без = preg_replace_callback('~<[^>]+>~', function ($m) use (&$теги) {
        $теги[] = $m[0];
        return "\x01" . (count($теги) - 1) . "\x02";
    }, $html);
    $куски = preg_split('~(?<=[.!?…])\s+~u', $без, -1, PREG_SPLIT_NO_EMPTY) ?: [];
    $итог = [];
    foreach ($куски as $к) {
        $п = preg_replace_callback('~\x01(\d+)\x02~', fn($m) => $теги[(int) $m[1]], $к);
        $открыто = preg_match_all('~<([a-z0-9]+)(?:\s[^>]*)?>~i', $п, $o);
        $закрыто = preg_match_all('~</([a-z0-9]+)>~i', $п, $c);
        if ($открыто !== $закрыто) { continue; }
        $п = trim($п);
        if (mb_strlen($п) < 15) { continue; }
        $итог[] = $п;
    }
    return $итог;
}

/**
 * Текстовые прорези виджета: строки, где лежит текст, и роль каждой — класс
 * ближайшего предка с классом (иначе itemprop, иначе тег).
 *
 * Виджет нельзя переносить от одного донора целиком: разметка у всех общая, а
 * текст в ней свой, и перенос даёт кусок дословного совпадения размером в пол
 * страницы. Роли же у доноров одни и те же — `hero-tagline`, `payout-name`,
 * `pillar-text`, — поэтому каждая строка набирается из своего пула.
 *
 * Пары «вопрос-ответ» из этого исключены: их надо менять парой, иначе ответ
 * встанет под чужим вопросом. Ими занимается отдельная подстановка.
 */
const V5_ROLI_PAROJ = ['faq-question', 'text', 'review-quote-text'];

function v5Sloty(string $html): array
{
    $строки = explode("\n", $html);
    $стек = []; $слоты = [];
    foreach ($строки as $i => $l) {
        $t = trim($l);
        if ($t === '') { continue; }
        if ($t[0] !== '<') { $слоты[] = ['строка' => $i, 'роль' => end($стек) ?: '?']; continue; }
        if (str_starts_with($t, '</')) { array_pop($стек); continue; }
        if (!preg_match('~^<([a-z0-9]+)([^>]*)>~i', $t, $m)) { continue; }
        $роль = preg_match('~class="([^"]*)"~', $m[2], $c) ? explode(' ', trim($c[1]))[0]
              : (preg_match('~itemprop="([^"]*)"~', $m[2], $ip) ? $ip[1] : $m[1]);
        if ($роль === '') { $роль = $m[1]; }
        $пустой = str_ends_with($t, '/>') || in_array(strtolower($m[1]), ['meta', 'img', 'br', 'input', 'hr'], true);
        if ($пустой) { continue; }
        if (preg_match('~^<[a-z0-9]+[^>]*>(.+)</[a-z0-9]+>\s*$~i', $t)) {
            $слоты[] = ['строка' => $i, 'роль' => $роль, 'встроенный' => true];
            continue;
        }
        $стек[] = $роль;
    }
    return $слоты;
}

/** Вёрстка узла в стиле корпуса: тег на нулевой колонке, текст с отступом. */
function v5Uzel(string $tag, string $inner, string $attrs = ''): string
{
    return "<{$tag}{$attrs}>\n  " . $inner . "\n</{$tag}>";
}

/**
 * Пункт-шаг: императив в начале или слово порядка. Маркер перечня («Плюс:»,
 * «Минус:», галочка) отменяет всё — это список свойств, а не инструкция.
 */
function v5ShagovyiPunkt(string $т): bool
{
    if (preg_match('~^(?:<strong>)?\s*(?:[\x{2700}-\x{27BF}\x{2600}-\x{26FF}'
        . '\x{1F300}-\x{1FAFF}\x{2705}\x{274C}]|Плюс|Минус|Важно|Факт|Совет)~u', $т)) {
        return false;
    }
    return (bool) preg_match('~^(?:<strong>)?(?:Сначала|Затем|Потом|После|Далее|В конце'
        . '|Скачай\w*|Установи\w*|Открой\w*|Откры\w*|Нажми\w*|Разреши\w*|Введи\w*'
        . '|Подтверди\w*|Зайди\w*|Войди\w*|Перейди\w*|Выбери\w*|Заполни\w*'
        . '|Активируй\w*|Пройди\w*|Проверь\w*|Дождись|Дождитесь|Запусти\w*|Найди\w*'
        . '|Укажи\w*|Сохрани\w*|Зарегистрируй\w*|Пополни\w*)\b~u', $т);
}

/** Раздел, где нумерация уместна: инструкция, а не перечень свойств. */
function v5ShagovyiRazdel(string $тип, string $h2): bool
{
    if ($тип === 'app')   { return (bool) preg_match('~как установить~ui', $h2); }
    if ($тип === 'promo') { return (bool) preg_match('~как использовать промокод~ui', $h2); }
    return false;
}

/**
 * Ворота набора: нумерованный список возможен ТОЛЬКО на promo.
 *
 * Доноры ставят <ol> на promo (6 из 12) и на app (3 из 12), но приёмка
 * считает коридор от ЦЕЛИ набора, а не от корпусной полосы:
 *   |наше − цель| ≤ max(0.25·|цель профиля|, 0.8)
 * У app ordered_pct цель 0 и держат=true, значит коридор — [0, 0.8], и любой
 * <ol> валит страницу: «ordered_pct 25→0». Корпусная полоса [0, 20] в этом
 * правиле не участвует. На promo признак не держат вовсе, и там <ol> живёт.
 *
 * Первая версия этого не учла и открывала ворота app каждому четвёртому
 * набору. Толку ноль — страница всё равно не проходила, — а сиды партия на
 * это тратила: 279–283 собрались за 37 попыток против 19 у 274–278.
 *
 * Донорские 25% на app недостижимы, пока цель профиля равна нулю. Поднять её
 * значило бы переписать стандарт приёмки под привычку трёх доноров из
 * двенадцати; это отдельное решение, а не побочный эффект правки разметки.
 */
function v5NumerovatNabor(string $тип, string $имяНабора): bool
{
    return $тип === 'promo';
}

/**
 * Смена тега ul→ol на готовой странице.
 *
 * Замер по двенадцати донорам: <ol> есть ТОЛЬКО на promo (шесть доноров,
 * доля 16.7–33.3%) и app (три донора, 14.3–25%). На остальных десяти типах
 * его нет ни у кого, и профиль держит там полосу [0, 0] — это запрет, а не
 * недобор.
 *
 * Разделение труда: пункты-шаги в список набирает генератор (v5ShagovyiPunkt),
 * а здесь остаётся только смена тега — потому что доля считается по ГОТОВОЙ
 * странице, где к нашим спискам добавились списки виджетов. Проверка тут
 * двойная и обе нужны:
 *   · не меньше пяти списков. На app полоса [0, 20], и один <ol> из четырёх
 *     списков даёт 25% — страница валит приёмку;
 *   · больше половины пунктов — шаговые. Если генератору не хватило записей и
 *     в список попал перечень, нумеровать его нельзя: <ol> обещает порядок.
 */
function v5PoryadokSpiska(string $html, string $тип, string $имяНабора): string
{
    if (!v5NumerovatNabor($тип, $имяНабора)) { return $html; }
    if (preg_match_all('~<ul\b~i', $html) + preg_match_all('~<ol\b~i', $html) < 5) { return $html; }
    $шаги = $тип === 'app' ? '~как установить~ui' : '~как использовать промокод~ui';
    // Голый <ul> без атрибутов — наш список из v5Spisok. У списков виджетов
    // есть классы, и менять им тег нельзя: на них завязана вёрстка.
    if (!preg_match_all('~<ul>\n.*?</ul>~su', $html, $mm, PREG_OFFSET_CAPTURE)) { return $html; }
    foreach ($mm[0] as $m) {
        // Именно H2, а не ближайший заголовок: между «Как установить —
        // Пошагово» и списком стоит H3 раздела, и поиск по h[23] находил его.
        $до = substr($html, 0, $m[1]);
        $заголовок = preg_match_all('~<h2[^>]*>(.*?)</h2>~su', $до, $hh) ? end($hh[1]) : '';
        if (!preg_match($шаги, strip_tags($заголовок))) { continue; }
        preg_match_all('~<li>\s*(.*?)\s*</li>~su', $m[0], $pp);
        $всего = count($pp[1]);
        if ($всего < 3) { continue; }
        $шаговых = count(array_filter($pp[1], 'v5ShagovyiPunkt'));
        if ($шаговых * 2 <= $всего) { continue; }
        return substr($html, 0, $m[1]) . '<ol>' . substr($m[0], 4, -5) . '</ol>'
             . substr($html, $m[1] + strlen($m[0]));
    }
    return $html;
}

function v5Spisok(array $пункты, string $tag = 'ul'): string
{
    $o = "<{$tag}>\n";
    foreach ($пункты as $п) { $o .= "  <li>\n    " . $п . "\n  </li>\n"; }
    return $o . "</{$tag}>";
}

/**
 * Ремонт денежной пары в предложении.
 *
 * Донор пишет ставку числом внутри фразы, а результат отдаёт прорезью {РУБЛИ}.
 * Прорезь в узле выдаётся первой, то есть из младшей — ставочной — половины
 * банка, и герой «заходит с 1000 ₽ и доводит сумму до 200 рублей». Проверка
 * смысла ловит это как «результат меньше ставки»; здесь оно чинится на месте:
 * итог заменяется на запись из банка, которая крупнее ставки, с сохранением
 * написания валюты из исходной фразы.
 *
 * @param array<string, mixed> $рубли банк РУБЛИ: ключи — денежные строки
 */
function v5PochinitDengi(string $html, array $рубли): string
{
    // Банк режется по написанию валюты: «120 000 ₽» и «120 000 рублей» — это
    // разные строки, и подставлять нужно ту, что совпадает с исходной фразой.
    $поВалюте = ['₽' => [], 'рубли' => []];
    foreach (array_keys($рубли) as $s) {
        $s = (string) $s;
        $n = v5Rubli($s);
        // «000 ₽» и «0₽» — обломки разбора: он разорвал «120 000 ₽» по пробелу.
        if ($n < 1000 || preg_match('~^\D*0~u', $s)) { continue; }
        $вид = mb_strpos($s, '₽') !== false ? '₽' : 'рубли';
        $поВалюте[$вид][$n] = trim(preg_replace('~\s*(?:₽|рубл\w+)\s*$~u', '', $s));
    }
    foreach ($поВалюте as &$список) { ksort($список); }
    unset($список);
    if (!$поВалюте['₽'] && !$поВалюте['рубли']) { return $html; }

    $re = '~((?:зашёл|зашла|начал|начала|пополнил|пополнила|поставил|поставила)[^.!?<]{0,80}?'
        . '(\d[\d\x{00A0} ]*?)\s?(?:₽|рубл\w+)[^.!?<]{0,110}?'
        . '(?:довёл|довела|поднял|подняла|вырос\w*|забрал|забрала|до)\s+)'
        . '(\d[\d\x{00A0} ]*?)\s?(₽|рубл\w+)~u';

    return (string) preg_replace_callback($re, function (array $m) use ($поВалюте): string {
        $ставка = v5Rubli($m[2]);
        $итог   = v5Rubli($m[3]);
        if ($ставка <= 0 || $итог > $ставка) { return $m[0]; }
        $вид = $m[4] === '₽' ? '₽' : 'рубли';
        $список = $поВалюте[$вид] ?: ($поВалюте['₽'] ?: $поВалюте['рубли']);
        // Результат в корпусе кратно больше ставки: «зашёл с 1000 ₽ и довёл до
        // 1050 ₽» читается не лучше сломанной подстановки. Порог — десять
        // ставок, с откатом на три и на самую крупную запись банка.
        $новое = null;
        foreach ([10, 3, 1] as $кратность) {
            foreach ($список as $n => $запись) {
                if ($n >= $ставка * $кратность) { $новое = [$n, $запись]; break 2; }
            }
        }
        if ($новое === null || $новое[0] <= $ставка) { return $m[0]; }
        return $m[1] . $новое[1] . ' ' . $m[4];
    }, $html);
}

/**
 * Согласование числительного с существительным времени.
 *
 * Донор пишет «вывод за 3 минуты» — форма верна для двух, трёх и четырёх.
 * Прорезь катит в этот шаблон любое число, и получается «за 20 минуты»,
 * «за 47 минуты». В корпусе такого нет: доноры просто не выпали на другие
 * числа. Правило простое и покрывает весь встречающийся набор слов.
 */
function v5PochinitChislo(string $html): string
{
    static $формы = [
        'минуты'  => ['минута', 'минуты', 'минут'],
        'минут'   => ['минута', 'минуты', 'минут'],
        'часа'    => ['час', 'часа', 'часов'],
        'часов'   => ['час', 'часа', 'часов'],
        'дня'     => ['день', 'дня', 'дней'],
        'дней'    => ['день', 'дня', 'дней'],
        'секунды' => ['секунда', 'секунды', 'секунд'],
        'секунд'  => ['секунда', 'секунды', 'секунд'],
    ];
    $ключи = implode('|', array_keys($формы));

    return (string) preg_replace_callback(
        // Тег между предлогом и числом («до <strong>1 часа</strong>») входит в разбор, иначе предлог не виден.
        '~(\S+\s)?((?:<[^>]+>)?)(\d+)(\s|&nbsp;)(' . $ключи . ')\b~u',
        function (array $m) use ($формы): string {
            // «до 1 часа», «от 40 минут» — родительный по предлогу, это норма.
            static $предлоги = ['до' => 1, 'от' => 1, 'около' => 1, 'порядка' => 1,
                                'свыше' => 1, 'более' => 1, 'менее' => 1];
            // Тег между предлогом и числом не мешает: «<strong>до 24 часов</strong>»
            // читалось как «до 24 часа».
            $перед = trim(strip_tags((string) $m[1]));
            if (isset($предлоги[mb_strtolower($перед)])) { return $m[0]; }

            $n = (int) $m[3];
            $сотня = $n % 100;
            $конец = $n % 10;
            if ($сотня >= 11 && $сотня <= 14) { $форма = 2; }
            elseif ($конец === 1)             { $форма = 0; }
            elseif ($конец >= 2 && $конец <= 4) { $форма = 1; }
            else                                { $форма = 2; }

            return ($m[1] ?? '') . $m[2] . $m[3] . $m[4] . $формы[$m[5]][$форма];
        }, $html);
}

/**
 * Баланс кавычек на странице.
 *
 * В библиотеке попадаются куски, где реплика открылась и не закрылась —
 * разбор донора разрезал цитату пополам. На странице это выглядит как
 * «Мне повезло. без пары или как одинокая » в конце чужой фразы.
 *
 * Считаем только текст вне тегов: в атрибутах кавычки свои. Лишний
 * закрывающий убираем, незакрытый открывающий закрываем по концу его
 * предложения — донор пишет реплику именно так.
 */
function v5PochinitKavychki(string $html): string
{
    // Предложение, начатое ссылкой со строчной: «…завтра минус. <a>информацию о промокодах</a> смотри…».
    $html = (string) preg_replace_callback('~([.!?…]\s+)(<a\b[^>]*>)([а-яё])~u', fn($m) => $m[1] . $m[2] . mb_strtoupper($m[3]), $html);
    // Куски текста вне тегов: смещение в исходной строке и сам текст.
    preg_match_all('~>[^<]+~u', $html, $m, PREG_OFFSET_CAPTURE);
    if (!$m[0]) { return $html; }

    $карта = [];            // позиция в потоке → позиция в html
    $поток = '';
    foreach ($m[0] as [$кусок, $смещение]) {
        $len = strlen($кусок);
        for ($i = 1; $i < $len; $i++) {   // единицу пропускаем: это сам «>»
            $карта[strlen($поток)] = $смещение + $i;
            $поток .= $кусок[$i];
        }
    }

    $правки = [];           // позиция в html → что делать
    $стек = [];
    $длина = strlen($поток);
    for ($i = 0; $i < $длина; $i++) {
        if (substr($поток, $i, 2) === "\xc2\xab") {          // «
            $стек[] = $i;
        } elseif (substr($поток, $i, 2) === "\xc2\xbb") {    // »
            if ($стек) { array_pop($стек); }
            else { $правки[$карта[$i]] = ['убрать', 2]; }
        }
    }
    // Незакрытая реплика: ставим » после конца её предложения.
    foreach ($стек as $поз) {
        $конец = null;
        for ($i = $поз + 2; $i < $длина; $i++) {
            if (strpos('.!?', $поток[$i]) !== false) { $конец = $i; break; }
        }
        if ($конец === null || !isset($карта[$конец])) {
            $правки[$карта[$поз]] = ['убрать', 2];           // закрывать негде — снимаем открывающую
        } else {
            $правки[$карта[$конец] + 1] = ['вставить', "\xc2\xbb"];
        }
    }
    if (!$правки) { return $html; }

    krsort($правки);        // правим с конца, чтобы смещения не поехали
    foreach ($правки as $поз => [$что, $чем]) {
        $html = $что === 'убрать'
            ? substr($html, 0, $поз) . substr($html, $поз + $чем)
            : substr($html, 0, $поз) . $чем . substr($html, $поз);
    }
    return $html;
}

/**
 * Один и тот же виджет лежит в библиотеке под двумя оболочками
 * (faq-section и info-block), поэтому сборка иногда ставит на страницу
 * обе копии: одинаковый заголовок, одинаковый текст и одинаковый
 * id="toc-N". Вторую копию убираем целиком.
 *
 * Копия не всегда обёрнута в свой <div>: бывает голая пара «<h2> плюс
 * следующий блок», и по одному <div> её не поймать. Поэтому идём по
 * верхнеуровневым блокам (нулевой отступ — вложенное генератор всегда
 * печатает с отступом) и склеиваем их в группы: группа начинается на
 * блоке с <h2> и тянется до следующего такого.
 */
function v5UbratDubliVidzhetov(string $html): string
{
    $строки = explode("\n", $html);
    $всего  = count($строки);

    // верхнеуровневые блоки: от «<тег …>» в нулевой колонке до «</тег>» там же
    $блоки = [];
    for ($i = 0; $i < $всего; $i++) {
        if (!preg_match('~^<([a-z0-9]+)\b~', $строки[$i], $m)) { continue; }
        $закрытие = '</' . $m[1] . '>';
        for ($j = $i + 1; $j < $всего; $j++) {
            if ($строки[$j] === $закрытие) {
                $кусок = implode("\n", array_slice($строки, $i, $j - $i + 1));
                $ключ = preg_match('~<h2\b[^>]*>(.*?)</h2>~is', $кусок, $h)
                    ? mb_strtolower(trim(preg_replace('~\s+~u', ' ', strip_tags($h[1]))), 'UTF-8') : '';
                $блоки[] = ['от' => $i, 'до' => $j, 'ключ' => $ключ];
                $i = $j;
                break;
            }
        }
    }

    // группы: заголовок и всё, что идёт за ним до следующего заголовка
    $группы = [];
    foreach ($блоки as $б) {
        if ($б['ключ'] !== '' || !$группы) {
            $группы[] = ['ключ' => $б['ключ'], 'от' => $б['от'], 'до' => $б['до']];
        } else {
            $группы[count($группы) - 1]['до'] = $б['до'];
        }
    }

    $видели = []; $убрать = [];
    foreach ($группы as $г) {
        if ($г['ключ'] === '') { continue; }
        if (isset($видели[$г['ключ']])) {
            for ($k = $г['от']; $k <= $г['до']; $k++) { $убрать[$k] = true; }
        } else {
            $видели[$г['ключ']] = true;
        }
    }
    if (!$убрать) { return $html; }

    $итог = [];
    foreach ($строки as $н => $строка) {
        if (!isset($убрать[$н])) { $итог[] = $строка; }
    }
    return implode("\n", $итог);
}

/**
 * Якоря у заголовков разделов. Конкурент помечает `id="toc-N"` три четверти
 * своих h2, мы — одну седьмую. Правило у него простое и мы его повторяем:
 * якорь получают заголовки разделов (без класса либо с оформительским
 * `gradient-text`), а шапки виджетов — нет.
 *
 * Нумерация сквозная: один и тот же id на странице — битая разметка, а после
 * снятия дубля виджета в нумерации ещё и дыры.
 */
const V5_H2_BEZ_YAKORYA = ['hero-headline', 'value-pillars-heading',
                           'slots-dashboard-title', 'review-quotes-heading'];

function v5PeresobratToc(string $html): string
{
    $н = 0;
    return preg_replace_callback('~<h2\b([^>]*)>~i', function ($m) use (&$н) {
        $атрибуты = $m[1];
        $класс = preg_match('~\sclass="([^"]*)"~', $атрибуты, $к) ? $к[1] : '';
        foreach (V5_H2_BEZ_YAKORYA as $шапка) {
            if (str_contains($класс, $шапка)) { return $m[0]; }
        }
        $н++;
        return preg_match('~\sid="~', $атрибуты)
            ? '<h2' . preg_replace('~\sid="[^"]*"~', ' id="toc-' . $н . '"', $атрибуты, 1) . '>'
            : '<h2' . $атрибуты . ' id="toc-' . $н . '">';
    }, $html);
}

/**
 * Мелочи после всех проходов: род в «выиграл(а)» по имени героя, донорская
 * нумерация вопросов FAQ («3. Будут ли новые слоты?»), строчная после точки
 * перед «если» («это не сюда. если готов»).
 */
/** Ключ вопроса FAQ для сравнения: без тегов, регистра и знаков. */
function v5KlyuchVoprosa(string $в): string
{
    return trim((string) preg_replace('~[^\p{L}\d]+~u', ' ', mb_strtolower(strip_tags($в))));
}

/** Почти один вопрос: общих основ (первые пять букв слов от четырёх букв) не меньше 60 % от короткого. */
function v5PohozhieVoprosy(string $a, string $b): bool
{
    $осн = static fn(string $x): array => array_values(array_unique(array_map(fn($w) => mb_substr($w, 0, 5),
        array_filter(preg_split('~[^\p{L}\d]+~u', mb_strtolower(strip_tags($x)), -1, PREG_SPLIT_NO_EMPTY), fn($w) => mb_strlen($w) >= 4))));
    $A = $осн($a); $B = $осн($b);
    if (count($A) < 2 || count($B) < 2) { return false; }
    $общ = count(array_intersect($A, $B));
    return $общ >= 2 && $общ >= 0.6 * min(count($A), count($B));
}

/** Основы слов от пяти букв (первые пять букв), без тегов и прорезей. */
function v5Osnovy(string $т): array
{
    $т = preg_replace('~\{[^}]*\}~u', ' ', strip_tags($т));
    $о = [];
    foreach (preg_split('~[^\p{L}]+~u', mb_strtolower((string) $т), -1, PREG_SPLIT_NO_EMPTY) as $w) {
        if (mb_strlen($w) >= 5) { $о[mb_substr($w, 0, 5)] = true; }
    }
    return $о;
}

/** Есть ли у двух текстов общая основа (слово от пяти букв). */
function v5ObshchayaOsnova(string $a, string $b): bool
{
    $A = v5Osnovy($a);
    if (!$A) { return true; }
    foreach (v5Osnovy($b) as $к => $_) { if (isset($A[$к])) { return true; } }
    return false;
}

/**
 * Одна шаблонная концовка на блок FAQ: «Если готов(а) — заходи и проверяй сам(а).»,
 * «Решать всё равно тебе.», «Хочешь попробовать — начни с бонуса.» шли в трёх ответах подряд.
 * Повторная последняя фраза снимается, если в ответе остаётся хотя бы два предложения.
 */
/** Почти один ответ: общих основ не меньше половины от короткого, и основ хотя бы пять. */
/** Тема вопроса FAQ для правила «одна тема на блок»: поддержка, телефон, валюта, пароль, верификация, демо, комиссия, налог, закрытие. */
function v5TemaVoprosa(string $в): string
{
    $q = mb_strtolower(strip_tags($в));
    foreach (['поддержка' => '~поддерж|связаться|обращаться|обратиться|куда писать~u', 'телефон' => '~телефон|номер[а]?\s+(?:телефона|мобильн)|без номера~u',
              'валюта' => '~валют~u', 'пароль' => '~парол~u', 'верификация' => '~верифик|документ~u', 'демо' => '~демо|бесплатно~u',
              'комиссия' => '~комисси~u', 'налог' => '~налог~u', 'закрытие' => '~закрыть аккаунт|удалить аккаунт|передума~u'] as $тема => $re) {
        if (preg_match($re, $q)) { return $тема; }
    }
    return '';
}

function v5PohozhieOtvety(string $a, string $b): bool
{
    $A = v5Osnovy($a); $B = v5Osnovy($b);
    if (count($A) < 5 || count($B) < 5) { return false; }
    return count(array_intersect_key($A, $B)) >= 0.5 * min(count($A), count($B));
}

function v5OdnaKontsovka(array $пары): array
{
    $были = [];
    foreach ($пары as $i => $p) {
        $о = (string) ($p['о'] ?? '');
        $предл = preg_split('~(?<=[.!?])\s+~u', trim($о), -1, PREG_SPLIT_NO_EMPTY);
        if (count($предл) < 2) { continue; }
        $посл = end($предл);
        $ключ = trim((string) preg_replace('~[^\p{L}]+~u', ' ', mb_strtolower(str_replace('(а)', '', strip_tags($посл)))));
        if ($ключ === '' || mb_strlen($ключ) > 60) { continue; }
        if (isset($были[$ключ])) {
            array_pop($предл);
            $пары[$i]['о'] = implode(' ', $предл);
        } else {
            $были[$ключ] = true;
        }
    }
    return $пары;
}

/** Семейства мантр — те же, что в sverka-v5.php. */
const V5_MANTRY = [
    '~гаранти[йя]\s+(?:тут\s+|здесь\s+)?(?:нет|никто|не\s+да[её]т)|никаких гарантий|без гарантий~ui',
    '~не\s+сюда~ui',
    '~движ\s+для\s+смелых|для\s+смелых~ui',
    '~можно\s+(?:и\s+)?проиграть|можешь\s+проиграть|исход\s+в\s+обе\s+стороны~ui',
    '~по-честному~ui',
    '~не\s+заход[иь]т?е?,?\s+если|если\s+боишься\s+проиграть|если\s+боитесь\s+проиграть~ui',
];

/**
 * Одна мантра семейства на раздел. У доноров A самое частое семейство встречается в разделе
 * 0.9–2.2 раза, у нас было 2.2–2.7: «гарантий нет» стояло в четырёх абзацах подряд.
 * Второе и дальше вхождения снимаются целым предложением, если в абзаце остаётся хотя бы одно.
 */
function v5MantryPoRazdelu(string $html): string
{
    $куски = preg_split('~(<section\b.*?</section>|<h2\b[^>]*>.*?</h2>)~su', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    $счёт = array_fill(0, count(V5_MANTRY), 0);
    foreach ($куски as $k => $кусок) {
        if ($k % 2 === 1) {
            if (str_starts_with($кусок, '<h2')) { $счёт = array_fill(0, count(V5_MANTRY), 0); }
            continue;
        }
        $куски[$k] = (string) preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su', function ($a) use (&$счёт) {
            $предл = preg_split('~(?<=[.!?…])\s+(?=(?:<strong>|<em>)?\p{Lu}|<)~u', $a[2]);
            if (count($предл) < 2) {
                foreach (V5_MANTRY as $i => $re) { if (preg_match($re, strip_tags($a[2]))) { $счёт[$i]++; } }
                return $a[0];
            }
            $оставить = [];
            foreach ($предл as $п) {
                $чист = strip_tags($п); $снять = false;
                foreach (V5_MANTRY as $i => $re) {
                    if (preg_match($re, $чист)) {
                        if ($счёт[$i] >= 1 && count($оставить) + 1 < count($предл)) { $снять = true; }
                        $счёт[$i]++;
                    }
                }
                if (!$снять) { $оставить[] = $п; }
            }
            if (!$оставить) { $оставить = [$предл[0]]; }
            return $a[1] . implode(' ', $оставить) . $a[3];
        }, $кусок);
    }
    return implode('', $куски);
}

/**
 * Обрывок без героя: короткая фраза с суммой, сроком или «он/его» в разделе, где имени героя
 * не было. У доноров таких нет; у нас — «Между доставками — десять минут перерыва», «Проиграл 10к.».
 */
/**
 * Одна концовка истории на раздел: «через три вечера отыграл и вывел 40к» и
 * следом «отыгрыш закрыл на четвёртый день, баланс показал…» — две записи с
 * собственным финалом в одном разделе. После первой фразы «время + сумма/счёт»
 * следующие такие снимаются из абзаца, если в нём остаётся хоть одно предложение.
 */
function v5OdinIshod(string $html): string
{
    $время = '(?:через\s+(?:\S+\s+){0,2}?(?:минут\w*|час\w*|вечер\w*|дня|дней|день|недел\w*|месяц\w*|сутки)|к\s+(?:утру|полуночи|ночи|двум\s+ночи|воскресенью|вечеру|концу\s+\S+)|на\s+(?:второй|третий|четв[её]ртый|пятый|шестой|седьмой|следующий)\s+(?:день|вечер)|под\s+утро|в\s+тот\s+же\s+вечер)';
    $деньги = '(?:\d[\d\s]*(?:к\b|тыс|млн|₽|руб)|на\s+(?:счету|счёте|балансе)|баланс)';
    $части = preg_split('~(?=<section\b)|(?=<h2\b)~u', $html);
    foreach ($части as &$часть) {
        $была = false;
        $часть = (string) preg_replace_callback('~<(p|li)\b([^>]*)>(.*?)</\1>~su', function ($m) use (&$была, $время, $деньги) {
            $предл = preg_split('~(?<=[.!?…])\s+(?=[«"(]?\p{Lu})~u', $m[3]);
            if (count($предл) < 1) { return $m[0]; }
            $оставить = [];
            foreach ($предл as $п) {
                $чист = strip_tags($п);
                $исход = preg_match('~' . $время . '~ui', $чист) && preg_match('~' . $деньги . '~ui', $чист) && mb_strlen($чист) < 200;
                if ($исход && $была) { continue; }
                if ($исход) { $была = true; }
                $оставить[] = $п;
            }
            if (!$оставить) { return $m[0]; }
            return '<' . $m[1] . $m[2] . '>' . implode(' ', $оставить) . '</' . $m[1] . '>';
        }, $часть);
    }
    return implode('', $части);
}

function v5UbratObryvki(string $html, array $имена, bool $сFaq = false): string
{
    $банк = array_fill_keys($имена, true);
    // Ответы FAQ — не история героя: «Аккаунт закрывается через поддержку…,
    // восстановить его потом нельзя» (11 слов, «его», «через») снимался как
    // обрывок, и от ответа оставалось одно предложение. Абзацы ответов
    // помечаются и проходят нетронутыми.
    $html = (string) preg_replace('~(<div class="faq-answer"[^>]*>\s*<div itemprop="text">\s*)<p\b~u', '$1<p data-faq', $html);
    $куски = preg_split('~(<section\b.*?</section>|<h2\b[^>]*>.*?</h2>)~su', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    $былоИмя = false;
    foreach ($куски as $k => $кусок) {
        if ($k % 2 === 1) {
            if (str_starts_with($кусок, '<h2')) {
                $былоИмя = false;
                if (preg_match_all('~\b(\p{Lu}[а-яё]{2,})\b~u', strip_tags($кусок), $mm)) { foreach ($mm[1] as $w) { if (isset($банк[$w])) { $былоИмя = true; } } }
            }
            continue;
        }
        $куски[$k] = (string) preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su', function ($a) use (&$былоИмя, $банк, $сFaq) {
            $предл = preg_split('~(?<=[.!?…])\s+(?=(?:<strong>|<em>)?\p{Lu}|<)~u', $a[2]);
            $оставить = [];
            // Ответ FAQ чистится только на финальном проходе ($сFaq) и только если
            // после снятия остаётся не меньше двух предложений: сверка считает FAQ
            // прозой и ловит там «Обойти его не получится ни через какой адрес».
            $вFaq = str_contains($a[1], 'data-faq');
            if ($вFaq && !$сFaq) { return $a[0]; }
            foreach ($предл as $п) {
                $чист = trim(strip_tags($п));
                if (preg_match_all('~\b(\p{Lu}[а-яё]{2,})\b~u', $чист, $mm)) { foreach ($mm[1] as $w) { if (isset($банк[$w])) { $былоИмя = true; } } }
                $слов = count(preg_split('~\s+~u', $чист, -1, PREG_SPLIT_NO_EMPTY));
                $обрывок = !$былоИмя && $слов >= 2 && $слов <= 12
                    && preg_match('~\d[\d\s]*\s*(?:₽|руб|к\b|тыс|млн)|\b(?:он|она|его|её|ему|ей)\b|\b(?:минут|часа|часов|секунд)\b~u', $чист)
                    && preg_match('~\b(?:вывел|вывела|закинул|закинула|прош[её]л|прошла|сел|села|забрал|снял|поднял|принёс|принесла|потратил|ушло|висело|лежало|светил[а-яё]*|показывал|плюс|минус|проиграл|слил|через|было|стало|оказалось|капнуло|пришло|упало|перерыв[а-яё]*|ждал|ждала)\b~ui', $чист)
                    && !preg_match('~^(?:если|можно|можешь|минус|плюс|честно|факт)~ui', $чист);
                if (!$обрывок) { $оставить[] = $п; }
            }
            if (!$оставить) { return $вFaq ? $a[0] : ''; }
            if ($вFaq && count($оставить) < 2 && count($предл) >= 2) { return $a[0]; }
            return $a[1] . implode(' ', $оставить) . $a[3];
        }, $кусок);
    }
    return str_replace('<p data-faq', '<p', implode('', $куски));
}

/** Значения RTP, попадающие в полосу страницы; пока база не задана — все. */
function v5RtpPolosa(array $значения, float $ширина = 2.0): array
{
    $база = (float) ($GLOBALS['v5RtpБаза'] ?? 0);
    if ($база <= 0) { return $значения; }
    return array_values(array_filter($значения, fn($x) => abs((float) str_replace(',', '.', (string) $x) - $база) <= $ширина));
}

/** Первое названное на странице RTP становится базой полосы. */
function v5RtpZapomnit(string $значение): string
{
    if (empty($GLOBALS['v5RtpБаза'])) { $GLOBALS['v5RtpБаза'] = (float) str_replace(',', '.', $значение); }
    return $значение;
}

/** RTP страницы — из полосы ±ширина вокруг базы; база разыгрывается один раз на страницу. */
function v5RtpVPolose(array $банки, $rng, float $ширина = 2.0): string
{
    $значения = array_keys($банки['RTP'] ?? []);
    if (!$значения) { return '96'; }
    if (empty($GLOBALS['v5RtpБаза'])) {
        // База — только из «густых» значений: у 92 в полосе ±2 нет соседей,
        // и страница получала одно RTP на всё — разных значений с % выходило 1–3
        // при полосе профиля 4–6.
        $ч = fn($x) => (float) str_replace(',', '.', (string) $x);
        $густые = array_values(array_filter($значения, function ($b) use ($значения, $ч, $ширина) {
            $n = 0; foreach ($значения as $x) { if (abs($ч($x) - $ч($b)) <= $ширина) { $n++; } } return $n >= 6;
        }));
        $GLOBALS['v5RtpБаза'] = $ч($rng->pick($густые ?: $значения));
    }
    $база = (float) $GLOBALS['v5RtpБаза'];
    $полоса = array_values(array_filter($значения, fn($x) => abs((float) str_replace(',', '.', (string) $x) - $база) <= $ширина));
    return (string) $rng->pick($полоса ?: $значения);
}

function v5PochinitMelochi(string $html): string
{
    $html = (string) preg_replace_callback('~(\p{Lu}[а-яё]+)\s+(выиграл|отыграл|снял|поднял|забрал|вывел|сорвал)\(а\)~u',
        fn($m) => $m[1] . ' ' . $m[2] . (v5Rod($m[1]) === 'ж' ? 'а' : ''), $html);
    $html = (string) preg_replace('~(<h3 class="faq-question"[^>]*>\s*)\d+\.\s+~u', '$1', $html);
    // «Вывод за сразу после верификации» — срок-фраза после «за».
    $html = (string) preg_replace('~(?<![а-яё])за\s+сразу\s+после~u', 'сразу после', $html);
    $html = (string) preg_replace('~(?<![а-яё])за\s+(в течение)~u', '$1', $html);
    // «до 1 час» → «до 1 часа», «до 3 час» → «до 3 часов».
    $html = (string) preg_replace_callback('~(?<![а-яё])до\s+(\d+)\s+час(?![а-яё])~u', fn($m) => 'до ' . $m[1] . ($m[1] === '1' ? ' часа' : ' часов'), $html);
    $html = (string) preg_replace_callback('~([.!?])(\s+)(если|а если|но если|и если)(?=\s)~u',
        fn($m) => $m[1] . $m[2] . mb_strtoupper(mb_substr($m[3], 0, 1)) . mb_substr($m[3], 1), $html);
    // «занимает около до 48 минут»: срок-фраза уже со своим «до».
    $html = (string) preg_replace('~(?<![а-яё])около\s+до\s+(\d)~u', 'до $1', $html);
    // «движ для смелых, но только.» — хвост после снятого повтора («с суммой, которую не жалко потерять»).
    $html = (string) preg_replace('~\s*[,—–-]?\s*(?:но|а|и)\s+только\s*([.!?])~u', '$1', $html);
    // «со 7 449 ₽» → «с 7 449 ₽»: «со» оставляется только перед сотней («со 100», «со 150»).
    $html = (string) preg_replace_callback('~(?<![а-яё])([Сс])о\s+(\d[\d ]*)(?=\D)~u', function ($m) {
        $ц = str_replace(' ', '', $m[2]);
        return (strlen($ц) === 3 && $ц[0] === '1') ? $m[0] : $m[1] . ' ' . $m[2];
    }, $html);
    // «Ставка 9 113 ₽ рублей» — знак валюты и слово вместе.
    $html = (string) preg_replace('~₽\s+рублей~u', '₽', $html);
    // «4 833слотов», «2 381игр» — число прилипло к слову.
    $html = (string) preg_replace('~(\d)(слот|игр|автомат|провайдер|турнир|фриспин|спин)(?=[а-яё]*(?![а-яё]))~u', '$1 $2', $html);
    // «вывод за 30–9 минут» — перевёрнутый диапазон.
    $html = (string) preg_replace_callback('~(?<![\d.,])(\d{1,3})\s*[–-]\s*(\d{1,3})(\s*(?:минут|мин(?![а-яё])|часов|часа|дней|дня|секунд))~u',
        fn($m) => (int) $m[1] > (int) $m[2] ? $m[2] . '–' . $m[1] . $m[3] : $m[0], $html);
    // «7–7 минут» — диапазон с равными концами после выравнивания сроков.
    $html = (string) preg_replace('~(?<![\d.,])(\d{1,3})\s*[–-]\s*\1(?=\s*(?:минут|мин(?![а-яё])|часов|часа|дней|дня|секунд|%))~u', '$1', $html);
    // «отдача 97.8 не зависит», «При одинаковом 92 два автомата» — RTP без знака процента.
    $html = (string) preg_replace('~(?<![\d.,])((?:8\d|9\d)\.\d)(?![\d%]|\s*(?:%|млн|тыс|к(?![а-яё])))~u', '$1%', $html);
    $html = (string) preg_replace('~((?:RTP|отдач[а-яё]+|одинаковом|означает|показател[ьяе]+)\s+)((?:8\d|9\d))(?![\d.,%]|\s*%)~u', '$1$2%', $html);
    // Заголовок целиком внутри ссылки — заголовок остаётся, ссылка нет.
    $html = (string) preg_replace('~<(h[23])([^>]*)>\s*<a\b[^>]*>(.*?)</a>\s*</\1>~su', '<$1$2>$3</$1>', $html);
    return $html;
}

/** Ставка партнёрки — одна на набор: у доноров на partnery одна-две цифры ревшары, у нас было до десяти. */
function v5Revshara(int $сид): string
{
    return (string) [25, 30, 35, 40, 45, 50][crc32('ревшара|' . $сид) % 6];
}

/**
 * На partnery все проценты «от дохода / RevShare / ревшары / GGR / с оборота» — одна цифра набора.
 * Литералы доноров («до 50% RevShare», «18% от дохода») и записи с {ДОЛЯ} в этой роли
 * («RevShare до 600%») выравниваются на неё; диапазон «от X% до Y%» — X на десять ниже.
 */
function v5RovnayaRevshara(string $html, string $ревшара, bool $всяСтраница = true): string
{
    $р = (int) $ревшара; $н = max(10, $р - 15);
    $роль = '(?:от\s+(?:чистого\s+)?дохода|revenue\s+share|revshare|ревшар[а-яё]*|от\s+ggr|с\s+каждой\s+ставки|(?:с|от)\s+(?:их\s+)?(?:оборота|ставок)|от\s+депозитов|от\s+прибыли|партн[её]рских\s+отчислен[а-яё]+|партн[её]рск[а-яё]+\s+вознаграждени[а-яё]+|вознаграждени[ея])';
    $тег = '(?:\s*</?(?:strong|b|em)>)*';
    $html = (string) preg_replace('~(?<![\d.,])\d{1,3}(\s*%' . $тег . '\s*' . $роль . ')~ui', $р . '$1', $html);
    $html = (string) preg_replace('~((?:revshare|ревшар[а-яё]*|revenue\s+share)' . $тег . '\s*[:—-]?\s*(?:партн[её]р[а-яё]*\s+)?(?:до|достигает|доходит\s+до)\s+)\d{1,3}(?=\s*%)~ui', '${1}' . $р, $html);
    $html = (string) preg_replace('~(до\s+)\d{1,3}(\s*%' . $тег . '\s*(?:от\s+(?:чистого\s+)?дохода|revenue\s+share|revshare|ревшар))~ui', '${1}' . $р . '$2', $html);
    // «Ревшара от 45% до 47%», «Процент от 10% до 60%» — оба конца от ставки набора.
    $html = (string) preg_replace_callback('~((?:revshare|ревшар[а-яё]*|процент[а-яё]*|комисси[яию]|доля|вознаграждени[ея]|отчислени[яе])' . $тег . '\s+(?:—\s*)?(?:здесь\s+)?(?:от|с)\s+)\d{1,3}(%?\s*(?:до|—|–|-)\s*)\d{1,3}(?=\s*%)~ui', fn($m) => $m[1] . $н . $m[2] . $р, $html);
    if (!$всяСтраница) { return $html; }
    $html = (string) preg_replace('~((?:комисси[яю]|ставк[аи]|процент[а-яё]*|доля|вознаграждени[ея])\s+(?:—\s*)?(?:партн[её]р[а-яё]*\s+)?до\s+)\d{1,3}(?=\s*%)~ui', '${1}' . $р, $html);
    $html = (string) preg_replace_callback('~(новичкам\s+(?:от|с)\s+)\d{1,3}(\s*%[^.;]{0,30}?(?:активным|дальше|потом|опытным)\s+(?:до|—)\s+)\d{1,3}(?=\s*%)~ui', fn($m) => $m[1] . $н . $m[2] . $р, $html);
    $html = (string) preg_replace_callback('~(проценты\s+здесь\s+от\s+)\d{1,3}(%\s+до\s+)\d{1,3}(?=%)~ui', fn($m) => $m[1] . $н . $m[2] . $р, $html);
    // «комиссия достигает 40%», «Максимальный процент доходит до 50%», «стартует от 25%», «получил 60% с их ставок»,
    // «до 40% на старте» — на partnery это про ревшару, если рядом не бонус, RTP или кэшбэк.
    $чужое = '~rtp|отдач|бонус|пакет|к[эе]шб|депозит|фриспин|засчит|вклад|кпи|cpa|конверси~ui';
    $поКонтексту = function (string $regex, string $значение) use (&$html, $чужое): void {
        $html = (string) preg_replace_callback($regex, function ($m) use ($html, $значение, $чужое) {
            $до = mb_substr(strip_tags(substr($html, max(0, $m[0][1] - 90), $m[0][1] - max(0, $m[0][1] - 90))), -70);
            return preg_match($чужое, $до) ? $m[0][0] : $m[1][0] . $значение;
        }, $html, -1, $c, PREG_OFFSET_CAPTURE);
    };
    $поКонтексту('~((?:достигает|доходит\s+до|поднимается\s+до|вырастает\s+до|растёт\s+до|максимум\s+—?\s*)\s*)\d{1,3}(?=\s*%)~ui', (string) $р);
    $поКонтексту('~((?:стартует\s+от|стартуешь\s+(?:с|от)|начинаешь\s+(?:с|от)|начинается\s+(?:с|от)|на\s+старте\s+(?:—\s*)?(?:от|с)?)\s*)\d{1,3}(?=\s*%)~ui', (string) $н);
    $поКонтексту('~((?:получил[аи]?|получаете|получаешь|отдают|платят|забираете|забираешь)\s+(?:до\s+)?)\d{1,3}(?=\s*%' . $тег . '\s+(?:с|от)\s+)~ui', (string) $р);
    $поКонтексту('~(до\s+)\d{1,3}(?=\s*%' . $тег . '\s+на\s+старте)~ui', (string) $р);
    return $html;
}

/**
 * Срок вывода — один на раздел. Карточка раздела (часть 63) держит прорезь
 * {МИН}, но в записях пулов срок часто вписан словами: «вывод за 2–3 часа»,
 * «до 24 часов», «мгновенно через СБП». Чтение набора 498 нашло это в одном
 * списке: «Вывод до 1 часа» и следующим пунктом «Вывод средств до 24 часов».
 * Первое упоминание в разделе задаёт срок, последующие переписываются под него
 * с правильным падежом — предлог записи сохраняется.
 */
function v5OdinSrokVyvoda(string $html): string
{
    $части = preg_split('~(?=<h2\b)|(?=<section\b)~u', $html);
    foreach ($части as &$часть) { $часть = v5SrokVRazdele($часть); }
    return implode('', $части);
}

/**
 * Плоский текст из кусков preg_split по тегам и смещения кусков в нём. Нужен
 * обоим проходам ниже: ключевое слово может стоять и до числа, и после него
 * («Моментальный вывод средств», «бонус 286% на первый депозит»), а окно,
 * смотревшее только назад, такие места пропускало.
 */
function v5PloskiyTekst(array $куски): array
{
    $плоский = ''; $смещения = [];
    foreach ($куски as $и => $к) {
        if ($к === '' || ($к[0] ?? '') === '<') { continue; }
        $смещения[$и] = strlen($плоский);
        $плоский .= $к;
    }
    return [$плоский, $смещения];
}

/** Предложение вокруг позиции: от ближайшего знака конца слева до ближайшего справа. */
function v5PredlozhenieVokrug(string $плоский, int $поз): string
{
    $начало = 0;
    $слева = substr($плоский, 0, $поз);
    if (preg_match_all('~[.!?;]~u', $слева, $м, PREG_OFFSET_CAPTURE)) {
        $последний = end($м[0]);
        $начало = $последний[1] + strlen($последний[0]);
    }
    $конец = strlen($плоский);
    if (preg_match('~[.!?;]~u', substr($плоский, $поз), $м2, PREG_OFFSET_CAPTURE)) {
        $конец = $поз + $м2[0][1];
    }
    return trim(substr($плоский, $начало, $конец - $начало));
}

function v5SrokSlovo(string $чис, string $ед, bool $родительный): string
{
    $последнее = (int) preg_replace('~^.*?[–—-]\s*~u', '', str_replace(' ', '', $чис));
    $один = $последнее % 10 === 1 && $последнее % 100 !== 11;
    $мало = in_array($последнее % 10, [2, 3, 4], true) && !in_array($последнее % 100, [12, 13, 14], true);
    if ($ед === 'сут') { return $родительный ? 'суток' : ($один ? 'сутки' : 'суток'); }
    if ($ед === 'час') {
        if ($родительный) { return $один ? 'часа' : 'часов'; }
        return $один ? 'час' : ($мало ? 'часа' : 'часов');
    }
    if ($родительный) { return $один ? 'минуты' : 'минут'; }
    return $один ? 'минуту' : ($мало ? 'минуты' : 'минут');
}

function v5SrokFraza(array $канон, string $предлог): string
{
    if ($канон['вид'] === 'мгн') { return 'мгновенно'; }
    // «до», «в течение», «в пределах» требуют родительного падежа, «за» и
    // «через» — винительного; без предлога берём именительный (он совпадает
    // с винительным в этих сочетаниях: «время вывода 26 минут»).
    $род = in_array($предлог, ['до', 'в течение', 'в пределах'], true);
    $слово = v5SrokSlovo($канон['чис'], $канон['ед'], $род);
    $чис = $канон['ед'] === 'сут' ? '' : $канон['чис'] . ' ';
    return trim(($предлог !== '' ? $предлог . ' ' : '') . $чис . $слово);
}

function v5SrokVRazdele(string $часть): string
{
    // Слова, рядом с которыми число времени — это срок вывода, а не длина
    // сессии: «через 20 минут игры» и «за три часа поднял» трогать нельзя.
    $рядом = '~(?:вывод|вывел|вывес|вывед|выплат|выплач|снима|сним|сня|зачисл|приход|пришл|прид[её]т|прид[уё]|на\s+карт|на\s+сч[её]т|заявк|переч[ие]сл|деньги)~ui';
    // История героя — не заявленный срок: «вытащил 74к и вывел за 5 минут»
    // остаётся как есть, и канон из него не берётся.
    $герой = '~(?:вывел|вывела|снял|сняла|забрал|забрала|вытащил|вытащила|получил|получила|пришли|пришло|дошли|дошло|упал\w*|оказал\w*)~ui';
    // Вторая величина, помеченная как исключение, — законная: «обычно 40 минут,
    // редко задержки до суток». Схлопывание таких пар давало «заявка за 40 минут,
    // а полный вывод средств обычно занимает 40 минут» (чтение набора 504).
    $исключение = '~(?:редк|иногда|бывает|в\s+худшем|максимум|не\s+более|задержк|при\s+проверк|при\s+верификац|полн\w+\s+вывод|дольше|затянут|в\s+пиков)~ui';
    // «15 минут назад» — давность события, а не срок вывода. Виджет последних
    // выплат стоит под заголовком «Последние выплаты», слово «выплат» попадает
    // в окно, и проход сводил все двенадцать строк к одному времени: у нас
    // 17 % страниц с виджетом показывали двенадцать выплат «15 минут назад»
    // подряд, тогда как у корпуса таких страниц нет ни одной (пять-шесть
    // разных значений на каждой).
    // `(?![а-яё])` перед запретом «назад» обязателен: без него `\w*` откатывалась
    // внутрь слова. «24 минуты назад» из ленты выплат не отсекалось запретом —
    // движок отступал к «24 минут», хвост «ы» оставался снаружи, и в выдачу
    // уходило «24 минутыы назад». Пятьдесят два таких места на партию.
    $срок = '~(?<![\d.,])(?:(?P<пред>за|до|в\s+течение|в\s+пределах|через)\s+)?(?P<чис>\d{1,3}(?:\s*[–—-]\s*\d{1,3})?)\s*(?P<ед>минут\w*|час\w*|суток|сутки|сут\w*)(?![а-яё])(?!\s*назад)'
          . '|(?P<мгн>мгновенно|моментально|мгновенн(?P<оконч1>ый|ая|ое|ые|ым|ого|ой)|моментальн(?P<оконч2>ый|ая|ое|ые|ым|ого|ой))(?![а-яё])~ui';
    $канон = null;
    $куски = preg_split('~(<[^>]*>)~u', $часть, -1, PREG_SPLIT_DELIM_CAPTURE);
    [$плоский, $смещения] = v5PloskiyTekst($куски);
    foreach ($куски as $и => $кусок) {
        if ($кусок === '' || ($кусок[0] ?? '') === '<') { continue; }
        if (!preg_match('~\d|мгновенн|моментальн~ui', $кусок)) { continue; }
        if (!preg_match_all($срок, $кусок, $все, PREG_SET_ORDER | PREG_OFFSET_CAPTURE)) { continue; }
        $сдвиг = 0; $новый = $кусок;
        foreach ($все as $m) {
            [$текст, $поз] = $m[0];
            // Окно — всё предложение, в обе стороны от числа.
            $окно = v5PredlozhenieVokrug($плоский, ($смещения[$и] ?? 0) + $поз);
            if (!preg_match($рядом, $окно) || preg_match($герой, $окно)) { continue; }
            // Прилагательное («Моментальный вывод средств») сроком не переписать:
            // «за 27 минут вывод средств» — это уже не по-русски. Такое место
            // просто перестаёт спорить с разделом: «Быстрый вывод средств».
            $оконч = ($m['оконч1'][0] ?? '') !== '' ? $m['оконч1'][0] : ($m['оконч2'][0] ?? '');
            if ($оконч !== '') {
                if ($канон === null || $канон['вид'] === 'мгн') { continue; }
                $замена = 'быстр' . $оконч;
                // Заглавная буква записи сохраняется: пункт списка начинается с неё.
                if (preg_match('~^\p{Lu}~u', $текст)) { $замена = mb_strtoupper(mb_substr($замена, 0, 1)) . mb_substr($замена, 1); }
                $новый = substr_replace($новый, $замена, $поз + $сдвиг, strlen($текст));
                $сдвиг += strlen($замена) - strlen($текст);
                continue;
            }
            $это = isset($m['мгн']) && $m['мгн'][0] !== ''
                ? ['вид' => 'мгн']
                : ['вид' => 'чис', 'чис' => preg_replace('~\s*([–—-])\s*~u', '$1', trim($m['чис'][0])),
                   'ед' => str_starts_with(mb_strtolower($m['ед'][0]), 'час') ? 'час'
                        : (str_starts_with(mb_strtolower($m['ед'][0]), 'сут') ? 'сут' : 'минут')];
            if (preg_match($исключение, $окно)) { continue; }
            // Противопоставление — не спор двух сроков, а фигура речи: «вывод
            // занял 40 минут, а не мгновенно». Схлопывание давало «занял 2-5
            // минут, а не за 2-5 минут» — фраза читается как явный брак, и
            // нашлась она в четырёх наборах из двадцати (у корпуса таких нет).
            $предСлева = mb_substr(substr($плоский, 0, ($смещения[$и] ?? 0) + $поз), -14);
            if (preg_match('~(?:а|но)\s+не\s*(?:за|в|через|быстрее)?\s*$~ui', $предСлева)) { continue; }
            if ($канон === null) { $канон = $это; continue; }
            if ($канон === $это) { continue; }
            $пред = isset($m['пред']) && $m['пред'][0] !== '' ? preg_replace('~\s+~u', ' ', mb_strtolower($m['пред'][0])) : '';
            // «Мгновенно» вместо числа оставляет фразу без предлога: «деньги
            // приходят мгновенно» → «приходят за 26 минут», а не «приходят 26 минут».
            if ($это['вид'] === 'мгн' && $канон['вид'] === 'чис' && $пред === '') { $пред = 'за'; }
            $замена = v5SrokFraza($канон, $канон['вид'] === 'мгн' ? '' : $пред);
            $новый = substr_replace($новый, $замена, $поз + $сдвиг, strlen($текст));
            $сдвиг += strlen($замена) - strlen($текст);
        }
        $куски[$и] = $новый;
    }
    return implode('', $куски);
}

/**
 * Процент приветственного пакета — один на набор. Пакет у площадки один, и
 * «Красная дорожка до 150%» в шапке при «до 250%» и «75%» в тексте той же
 * страницы — первое, что видит читатель (чтение набора 498: 15 значений на
 * набор). Другие проценты — релоад, кэшбэк, ревшара, бонус за установку —
 * не трогаем: у доноров разных процентов на страницу 4.9.
 */
/**
 * Ответ без вопроса. Абзац начинается со связки — «Потому что за щедрым
 * процентом обычно стоит более жёсткий отыгрыш», «Причина банальная — не
 * прошёл верификацию», — а вопроса перед ней нет ни в этом абзаце, ни в
 * заголовке. Читается как обрубленный диалог.
 *
 * Отбор такие записи отсеивает, но когда пул кандидатов исчерпан, второй
 * проход берёт что есть, и связка проскакивает. Замер: у нас четверть связок
 * оставалась висячей, у корпуса из 102 наборов — седьмая часть.
 *
 * Здесь связка просто снимается, а фраза остаётся: «Потому что за щедрым
 * процентом…» → «За щедрым процентом…». Если после связки шло двоеточие или
 * тире, они уходят вместе с ней.
 */
/**
 * Анкор в падеже, которого требует управление.
 *
 * Читая 608, видно: «Он вывел 350к через войти в аккаунт», «96.8% те же,
 * что в обзор бонусной программы», «Следи за новости о слотах». Анкор
 * вставлен в словарной форме, а рамка требует другой. Замер по партии
 * 601–610: 53 сбоя на десять наборов, источник — 423 записи пула, руками
 * столько не переписывают.
 *
 * Проход работает только там, где падеж определяется однозначно:
 * предлог с жёстким управлением, либо управляющее слово при «в/на», либо
 * анкор-инфинитив после любого предлога. Всё остальное не трогается.
 */
/**
 * Бренд-ключ по норме корпуса.
 *
 * Замер по 43 чужим наборам (516 страниц) против нашей партии 601–610:
 * бренд-ключ у нас 0.97 на 1000 слов, у корпуса 2.42. На slots, bonus и
 * promo у нас ноль при корпусных 1.4–1.7; на zerkalo 0.69 против 3.97.
 * При этом «площадка» у нас 1.9 на страницу против корпусных 0.7 — мы
 * зовём площадку обезличенно там, где чужие ставят имя.
 *
 * Два приёма, оба взяты из корпуса:
 *   1. «площадк-» уступает место бренду: «условия площадки» → «условия
 *      %brand_name_ru%». Ключ несклоняем, и корпус ставит его после любого
 *      предлога — «в %brand_name_ru%» 175 раз, «на» 18, «через» 10.
 *   2. Бренд цепляется к ключу страницы: «Промокод %brand_name_ru% не
 *      гарантирует начисление», «Промо-раздел %brand_name_ru%», «внутри
 *      %brand_name_ru%». Так корпус набирает бренд на slots/bonus/promo,
 *      где слова «площадка» нет вовсе.
 *
 * Проход добирает до корпусной нормы и останавливается: перебор хуже
 * недобора, потому что бренд-ключ разворачивается в имя на выдаче.
 */
/**
 * Плотность ключей по медиане корпуса.
 *
 * Замер по 43 чужим наборам: «слот» у нас 4.22 на 1000 слов против 6.26,
 * «бонус» 7.37 против 9.65, имена героя 2.07 против 3.68. При этом по
 * соседним словам у нас избыток ровно там, где недобор по ключу:
 * «автомат» 4.94 против корпусных 2.43, «подарок» 1.17 против 0.78,
 * местоимения героя 4.63 против 4.12. Мы говорим то же самое другими
 * словами — проход возвращает ключевые.
 *
 * Работает в прозе и пунктах списка. Заголовки не трогает: они приходят
 * из пула целиком, и подмена слова в заголовке ломает перекличку с h3.
 */
/**
 * Добор ссылок до полосы профиля.
 *
 * Одиннадцать типов страниц из двенадцати шли ниже собственной полосы:
 * slots 26 при полосе 31–55, bonus 27 при 35–59, zerkalo 28 при 34–59,
 * main 52 при 59–76. Приёмка это печатала точкой, а не провалом, и недобор
 * ехал в выдачу шесть сотен наборов подряд.
 *
 * Причина структурная: ссылки живут внутри записей пула, а наши
 * собственные записи их не несут — у доноров ссылки есть в трети записей,
 * у наших нет вовсе. Чем выше доля своих записей, тем меньше ссылок.
 *
 * Отсюда и недобор ключей: «обзор казино», «регистрацию», «промокоды»,
 * «промо акции», «играть бесплатно», «слоты» — это всё тексты анкоров.
 * Корпус ставит 43.1 ссылки на страницу, мы 33.5, и разрыв по ключам
 * повторяет разрыв по ссылкам.
 *
 * Проход не меняет ни буквы: он оборачивает в ссылку слово, которое уже
 * стоит в тексте в нужной форме. Берутся только абзацы и пункты без
 * ссылок — правило «один анкор на абзац» остаётся в силе.
 */
/**
 * Разброс цели по сиду набора.
 *
 * Замер по 43 чужим наборам против нашей десятки: коэффициент вариации
 * бренд-ключа у корпуса 0.35 (без выброса turbo), у нас 0.05; по ссылкам
 * 0.40 против наших 0.02. Десять наших наборов укладываются в 42.25–45.00
 * ссылки на страницу, а у чужих один набор даёт 6.25, другой 68.08.
 *
 * Корпус из независимых сайтов так и выглядит: каждый писал свой движок со
 * своей политикой. Наша ровность сама по себе отпечаток — совпадаем между
 * собой точнее, чем чужие совпадают друг с другом.
 *
 * Коэффициент берётся от сида набора, а не страницы: все двенадцать страниц
 * одного набора живут по одной политике, как один сайт.
 */
function v5RazbrosPoSidu(int $сид, string $ключ, float $низ, float $верх): float
{
    $доля = (crc32('разброс|' . $ключ . '|' . $сид) % 1000) / 999.0;
    return $низ + ($верх - $низ) * $доля;
}

/**
 * Добор «казино», «джекпота» и имени героя до медианы корпуса.
 *
 * Замер по 43 чужим наборам против партии 611–620: «казино» у нас 3.74 на
 * 1000 слов против 5.55, «джекпот» 2.73 против 3.58, имена героя 2.53
 * против 4.15. Прямого запаса на весь разрыв нет, поэтому три приёма.
 *
 *   1. Остаток «площадки» уходит «казино». Брендовый проход берёт две трети
 *      вхождений себе, у нас остаётся 0.99 против корпусных 0.24 — этот
 *      излишек и есть источник.
 *   2. «Приз» уступает «джекпоту» там, где речь о главном призе: у нас
 *      «приз» 0.80 против корпусных 0.42, а «джекпот» недобран.
 *   3. Имя цепляется к ключу страницы так же, как бренд: корпус пишет
 *      «слоты казино», «бонусы казино», «новости казино».
 */
function v5DoborKlyuchey(string $html, string $тип, int $сид = 0): string
{
    static $нормаКазино = [
        'main' => 7.43, 'obzor' => 10.14, 'slots' => 3.20, 'bonus' => 4.53,
        'promo' => 3.40, 'registracia' => 4.93, 'vhod' => 6.71, 'zerkalo' => 5.23,
        'app' => 4.34, 'news' => 7.81, 'partnery' => 3.84, 'info' => 10.23,
    ];
    $плоский = preg_replace('~\s+~u', ' ', strip_tags($html));
    $слов = max(1, count(preg_split('~\s+~u', trim($плоский))));

    // ── 1. «приз» уступает «джекпоту» ──
    $естьДж = preg_match_all('~джекпот\w*~ui', $плоский);
    $надоДж = (int) round(3.58 * $слов / 1000) - $естьДж;
    if ($надоДж > 0) {
        $n = 0;
        $html = preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su',
            static function (array $бл) use (&$надоДж, &$n, $сид): string {
                if ($надоДж <= 0 || str_contains($бл[2], '<a ')) { return $бл[0]; }
                $тело = preg_replace_callback('~\b(главный\s+)?приз(ом|а|у|е|ы|ов)?\b~ui',
                    static function (array $м) use (&$надоДж, &$n, $сид): string {
                        if ($надоДж <= 0) { return $м[0]; }
                        $n++;
                        if ((crc32('приз|' . $сид . '|' . $n) % 3) === 0) { return $м[0]; }
                        $надоДж--;
                        $хвост = $м[2] ?? '';
                        $форма = ['' => 'джекпот', 'ом' => 'джекпотом', 'а' => 'джекпота',
                                  'у' => 'джекпоту', 'е' => 'джекпоте', 'ы' => 'джекпоты', 'ов' => 'джекпотов'];
                        $новое = $форма[$хвост] ?? 'джекпот';
                        return preg_match('~^[А-ЯЁ]~u', $м[0])
                            ? mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1) : $новое;
                    }, $бл[2], 1);
                return $бл[1] . ($тело ?? $бл[2]) . $бл[3];
            }, $html) ?? $html;
    }

    // ── 2–3. «казино»: остаток «площадки», потом привязка к ключу ──
    $цель = ($нормаКазино[$тип] ?? 5.0) * v5RazbrosPoSidu($сид, 'казино', 0.8, 1.2);
    $надо = (int) round($цель * $слов / 1000) - preg_match_all('~\bказино\b~ui', $плоский);
    if ($надо <= 0) { return $html; }

    $опред = 'сам(?:а|ой|у|и|их|ими)|эт(?:а|ой|у|и|их|ими)|наш(?:а|ей|у|и|их|ими)'
        . '|т(?:а|ой|у|е|ех|еми)|данн(?:ая|ой|ую|ые|ых|ыми)|любим(?:ая|ой|ую|ые|ых|ыми)'
        . '|честн(?:ая|ой|ую|ые|ых|ыми)|лучш(?:ая|ей|ую|ие|их|ими)|мног(?:ие|их|ими)|все|всех';
    $html = preg_replace_callback('~(\S+\s+)?\bплощадк(?:а|и|е|у|ой|ам|ами|ах)\b~ui',
        static function (array $м) use (&$надо, $опред): string {
            if ($надо <= 0) { return $м[0]; }
            $перед = trim((string) ($м[1] ?? ''));
            if ($перед !== '' && preg_match('~^(?:' . $опред . ')$~ui', $перед)) { return $м[0]; }
            // Падеж «казино» не имеет — слово несклоняемое, встаёт в любую рамку.
            $надо--;
            return ($м[1] ?? '') . 'казино';
        }, $html) ?? $html;
    if ($надо <= 0) { return $html; }

    // Привязка к ключу страницы: «слоты казино», «бонусы казино».
    static $ключи = [
        'slots' => 'слоты|слотов|каталог', 'bonus' => 'бонусы|бонусов|акции',
        'promo' => 'промокоды|акции|турниры', 'zerkalo' => 'зеркало|адрес|доступ',
        'app' => 'приложение|версия', 'news' => 'новости|обновления',
        'partnery' => 'программа|партнёрка', 'info' => 'правила|условия|поддержка',
        'main' => 'каталог|бонусы|слоты', 'obzor' => 'обзор|отзывы|рейтинг',
        'registracia' => 'регистрация|аккаунт', 'vhod' => 'вход|кабинет',
    ];
    $ключ = $ключи[$тип] ?? null;
    if ($ключ === null) { return $html; }
    $m = 0;
    return (string) preg_replace_callback('~(<p\b[^>]*>)(.*?)(</p>)~su',
        static function (array $аб) use (&$надо, &$m, $ключ, $сид): string {
            if ($надо <= 0 || preg_match('~\bказино\b~ui', strip_tags($аб[2]))) { return $аб[0]; }
            $куски = preg_split('~(<a\b[^>]*>.*?</a>)~su', $аб[2], -1, PREG_SPLIT_DELIM_CAPTURE);
            $готово = false;
            foreach ($куски as $i => $к) {
                if ($готово || $надо <= 0 || str_starts_with($к, '<a')) { continue; }
                $новый = preg_replace_callback('~\b(' . $ключ . ')\b(?!\s+казино)~ui',
                    static function (array $м) use (&$надо, &$m, &$готово, $сид): string {
                        if ($готово || $надо <= 0) { return $м[0]; }
                        $m++;
                        if ((crc32('казино-ключ|' . $сид . '|' . $m) % 2) !== 0) { return $м[0]; }
                        $надо--; $готово = true;
                        return $м[1] . ' казино';
                    }, $к, 1);
                $куски[$i] = $новый ?? $к;
            }
            return $аб[1] . implode('', $куски) . $аб[3];
        }, $html) ?: $html;
}

/**
 * Добор ключей «бонус» и «джекпот» до корпусной плотности по типам страниц.
 *
 * Замер по 31 чужому набору, медиана на 1000 слов: «бонус» у них 10.4 против
 * наших 7.8, «джекпот» 3.8 против 2.8. Разрыв не общий, а по типам: на main и
 * slots мы уже в полосе, а на zerkalo, partnery, info и vhod отстаём вдвое.
 *
 * Два приёма, оба без выдумывания фактов:
 *  1. Синонимы уступают ключу: «подарок» → «бонус», «куш» → «джекпот». Каждое
 *     второе вхождение — иначе пропадает само слово, а у чужих оно живёт.
 *  2. Согласованное определение: «пакет» → «бонусный пакет», «баланс» →
 *     «бонусный баланс». Ключ прибавляется, а смысл не меняется. Слово с уже
 *     стоящим определением не трогаем — «щедрый пакет» своё определение имеет.
 */
function v5DoborBonusa(string $html, string $тип, int $сид = 0): string
{
    // Медианы NEW100 по 82 обычным наборам: прежние числа сняты со старого
    // корпуса и на bonus, info и partnery завышены.
    static $нормаБонус = [
        'main' => 7.1, 'obzor' => 7.9, 'slots' => 7.7, 'bonus' => 22.2, 'promo' => 11.7,
        'registracia' => 9.0, 'vhod' => 7.7, 'zerkalo' => 7.1, 'app' => 9.6,
        'news' => 7.8, 'partnery' => 4.2, 'info' => 5.6,
    ];
    static $нормаДжекпот = [
        'main' => 4.0, 'obzor' => 4.1, 'slots' => 6.5, 'bonus' => 4.1, 'promo' => 3.7,
        'registracia' => 3.4, 'vhod' => 2.8, 'zerkalo' => 3.2, 'app' => 3.1,
        'news' => 3.6, 'partnery' => 3.1, 'info' => 3.4,
    ];
    $плоский = preg_replace('~\s+~u', ' ', strip_tags($html));
    $слов = max(1, count(preg_split('~\s+~u', trim($плоский))));

    // ── джекпот: «куш» уступает ключу ──
    $цельДж = ($нормаДжекпот[$тип] ?? 3.2) * v5RazbrosPoSidu($сид, 'джекпот', 0.85, 1.15);
    $надоДж = (int) round($цельДж * $слов / 1000) - preg_match_all('~\bджекпот\w*~ui', $плоский);
    if ($надоДж > 0) {
        static $куш = ['куш' => 'джекпот', 'куша' => 'джекпота', 'кушу' => 'джекпоту',
            'кушем' => 'джекпотом', 'куше' => 'джекпоте', 'куши' => 'джекпоты', 'кушей' => 'джекпотов'];
        $n = 0;
        $html = (string) preg_replace_callback('~\b(куш(?:а|у|ем|е|и|ей)?)\b~ui',
            static function (array $м) use (&$надоДж, &$n, $куш, $сид): string {
                if ($надоДж <= 0) { return $м[0]; }
                $n++;
                // Каждое второе: слово у чужих живёт, и выбрасывать его целиком
                // значит менять словарь, а не плотность ключа.
                if ((crc32('куш|' . $сид) + $n) % 2 !== 0) { return $м[0]; }
                $новое = $куш[mb_strtolower($м[1])] ?? null;
                if ($новое === null) { return $м[0]; }
                $надоДж--;
                return preg_match('~^[А-ЯЁ]~u', $м[1])
                    ? mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1) : $новое;
            }, $html) ?: $html;
    }

    // ── бонус: синонимы, потом согласованное определение ──
    $цельБ = ($нормаБонус[$тип] ?? 8.0) * v5RazbrosPoSidu($сид, 'бонус', 0.85, 1.15);
    $плоский = preg_replace('~\s+~u', ' ', strip_tags($html));
    $надоБ = (int) round($цельБ * $слов / 1000) - preg_match_all('~\bбонус\w*~ui', $плоский);
    if ($надоБ <= 0) { return $html; }

    static $синонимы = [
        'подарок' => 'бонус', 'подарка' => 'бонуса', 'подарку' => 'бонусу', 'подарком' => 'бонусом',
        'подарке' => 'бонусе', 'подарки' => 'бонусы', 'подарков' => 'бонусов', 'подаркам' => 'бонусам',
        'подарками' => 'бонусами', 'подарках' => 'бонусах',
        'вознаграждение' => 'бонус', 'вознаграждением' => 'бонусом', 'вознаграждении' => 'бонусе',
        'поощрение' => 'бонус', 'поощрением' => 'бонусом', 'поощрении' => 'бонусе',
    ];
    $html = (string) preg_replace_callback('~\b(подарк(?:а|у|ом|е|и|ов|ам|ами|ах)|подарок'
        . '|вознаграждени(?:е|ем|и)|поощрени(?:е|ем|и))\b~ui',
        static function (array $м) use (&$надоБ, $синонимы): string {
            if ($надоБ <= 0) { return $м[0]; }
            $новое = $синонимы[mb_strtolower($м[1])] ?? null;
            if ($новое === null) { return $м[0]; }
            $надоБ--;
            return preg_match('~^[А-ЯЁ]~u', $м[1])
                ? mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1) : $новое;
        }, $html) ?: $html;
    if ($надоБ <= 0) { return $html; }

    // Определение по падежу существительного. Мужской род единственного числа
    // и два слова, которые живут только во множественном.
    static $мужской = [
        '' => 'бонусный', 'а' => 'бонусного', 'у' => 'бонусному', 'ом' => 'бонусным',
        'е' => 'бонусном', 'ы' => 'бонусные', 'ов' => 'бонусных', 'ам' => 'бонусным',
        'ами' => 'бонусными', 'ах' => 'бонусных',
    ];
    static $множ = [
        'деньги' => 'бонусные', 'денег' => 'бонусных', 'деньгам' => 'бонусным',
        'деньгами' => 'бонусными', 'деньгах' => 'бонусных',
        'средства' => 'бонусные', 'средств' => 'бонусных', 'средствам' => 'бонусным',
        'средствами' => 'бонусными', 'средствах' => 'бонусных',
    ];
    // Своё определение уже стоит — второе не вешаем.
    $опред = '\S*(?:ый|ий|ой|ая|яя|ое|ее|ые|ие|ых|их|ым|им|ыми|ими|ого|его|ому|ему|ом|ем)';
    // «бонус-раунд» — уже бонусный: проход вешал определение поверх и в выдачу
    // уходило «бонус-бонусный раунд», 54 места на партию. Ключ слева в узком
    // окне отменяет добор целиком.
    $html = (string) preg_replace_callback(
        '~(?<!бонус)(?<!бонус-)(?<!бонусный )(?<!бонусные )(' . $опред . '\s+)?\b(пакет|баланс|раунд|спин)(а|у|ом|е|ы|ов|ам|ами|ах)?\b~ui',
        static function (array $м) use (&$надоБ, $мужской): string {
            if ($надоБ <= 0 || ($м[1] ?? '') !== '') { return $м[0]; }
            // Слово с заглавной не трогаем: это начало предложения или имя
            // пакета, и «бонусный Пакет «Формула старта»» — брак, а не добор.
            if (preg_match('~^[А-ЯЁ]~u', $м[2])) { return $м[0]; }
            $опр = $мужской[mb_strtolower($м[3] ?? '')] ?? null;
            if ($опр === null) { return $м[0]; }
            $надоБ--;
            return $опр . ' ' . $м[2] . ($м[3] ?? '');
        }, $html) ?: $html;
    if ($надоБ <= 0) { return $html; }
    return (string) preg_replace_callback(
        '~(' . $опред . '\s+)?\b(деньги|денег|деньгам|деньгами|деньгах|средства|средств|средствам|средствами|средствах)\b~ui',
        static function (array $м) use (&$надоБ, $множ): string {
            if ($надоБ <= 0 || ($м[1] ?? '') !== '') { return $м[0]; }
            if (preg_match('~^[А-ЯЁ]~u', $м[2])) { return $м[0]; }
            $опр = $множ[mb_strtolower($м[2])] ?? null;
            if ($опр === null) { return $м[0]; }
            $надоБ--;
            return $опр . ' ' . $м[2];
        }, $html) ?: $html;
}

/**
 * Определения, входящие в анкор вместе с ключом.
 *
 * «Рабочее зеркало», «свежие бонусы», «крупный джекпот»: определение уже
 * согласовано в исходном тексте, падежа и смысла анкор не меняет, а словарь
 * анкоров набора расширяется. У чужих разных анкоров 213 на 687 ссылок, у нас
 * было 145 на 608 — вся разница в длинных формулировках, а не в числе ссылок.
 */
const V5_PRIL_ANKORA = 'рабоч(?:ее|ие|его|им|ем)|мобильн\\w+|свеж\\w+|нов(?:ый|ые|ых|ым|ого|ому|ом|ая|ой|ую)'
    . '|щедр\\w+|крупн\\w+|быстр\\w+|честн\\w+|актуальн\\w+|стартов\\w+|приветственн\\w+'
    . '|бесплатн\\w+|лучш\\w+|живы\\w+|официальн\\w+|игров\\w+|личн\\w+|партнёрск\\w+';

/**
 * Повелительный глагол перед анкором забирается в анкор: «проверь зеркало»
 * вместо «проверь <a>зеркало</a>». Анкоров, начинающихся с глагола, у корпуса
 * 17.5 % при полосе 14.1–21.1, у нас было 13.6 %: записи пула дают свою долю,
 * а добор кладёт сверху одни существительные и размывает её. Число ссылок от
 * этого не меняется, меняется только их вид.
 */
const V5_GLAG_ANKORA = 'играй|играйте|заходи|заходите|жми|жмите|бери|берите|забери|заберите'
    . '|проверь|проверьте|смотри|смотрите|войди|войдите|скачай|скачайте|зайди|зайдите';

function v5DoborSsylok(string $html, string $тип, int $сид = 0): string
{
    // Цель профиля по типам — середина полосы, снятой с доноров.
    // Цель — нижний край полосы, а не середина: перекрут добирает ссылки
    // после генератора и кладёт сверху ещё десяток. При цели в середину
    // info выходил на 51 при полосе 37–47.
    static $цели = [
        'main' => 60, 'obzor' => 33, 'slots' => 32, 'bonus' => 36, 'promo' => 34,
        'registracia' => 40, 'vhod' => 35, 'zerkalo' => 35, 'app' => 37,
        'news' => 37, 'partnery' => 36, 'info' => 38,
    ];
    // Что во что ведёт. Порядок — по частоте анкора в корпусе.
    //
    // Первыми идут глагольные обороты: анкоров, начинающихся с повелительного
    // глагола, у корпуса 17.5 % (полоса 14.1–21.1), у нас было 13.6 %. Добор
    // кладёт поверх записей одни существительные и размывает долю, поэтому
    // готовые обороты в тексте забираются под ссылку раньше голых слов —
    // число ссылок от этого не меняется, меняется только их вид.
    $адреса = [
        '~\bигра(?:ть|й)\s+бесплатно\b~ui'                                      => '/slots',
        '~\b(?:войти|войди|зайти|заходи)\s+в\s+(?:казино|аккаунт|личный\s+кабинет|кабинет)\b~ui' => '/vhod',
        '~\bзарегистрир(?:оваться|уйся)\b~ui'                                   => '/registracia',
        '~\b(?:забрать|забери|бери)\s+(?:свой\s+)?бонус\w*~ui'                  => '/app',
        '~\b(?:скачать|скачай)\s+приложение\b~ui'                               => '/app',
        '~\b(?:проверить|проверь)\s+зеркало\b~ui'                               => '/zerkalo',
        '~\b(?:смотри|смотреть)\s+(?:акции|промо|турнирную\s+таблицу)\b~ui'     => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(слоты|слотов|слотах|слотам|слотами)\b~ui'                 => '/slots',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(регистрацию|регистрации|регистрацией)\b~ui'               => '/registracia',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(промокоды|промокодов|промокодам|промокодах)\b~ui'         => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(бонусы|бонусов|бонусам|бонусах|бонусами)\b~ui'            => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(зеркало|зеркала|зеркале|зеркалом)\b~ui'                   => '/zerkalo',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(приложение|приложения|приложении|приложением)\b~ui'       => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(джекпот|джекпота|джекпоте|джекпотом)\b~ui'                => '/slots',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(вход|входа|входе|входом)\b~ui'                            => '/vhod',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(турнир|турнира|турниры|турниров|турнире)\b~ui'            => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(кэшбэк|кэшбэка|кэшбэке)\b~ui'                             => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(фриспины|фриспинов|фриспинам|фриспинах)\b~ui'             => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(депозит|депозита|депозите|депозитом)\b~ui'                => '/registracia',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(выплат[аыу]|выплате|выплатой|выплаты)\b~ui'               => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(верификаци[юия]|верификацией)\b~ui'                       => '/registracia',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(лицензи[яюи]|лицензией)\b~ui'                             => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(поддержк[аиуе]|поддержкой)\b~ui'                          => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(отзывы|отзывов|отзывах|отзывам)\b~ui'                     => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(казино)\b~ui'                                             => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(акци[яию]|акции|акций|акциям|акциях)\b~ui'                => '/app',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(новости|новостей|новостям|новостях)\b~ui'                 => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(аккаунт|аккаунта|аккаунте|аккаунтом)\b~ui'                => '/registracia',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(кабинет|кабинета|кабинете)\b~ui'                          => '/vhod',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(ставк[аиуе]|ставки|ставок|ставкам|ставках)\b~ui'          => '/slots',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(автомат|автомата|автоматы|автоматов|автоматах)\b~ui'      => '/slots',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(обзор|обзора|обзоре)\b~ui'                                => '/',
        '~(?:\b(?:' . V5_PRIL_ANKORA . ')\s+)?\b(партнёрк[аиуе]|партнёрской программ[еы])\b~ui'            => '/',
    ];
    // Страница не ссылается сама на себя: на slots анкор «слоты» вёл бы
    // на /slots, и добор превращался в десяток самоссылок подряд.
    static $свой = [
        'main' => '/', 'obzor' => '/', 'slots' => '/slots', 'bonus' => '/app',
        'promo' => '/app', 'registracia' => '/registracia', 'vhod' => '/vhod',
        'zerkalo' => '/zerkalo', 'app' => '/app', 'news' => '/', 'partnery' => '',
        'info' => '',
    ];
    $мой = $свой[$тип] ?? '';
    $адреса = array_filter($адреса, static fn(string $а): bool => $а !== $мой);
    // Необязательная повелительная приставка к каждому узору: если глагол
    // стоит перед словом, он уходит под ссылку вместе с ним.
    $сГлаголом = [];
    foreach ($адреса as $рег => $адрес) {
        $сГлаголом['~(?:\b(?:' . V5_GLAG_ANKORA . ')\s+(?:в|на|за|из|к)?\s*)?' . substr($рег, 1)] = $адрес;
    }
    $адреса = $сГлаголом;

    // Цель гуляет по нижней половине полосы: набор целиком получает свой
    // коэффициент, и десять наборов перестают ложиться в три ссылки друг
    // от друга.
    static $полосы = [
        'main' => [59, 76], 'obzor' => [32, 48], 'slots' => [31, 55], 'bonus' => [35, 59],
        'promo' => [33, 58], 'registracia' => [39, 58], 'vhod' => [34, 55],
        'zerkalo' => [34, 59], 'app' => [36, 63], 'news' => [36, 53],
        'partnery' => [35, 52], 'info' => [37, 47],
    ];
    $цель = $цели[$тип] ?? 40;
    if (isset($полосы[$тип])) {
        [$низ, $верх] = $полосы[$тип];
        $цель = $низ + v5RazbrosPoSidu($сид, 'ссылки', 0.0, 0.5) * ($верх - $низ);
    }
    $надо = (int) round($цель) - preg_match_all('~<a\b~', $html);
    if ($надо <= 0) { return $html; }

    // Доля анкоров, встречающихся на странице ровно один раз, — отдельная
    // цель профиля. Добор не должен повторять уже стоящий текст: десять
    // ссылок «слоты» роняют её вдвое. Каждый новый анкор берётся один раз
    // на страницу.
    // Потолок — два вхождения анкора на страницу. Полная уникальность здесь
    // вредна: у нас доля анкоров «ровно один раз» и так 71 % при корпусных
    // 54, то есть разнообразия больше нормы, а не меньше.
    preg_match_all('~<a\b[^>]*>(.*?)</a>~su', $html, $мВсе);
    $занятыеНаСтранице = [];
    foreach ($мВсе[1] ?? [] as $x) {
        $к = mb_strtolower(trim(preg_replace('~\s+~u', ' ', strip_tags($x))));
        $занятыеНаСтранице[$к] = ($занятыеНаСтранице[$к] ?? 0) + 1;
    }

    // Два захода. Первый берёт только блоки без ссылок: доля абзацев с
    // одним анкором — отдельная цель профиля, и вторая ссылка в абзаце её
    // роняет. Второй заход трогает блоки с одной ссылкой и только если
    // страница всё ещё ниже полосы.
    $n = 0;
    foreach ([0, 1] as $потолок) {
        if ($надо <= 0) { break; }
        $html = (string) preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su',
        static function (array $бл) use (&$надо, &$n, &$занятыеНаСтранице, $адреса, $сид, $потолок): string {
            if ($надо <= 0) { return $бл[0]; }
            // Второй заход идёт только по пунктам списка: доля абзацев с
            // одним анкором — отдельная цель профиля, и вторая ссылка в
            // абзаце роняет её ниже полосы.
            if ($потолок > 0 && !str_starts_with($бл[1], '<li')) { return $бл[0]; }
            $тело = $бл[2];
            // Правило «один анкор на абзац» — про повтор одного и того же
            // анкора, а не про вторую ссылку вообще: у корпуса 43 ссылки на
            // страницу при 25 абзацах, то есть 1.7 на абзац. Потолок — две
            // разные ссылки, и анкор не должен повторять уже стоящий.
            $ужеЕсть = preg_match_all('~<a\b[^>]*>(.*?)</a>~su', $тело, $мБыли);
            if ($ужеЕсть > $потолок) { return $бл[0]; }
            $занято = array_map(static fn(string $x): string => mb_strtolower(trim(strip_tags($x))), $мБыли[1] ?? []);
            // Уже размеченные куски вынимаются из-под прохода: без этого он
            // оборачивал слово внутри чужого анкора и получалась вложенная
            // ссылка — «<a>новости <a>казино</a></a>». Браузер такую распускает,
            // у чужих их ноль, а у нас выходило по семь на набор.
            $куски = preg_split('~(<a\b[^>]*>.*?</a>)~su', $тело, -1, PREG_SPLIT_DELIM_CAPTURE);
            foreach ($адреса as $рег => $адрес) {
                $взято = false;
                $обёртка = static function (array $м) use (&$надо, &$n, &$взято, &$занятыеНаСтранице, $адрес, $сид, $занято): string {
                    if ($взято || $надо <= 0) { return $м[0]; }
                    $низ = mb_strtolower($м[0]);
                    if (in_array($низ, $занято, true) || ($занятыеНаСтранице[$низ] ?? 0) >= 2) { return $м[0]; }
                    $n++;
                    // Каждое третье слово остаётся голым: сплошная простыня
                    // ссылок читается хуже, чем их нехватка.
                    if ((crc32('ссылка|' . $сид . '|' . $n) % 3) === 0) { return $м[0]; }
                    $взято = true; $надо--;
                    $занятыеНаСтранице[$низ] = ($занятыеНаСтранице[$низ] ?? 0) + 1;
                    return '<a href="' . $адрес . '">' . $м[0] . '</a>';
                };
                foreach ($куски as $и => $кусок) {
                    if ($взято || $кусок === '' || str_starts_with($кусок, '<a')) { continue; }
                    $куски[$и] = preg_replace_callback($рег, $обёртка, $кусок) ?? $кусок;
                }
                if ($взято) { break; }
            }
            return $бл[1] . implode('', $куски) . $бл[3];
        }, $html) ?: $html;
    }
    return $html;
}

/**
 * Потолок ссылок на странице.
 *
 * У добора была только нижняя граница: он набирал ссылки до цели и не умел
 * снимать лишние. Пока словарь анкоров был узким, тормозом работал запрет
 * «не больше двух одинаковых анкоров на страницу» — страница упиралась в него
 * раньше, чем выходила за полосу. Стоило расширить словарь, как тормоз исчез,
 * и obzor набрал 66 ссылок при корпусной полосе 32–48, news 67 при 36–53.
 * Партия перестала собираться: «ссылок мимо» — жёсткий провал приёмки.
 *
 * Здесь снимается лишнее. Порядок разоружения выбран так, чтобы потолок не
 * съел разнообразие, а прибавил его:
 *   1. повторы анкора на странице — второе и последующие вхождения того же
 *      текста уходят первыми;
 *   2. вторая и третья ссылка внутри одного абзаца;
 *   3. всё остальное с конца страницы — хвост несёт меньше веса, чем начало.
 *
 * Ссылка не удаляется, а разворачивается: текст анкора остаётся на месте.
 */
/**
 * Разброс длины абзаца по корпусу.
 *
 * Замер по странице: у доноров разброс 18.6 слова, у 31 чужого набора 17.4, у
 * нас 22.8 при одинаковой средней (42.9 против 43.0). Форма расходится, а не
 * объём: абзацев длиннее восьмидесяти слов у нас 7.9 % против корпусных 2.2 %,
 * девяносто пятый перцентиль 89 слов против 72–74. `para_spread` — самая
 * частая промашка профиля: двадцать на четыре набора, больше любой другой.
 *
 * Хвост подрезается с двух сторон, средняя от этого не плывёт:
 *   · абзац длиннее 85 слов делится по границе предложения, ближайшей к
 *     середине, и так пока не уложится;
 *   · абзац короче 15 слов прирастает к предыдущему, если вместе они не
 *     перевалят за 70.
 *
 * Виджеты и списки не трогаются: режутся только абзацы прозы.
 */
function v5RovnyeAbzatsy(string $html): string
{
    // Абзацы прозы: без разметки внутри, кроме простых выделений и ссылок.
    $делитель = static function (string $тело): ?array {
        $части = preg_split('~(?<=[.!?…])\s+~u', trim($тело), -1, PREG_SPLIT_NO_EMPTY);
        if (count($части) < 4) { return null; }
        $слов = array_map(static fn(string $x): int => count(preg_split('~\s+~u', trim(strip_tags($x)), -1, PREG_SPLIT_NO_EMPTY)), $части);
        $всего = array_sum($слов);
        $надо = $всего / 2;
        $сумма = 0; $лучший = -1; $разница = PHP_INT_MAX;
        foreach ($слов as $i => $w) {
            $сумма += $w;
            if ($i === count($слов) - 1) { break; }
            $д = abs($сумма - $надо);
            if ($д < $разница) { $разница = $д; $лучший = $i; }
        }
        if ($лучший < 0) { return null; }
        return [implode(' ', array_slice($части, 0, $лучший + 1)), implode(' ', array_slice($части, $лучший + 1))];
    };

    // ── 1. длинные делим ──
    // Деление прибавляет абзацы, а ворота драйвера держат среднее по набору
    // не выше 23. Поэтому страницу, у которой абзацев и так много, не трогаем:
    // разброс там правится хуже, зато набор проходит. Слияние коротких
    // сработать почти не может — соседние <p> у нас редко стоят подряд, между
    // ними то список, то подзаголовок.
    // Делим не больше одного абзаца на страницу: разброс держат крайние
    // значения, и снятие самого длинного забирает почти весь выигрыш, а число
    // абзацев растёт на единицу вместо полутора.
    for ($круг = 0; $круг < 1; $круг++) {
        $поделили = false;
        $html = (string) preg_replace_callback('~(<p\b[^>]*>)(.*?)(</p>)~su',
            static function (array $м) use ($делитель, &$поделили): string {
                if ($поделили) { return $м[0]; }
                $чисто = trim(preg_replace('~\s+~u', ' ', strip_tags($м[2])));
                $слов = $чисто === '' ? 0 : count(preg_split('~\s+~u', $чисто));
                // Порог поднят с 85 до 110: у корпуса абзацев в 60 слов и длиннее
                // 27.2 %, у нас выходило 13.5 %, и деление работало против нас.
                if ($слов <= 110) { return $м[0]; }
                $пара = $делитель($м[2]);
                if ($пара === null) { return $м[0]; }
                $поделили = true;
                return $м[1] . $пара[0] . $м[3] . "\n" . $м[1] . $пара[1] . $м[3];
            }, $html) ?: $html;
        if (!$поделили) { break; }
    }

    // ── 2. короткие прирастают к предыдущему ──
    return (string) preg_replace_callback(
        '~(<p\b[^>]*>)(.*?)(</p>)(\s*)(<p\b[^>]*>)(.*?)(</p>)~su',
        static function (array $м): string {
            $слов = static function (string $x): int {
                $ч = trim(preg_replace('~\s+~u', ' ', strip_tags($x)));
                return $ч === '' ? 0 : count(preg_split('~\s+~u', $ч));
            };
            $первый = $слов($м[2]); $второй = $слов($м[6]);
            // Порог слияния подобран так, чтобы проход не менял числа абзацев:
            // деление длинных прибавляло 1.4 абзаца на страницу, а ворота
            // драйвера держат среднее ≤23, и набор переставал проходить.
            // Пороги подняты (22 → 26 слов, сумма 78 → 95): в корзине 10–25 слов
            // у нас 21.4 % абзацев против корпусных 15.0 %, а медиана длины
            // 38 слов против их 46.
            if ($второй >= 26 || $второй === 0 || $первый === 0) { return $м[0]; }
            if ($первый + $второй > 95) { return $м[0]; }
            return $м[1] . rtrim($м[2]) . ' ' . ltrim($м[6]) . $м[7];
        }, $html) ?: $html;
}

/**
 * Слияние разовых анкоров с их базовой формой.
 *
 * `anchor_once_pct` у доноров 32–43 %, у нас после расширения словаря 55–77:
 * почти каждый анкор на странице стал уникальным. Метрика считает разовые
 * тексты к разным текстам, поэтому лечится она не снятием ссылок, а
 * переименованием: «свежие бонусы» → «бонусы», если «бонусы» на странице уже
 * есть. Определение стоит впереди, и его снятие не трогает ни падеж, ни
 * управление.
 */
function v5SliyanieRazovyhAnkorov(string $html, float $цель = 42.0): string
{
    for ($круг = 0; $круг < 12; $круг++) {
        if (!preg_match_all('~<a\b[^>]*>(.*?)</a>~su', $html, $м, PREG_OFFSET_CAPTURE)) { return $html; }
        $счёт = [];
        foreach ($м[1] as [$сырой]) {
            $т = mb_strtolower(trim(preg_replace('~\s+~u', ' ', strip_tags($сырой))));
            if ($т !== '') { $счёт[$т] = ($счёт[$т] ?? 0) + 1; }
        }
        if (!$счёт) { return $html; }
        $разовых = count(array_filter($счёт, static fn(int $n): bool => $n === 1));
        if ($разовых * 100 / count($счёт) <= $цель) { return $html; }
        // Ищем разовый анкор, у которого первое слово — определение, а хвост
        // уже стоит на странице сам по себе.
        $снято = false;
        foreach ($м[1] as $и => [$сырой, $поз]) {
            $т = mb_strtolower(trim(preg_replace('~\s+~u', ' ', strip_tags($сырой))));
            if ($т === '' || ($счёт[$т] ?? 0) !== 1) { continue; }
            if (!preg_match('~^\S+(?:ый|ий|ой|ая|яя|ое|ее|ые|ие|ых|их|ым|им|ыми|ими|ого|его|ому|ему|ом|ем|ую|юю)\s+(.+)$~u', $т, $мХ)) { continue; }
            $база = $мХ[1];
            if (($счёт[$база] ?? 0) < 1) { continue; }
            // Снимаем определение в исходной разметке, сохраняя её регистр.
            $новый = preg_replace('~^(\s*)\S+\s+~u', '$1', $сырой, 1);
            if ($новый === null || $новый === $сырой) { continue; }
            $html = substr_replace($html, $новый, $поз, strlen($сырой));
            $снято = true;
            break;
        }
        if (!$снято) { return $html; }
    }
    return $html;
}

function v5PotolokSsylok(string $html, string $тип, int $сид = 0): string
{
    static $полосы = [
        'main' => [59, 76], 'obzor' => [32, 48], 'slots' => [31, 55], 'bonus' => [35, 59],
        'promo' => [33, 58], 'registracia' => [39, 58], 'vhod' => [34, 55],
        'zerkalo' => [34, 59], 'app' => [36, 63], 'news' => [36, 53],
        'partnery' => [35, 52], 'info' => [37, 47],
    ];
    [$низ, $верх] = $полосы[$тип] ?? [31, 60];
    // Потолок гуляет по верхней четверти полосы: у корпуса число ссылок не
    // липнет к краю, и у нас липнуть не должно.
    $потолок = (int) round($верх - v5RazbrosPoSidu($сид, 'потолок-ссылок', 0.0, 0.25) * ($верх - $низ));
    $есть = preg_match_all('~<a\b~', $html);
    $снять = $есть - $потолок;
    // Доля разовых анкоров — своя цель профиля: у доноров 32–43 %. Считается
    // она как «текстов, встреченных один раз» к «разных текстов», и снятием
    // ссылок её не исправить — пришлось бы выкинуть большую часть словаря.
    // Зато её правит переименование: у анкора вида «свежие бонусы» снимается
    // определение, и он сливается с уже стоящим на странице «бонусы». Ссылка
    // остаётся, падеж не меняется (определение всегда впереди), а разовых
    // текстов становится на один меньше. Разнообразие набора при этом не
    // страдает: на другой странице сольётся другая пара.
    $html = v5SliyanieRazovyhAnkorov($html);

    if ($снять <= 0) { return $html; }

    // Все ссылки с их положением, текстом и номером абзаца.
    $блоки = [];
    preg_match_all('~<(p|li)\b[^>]*>.*?</\1>~su', $html, $мБл, PREG_OFFSET_CAPTURE);
    foreach ($мБл[0] as $i => [$тело, $поз]) {
        $блоки[] = ['от' => $поз, 'до' => $поз + strlen($тело), 'номер' => $i];
    }
    $ссылки = [];
    if (!preg_match_all('~<a\b[^>]*>(.*?)</a>~su', $html, $мС, PREG_OFFSET_CAPTURE | PREG_SET_ORDER)) { return $html; }
    $видели = [];
    $вБлоке = [];
    $всегоПоТексту = [];
    foreach ($мС as $n => $м) {
        $поз = $м[0][1];
        $текст = mb_strtolower(trim(preg_replace('~\s+~u', ' ', strip_tags($м[1][0]))));
        $блок = -1;
        foreach ($блоки as $б) { if ($поз >= $б['от'] && $поз < $б['до']) { $блок = $б['номер']; break; } }
        $видели[$текст] = ($видели[$текст] ?? 0) + 1;
        $всегоПоТексту[$текст] = ($всегоПоТексту[$текст] ?? 0) + 1;
        $вБлоке[$блок] = ($вБлоке[$блок] ?? 0) + 1;
        $ссылки[] = [
            'поз' => $поз, 'длина' => strlen($м[0][0]), 'текст' => $текст,
            'разметка' => $м[1][0],
            'повтор' => $видели[$текст] - 1,          // 0 — первый раз
            'вАбзаце' => $блок < 0 ? 0 : $вБлоке[$блок] - 1,
            'номер' => $n,
            'единственный' => false,
        ];
    }
    foreach ($ссылки as &$с) { $с['единственный'] = ($всегоПоТексту[$с['текст']] ?? 0) === 1; }
    unset($с);
    // Что снимать, решается на каждом шаге заново. У доноров доля анкоров,
    // встреченных на странице ровно один раз, держится в 32–43 %, а после
    // расширения словаря мы поехали к 63–74: потолок, снимая повторы, гнал её
    // ещё выше, и густые наборы вставали именно на этой метрике. Теперь пока
    // доля выше сорока пяти — уходит одиночный анкор (доля падает), ниже —
    // уходит повтор (доля растёт, а с ней и разнообразие).
    $счёт = $всегоПоТексту;
    $осталось = $есть;
    $взято = [];
    $порядок = $ссылки;
    usort($порядок, static fn(array $a, array $b): int => $b['номер'] <=> $a['номер']);
    for ($шаг = 0; $шаг < $снять; $шаг++) {
        $однажды = count(array_filter($счёт, static fn(int $k): bool => $k === 1));
        $хотимОдиночный = $осталось > 0 && $однажды * 100 / $осталось > 45.0;
        $выбран = null;
        foreach ([true, false] as $строго) {
            foreach ($порядок as $к => $с) {
                if (isset($взято[$к]) || ($счёт[$с['текст']] ?? 0) < 1) { continue; }
                $одиночный = ($счёт[$с['текст']] ?? 0) === 1;
                if ($строго && $одиночный !== $хотимОдиночный) { continue; }
                $выбран = $к; break 2;
            }
        }
        if ($выбран === null) { break; }
        $взято[$выбран] = 1;
        $счёт[$порядок[$выбран]['текст']]--;
        $осталось--;
    }
    $кСнятию = array_map(static fn(int $к): array => $порядок[$к], array_keys($взято));
    // Резать с конца строки, иначе поедут смещения.
    usort($кСнятию, static fn(array $a, array $b): int => $b['поз'] <=> $a['поз']);
    foreach ($кСнятию as $с) {
        $html = substr_replace($html, $с['разметка'], $с['поз'], $с['длина']);
    }
    return $html;
}

function v5PlotnostKlyuchey(string $html, int $сид = 0): string
{
    // Пары «избыток → ключ» и корпусная медиана ключа на 1000 слов.
    static $замены = [
        // «игровой автомат» корпус почти не пишет: 0.05 против наших 0.46.
        ['~\bигров(ой|ые|ого|ым|ом|ых|ыми)\s+автомат(\w*)~ui', 'слот', 'слот'],
        ['~\bавтомат(ы|а|ов|ам|ами|ах|е|у)?\b~ui',             'слот', 'слот'],
        ['~\bподар(ок|ка|ку|ком|ке|ки|ков|кам|ками|ках)\b~ui', 'бонус', 'бонус'],
    ];
    static $окончания = [
        'слот'  => ['' => 'слот', 'ы' => 'слоты', 'а' => 'слота', 'ов' => 'слотов', 'ам' => 'слотам',
                    'ами' => 'слотами', 'ах' => 'слотах', 'е' => 'слоте', 'у' => 'слоту',
                    'ой' => 'слот', 'ые' => 'слоты', 'ого' => 'слота', 'ым' => 'слотом',
                    'ом' => 'слоте', 'ых' => 'слотах', 'ыми' => 'слотами'],
        'бонус' => ['ок' => 'бонус', 'ка' => 'бонуса', 'ку' => 'бонусу', 'ком' => 'бонусом',
                    'ке' => 'бонусе', 'ки' => 'бонусы', 'ков' => 'бонусов', 'кам' => 'бонусам',
                    'ками' => 'бонусами', 'ках' => 'бонусах'],
    ];
    $цели = ['слот' => 6.26, 'бонус' => 9.65];
    $плоский = preg_replace('~\s+~u', ' ', strip_tags($html));
    $слов = max(1, count(preg_split('~\s+~u', trim($плоский))));
    $надо = [];
    foreach ($цели as $ключ => $цель) {
        $есть = preg_match_all('~\b' . $ключ . '\w*~ui', $плоский);
        $надо[$ключ] = (int) round($цель * $слов / 1000) - $есть;
    }
    if (max($надо) <= 0) { return $html; }

    $n = 0;
    return (string) preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su',
        static function (array $бл) use (&$надо, &$n, $замены, $окончания, $сид): string {
            $тело = $бл[2];
            foreach ($замены as [$рег, $ключ, $база]) {
                if (($надо[$ключ] ?? 0) <= 0) { continue; }
                $тело = preg_replace_callback($рег, static function (array $м) use (&$надо, &$n, $ключ, $база, $окончания, $сид): string {
                    if ($надо[$ключ] <= 0) { return $м[0]; }
                    $n++;
                    // Каждое четвёртое вхождение остаётся: корпус синонимы
                    // не выбрасывает, у него «автомат» тоже есть.
                    if ((crc32('ключ|' . $сид . '|' . $n) % 4) === 0) { return $м[0]; }
                    $хвост = $м[1] ?? '';
                    if (isset($м[2])) { $хвост = $м[2]; }
                    $новое = $окончания[$база][$хвост] ?? $окончания[$база][''] ?? $база;
                    // Заглавная буква сохраняется.
                    if (preg_match('~^[А-ЯЁ]~u', $м[0])) {
                        $новое = mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1);
                    }
                    $надо[$ключ]--;
                    return $новое;
                }, $тело);
            }
            return $бл[1] . $тело . $бл[3];
        }, $html) ?: $html;
}

/**
 * Имя героя вместо местоимения.
 *
 * Замер по 43 чужим наборам: имена героев у нас 2.07 на 1000 слов против
 * корпусных 3.68, при этом местоимений 4.63 против 4.12. Герой у нас есть,
 * но после первого предложения превращается в «он» и растворяется.
 *
 * Проход работает внутри раздела: берёт имя, названное в разделе, и
 * возвращает его вместо «Он» в начале предложения — но не в том же
 * предложении, где имя уже стоит, и не чаще, чем требует недобор.
 */
/** Имена героев: банк набора целиком. По нему считается плотность имён. */
const V5_IMENA_BANKA = 'Александр|Алексей|Анатолий|Андрей|Антон|Аркадий|Арсений|Артём|Артур'
    . '|Богдан|Борис|Вадим|Валентин|Валерий|Василий|Виктор|Виталий|Владимир|Владислав|Всеволод'
    . '|Вячеслав|Геннадий|Георгий|Герман|Глеб|Григорий|Даниил|Денис|Дмитрий|Евгений|Егор|Захар'
    . '|Иван|Игнат|Игорь|Илья|Кирилл|Константин|Леонид|Макар|Максим|Марат|Марк|Матвей|Михаил'
    . '|Никита|Николай|Олег|Павел|Пётр|Роман|Ростислав|Руслан|Савелий|Семён|Сергей|Станислав'
    . '|Степан|Тарас|Тимофей|Тимур|Фёдор|Филипп|Эдуард|Юрий|Ярослав'
    . '|Алина|Анна|Валерия|Вероника|Виктория|Дарья|Екатерина|Елена|Ирина|Кристина|Ксения'
    . '|Марина|Мария|Наталья|Ольга|Полина|Светлана|София|Татьяна|Юлия|Яна';

function v5ImenaGeroya(string $html, string $тип = '', int $сид = 0): string
{
    // Медиана по 31 чужому набору, по типам страниц: на slots и promo герой
    // ведёт раздел и назван часто, на news почти не появляется.
    //
    // Прошлая таблица была занижена вдвое: её сняли списком из 35 имён, а в
    // банке набора их 46, и половина наших собственных героев в замер не
    // попадала. Пересчитано полным списком — и по чужим, и по нашим.
    static $норма = [
        'main' => 10.05, 'obzor' => 5.96, 'slots' => 11.09, 'bonus' => 6.18,
        'promo' => 11.69, 'registracia' => 5.03, 'vhod' => 5.41, 'zerkalo' => 4.86,
        'app' => 4.73, 'news' => 3.69, 'partnery' => 4.07, 'info' => 4.27,
    ];
    $цель = ($норма[$тип] ?? 5.4) * v5RazbrosPoSidu($сид, 'имена', 0.7, 1.35);
    $имена = V5_IMENA_BANKA;
    $плоский = preg_replace('~\s+~u', ' ', strip_tags($html));
    $слов = max(1, count(preg_split('~\s+~u', trim($плоский))));
    $есть = preg_match_all('~\b(?:' . $имена . ')\b~u', $плоский);
    $надо = (int) round($цель * $слов / 1000) - $есть;
    if ($надо <= 0) { return $html; }

    $n = 0;
    return (string) preg_replace_callback('~(<h2\b.*?)(?=<h2\b|$)~su',
        static function (array $разд) use (&$надо, &$n, $имена, $сид): string {
            $часть = $разд[1];
            if ($надо <= 0) { return $часть; }
            if (!preg_match('~\b(' . $имена . ')\b~u', strip_tags($часть), $мИмя)) { return $часть; }
            $имя = $мИмя[1];
            return (string) preg_replace_callback('~(<p\b[^>]*>)(.*?)(</p>)~su',
                static function (array $аб) use (&$надо, &$n, $имя, $сид): string {
                    if ($надо <= 0) { return $аб[0]; }
                    // Имя уже в абзаце — местоимение там на своём месте.
                    if (str_contains(strip_tags($аб[2]), $имя)) { return $аб[0]; }
                    // Начало предложения и начало придаточного: «…, и он забрал»
                    // тоже место для имени. Одной подстановки на абзац хватает —
                    // у чужих в абзаце с героем имя стоит 1.41 раза, у нас 1.39.
                    $тело = preg_replace_callback(
                        '~(^|(?<=[.!?]\s)|(?<=,\s)(?:и|а|но|потому что|так что)\s|(?<=—\s))(Он|он)(\s+[а-яё])~u',
                        static function (array $м) use (&$надо, &$n, $имя, $сид): string {
                            if ($надо <= 0) { return $м[0]; }
                            $n++;
                            $надо--;
                            return $м[1] . $имя . $м[3];
                        }, $аб[2], 1);
                    return $аб[1] . ($тело ?? $аб[2]) . $аб[3];
                }, $часть) ?: $часть;
        }, $html) ?: $html;
}

/**
 * Манера набора с именем бренда: густая или обычная.
 *
 * Корпус из 102 чужих наборов делится надвое, и это одно решение на весь
 * набор — двенадцать страниц живут по одной политике, как один сайт. 28 %
 * густых, как в корпусе. Признак нужен и генератору, и приёмке: судить
 * густой набор по полосам, снятым с обычных доноров, — значит требовать от
 * него того, чего у образцов его манеры нет.
 */
function v5GustoyNabor(int $сид): bool
{
    $задано = v5ManeraNabora();
    return $задано ?? ((crc32('манера|' . $сид) % 100) < 28);
}

/**
 * Перебивка манеры на набор: `null` — решает сид, иначе стоит заданное.
 *
 * Гонка сидов сама по себе манеру не сохраняет: набор собирается тем сидом,
 * который первым прошёл ворота, а густой проходит их реже обычного — за
 * десять наборов густых могло не оказаться вовсе. Поэтому манера назначается
 * партии заранее, долей корпуса, а сид разыгрывает всё остальное.
 */
function v5ManeraNabora(?bool $задать = null): ?bool
{
    static $манера = null;
    if ($задать !== null) { $манера = $задать; }
    return $манера;
}

/**
 * Имя бренда в заголовке раздела — манера густых наборов.
 *
 * Разбор 29 густых наборов корпуса: 960 заголовков h2 несут имя, то есть 33
 * на набор при наших 88 заголовках — примерно каждый третий. Отсюда и вся их
 * плотность: имя сидит не в прозе, а в заголовках, и каждый набор берёт свою
 * формулу — «<Бренд> Казино: куда ведут разделы», «Казино <Бренд>: начните с
 * журнала», «Цифры <Бренд> видны до пополнения», «Уровни игрока <Бренд>
 * Казино», «Словарь площадки <Бренд> Казино», «Запросы про <Бренд> Казино».
 *
 * Набор получает одну оправу на сид и клеит её к своим заголовкам: так имя
 * размазывается по разным ключам, а не повторяет одну фразу.
 */
function v5BrendVZagolovke(string $html, int $сид = 0): string
{
    // Пара на набор: вторая оправа — запасная для заголовка, в котором уже
    // есть тире или двоеточие. «Скачать для iOS — Без проблем на площадке
    // <Бренд> Казино» читается как обрывок, и хвостовые оправы туда не идут.
    static $оправы = [
        ['%s Казино: %s', '%s Казино: %s'],
        ['Казино %s: %s', 'Казино %s: %s'],
        ['%2$s — %1$s Казино', '%s Казино: %s'],
        ['%2$s на площадке %1$s Казино', 'Казино %s: %s'],
    ];
    $пара = $оправы[crc32('оправа|' . $сид) % count($оправы)];
    $n = 0;
    return (string) preg_replace_callback('~(<h2\b[^>]*>)(.*?)(</h2>)~su',
        static function (array $h) use (&$n, $пара, $сид): string {
            $текст = trim(preg_replace('~\s+~u', ' ', $h[2]));
            // Заголовок с именем, со ссылкой, с разметкой внутри или начатый не
            // буквой («❓ Честные ответы») не трогаем: подпись виджета и FAQ
            // живут по своим правилам, а в оправу встаёт только голый текст.
            if ($текст === '' || str_contains($текст, 'brand_name') || str_contains($текст, '<')
                || preg_match('~^[^\p{L}]~u', $текст) || mb_strlen($текст) < 8
                || mb_strlen($текст) > 70) { return $h[0]; }
            $n++;
            // Первый заголовок страницы не трогаем: текст страницы начнётся с
            // «Казино <Бренд>:», а это метрика `opener_name`, у доноров она
            // ноль. Густой набор ловил её на семи страницах из двенадцати и
            // из-за неё не собирался — 674 ушёл за две тысячи попыток.
            if ($n === 1) { return $h[0]; }
            // Каждый третий: 33 заголовка с именем на 88 заголовков набора.
            if ((crc32('заг|' . $сид . '|' . $n) % 3) !== 0) { return $h[0]; }
            $оправа = $пара[(str_contains($текст, '—') || str_contains($текст, ':')) ? 1 : 0];
            return $h[1] . sprintf($оправа, '%brand_name_ru%', $текст) . $h[3];
        }, $html) ?: $html;
}

function v5BrendStranicy(string $html, string $тип, int $сид = 0): string
{
    // Корпусная норма бренд-ключей на 1000 слов по типам страниц.
    // Корпус из 102 наборов делится надвое по манере с именем.
    //
    // Обычные (73 из 102): имя стоит на main, obzor, zerkalo, news, info и
    // partnery, а на slots, bonus, promo, registracia и vhod его нет вовсе.
    // Только кириллица.
    //
    // Густые (29 из 102): имя на каждой странице, вчетверо плотнее, и четверть
    // написаний — латиницей. Это не выброс, а вторая манера: `%brand_name_en%`
    // стоит в 30 наборах из 102, по 13 на набор медианой, и почти весь он на
    // main (333 вхождения из 334).
    //
    // Манера выбирается сидом набора: 28 % густых, как в корпусе.
    static $обычная = [
        'main' => 3.78, 'obzor' => 2.97, 'slots' => 0.0, 'bonus' => 0.0,
        'promo' => 0.0, 'registracia' => 0.0, 'vhod' => 0.0, 'zerkalo' => 2.27,
        'app' => 0.83, 'news' => 2.15, 'partnery' => 1.67, 'info' => 2.20,
    ];
    static $густая = [
        'main' => 17.22, 'obzor' => 9.54, 'slots' => 6.28, 'bonus' => 6.93,
        'promo' => 6.80, 'registracia' => 6.27, 'vhod' => 6.15, 'zerkalo' => 8.91,
        'app' => 6.03, 'news' => 8.89, 'partnery' => 8.86, 'info' => 8.30,
    ];
    $густой = v5GustoyNabor($сид);
    $норма = $густой ? $густая : $обычная;
    // В густом наборе имя сперва уходит в заголовки — там его держат чужие, и
    // оттуда берётся почти вся их плотность.
    if ($густой) { $html = v5BrendVZagolovke($html, $сид); }
    // Ключевое слово страницы, к которому корпус цепляет имя.
    static $ключи = [
        'slots' => 'каталог слотов|слоты|слотах|слотов', 'bonus' => 'бонус|бонусы|бонусов',
        'promo' => 'промокод|промокоды|акции|акция', 'zerkalo' => 'зеркало|зеркала',
        'app' => 'приложение|приложения|версия|клиент|мобильная версия',
        'news' => 'новости|обновления|новость|акция|акции|турнир|турнира|раздел',
        'partnery' => 'партнёрская программа|партнёрка|программа',
        'info' => 'казино|портал|сайт|правила|поддержка|раздел',
        'main' => 'казино|каталог|сайт|портал|раздел',
        'obzor' => 'казино|обзор|портал|сайт',
    ];
    // Разброс по набору: у корпуса плотность бренда гуляет от 0.27 до 2.22
    // при медиане 1.29, у нас укладывалась в 1.08–1.30.
    $цель = ($норма[$тип] ?? 1.5) * v5RazbrosPoSidu($сид, 'бренд', 0.45, 1.75);
    $плоский = preg_replace('~\s+~u', ' ', strip_tags($html));
    $слов = max(1, count(preg_split('~\s+~u', trim($плоский))));
    $есть = preg_match_all('~%brand_name_(?:ru|en)%~', $html);
    $надо = (int) round($цель * $слов / 1000) - $есть;
    if ($надо <= 0) { return $густой ? v5LatinicaBrenda($html, $сид) : $html; }

    // 1. «площадк-» уступает бренду. Две трети вхождений — корпус слово
    //    не выбрасывает совсем, у него 0.7 на страницу против наших 1.9.
    $n = 0;
    // Согласованное определение перед словом остаётся висеть — «публикуется
    // самой площадкой» превратилось бы в «самой %brand_name_ru%». Такие
    // вхождения пропускаем: ключ несклоняем и рода не имеет.
    // Множественное число — та же дыра, что и единственное: «честные площадки
    // не прячут важное» превращалось в «честные %brand_name_ru%». Имя одно,
    // и согласованное с ним множественное определение висит.
    $опред = 'сам(?:а|ой|у|и|их|ими)|эт(?:а|ой|у|и|их|ими)|наш(?:а|ей|у|и|их|ими|ем|его)'
        . '|т(?:а|ой|у|е|ех|еми)|данн(?:ая|ой|ую|ые|ых|ыми)|любим(?:ая|ой|ую|ые|ых|ыми)'
        . '|честн(?:ая|ой|ую|ые|ых|ыми)|лучш(?:ая|ей|ую|ие|их|ими)|надёжн(?:ая|ой|ую|ые|ых|ыми)'
        . '|разн(?:ая|ой|ую|ые|ых|ыми)|крупн(?:ая|ой|ую|ые|ых|ыми)|некотор(?:ая|ой|ую|ые|ых|ыми)'
        . '|мног(?:ие|их|ими)|все|всех|всеми';
    $html = preg_replace_callback('~(\S+\s+)?\bплощадк(?:а|и|е|у|ой|ам|ами|ах)\b~ui',
        static function (array $м) use (&$n, &$надо, $сид, $опред): string {
            if ($надо <= 0) { return $м[0]; }
            $перед = trim((string) ($м[1] ?? ''));
            if ($перед !== '' && preg_match('~^(?:' . $опред . ')$~ui', $перед)) { return $м[0]; }
            $n++;
            if ((crc32('площадка|' . $сид . '|' . $n) % 3) === 0) { return $м[0]; }
            $надо--;
            return ($м[1] ?? '') . '%brand_name_ru%';
        }, $html) ?? $html;
    if ($надо <= 0) { return $густой ? v5LatinicaBrenda($html, $сид) : $html; }

    // 2. Бренд к ключу страницы — только в прозе, не в ссылке и не в
    //    заголовке, и не там, где имя уже стоит рядом.
    $ключ = $ключи[$тип] ?? null;
    if ($ключ === null) { return $густой ? v5LatinicaBrenda($html, $сид) : $html; }
    $m = 0;
    $итог = (string) preg_replace_callback('~(<p\b[^>]*>)(.*?)(</p>)~su',
        static function (array $аб) use (&$надо, &$m, $ключ, $сид): string {
            if ($надо <= 0 || str_contains($аб[2], '%brand_name_')) { return $аб[0]; }
            // Внутри абзаца ссылки не трогаем: вырезаем их из поиска.
            $куски = preg_split('~(<a\b[^>]*>.*?</a>)~su', $аб[2], -1, PREG_SPLIT_DELIM_CAPTURE);
            $готово = false;
            foreach ($куски as $i => $к) {
                if ($готово || $надо <= 0 || str_starts_with($к, '<a')) { continue; }
                $новый = preg_replace_callback('~\b(' . $ключ . ')\b(?![\w%])~ui',
                    static function (array $м) use (&$надо, &$m, &$готово, $сид): string {
                        if ($готово || $надо <= 0) { return $м[0]; }
                        $m++;
                        if ((crc32('ключ|' . $сид . '|' . $m) % 2) !== 0) { return $м[0]; }
                        $надо--; $готово = true;
                        return $м[1] . ' %brand_name_ru%';
                    }, $к, 1);
                $куски[$i] = $новый ?? $к;
            }
            return $аб[1] . implode('', $куски) . $аб[3];
        }, $html) ?: $html;

    return $густой ? v5LatinicaBrenda($итог, $сид) : $итог;
}

/**
 * Четверть написаний имени латиницей — манера густых наборов.
 *
 * `%brand_name_en%` стоит в 30 чужих наборах из 102, медианой 13 на набор,
 * и почти весь — на main: 333 вхождения из 334. Внутри такого набора
 * латиница занимает 26 % всех написаний имени, остальное кириллица.
 */
function v5LatinicaBrenda(string $html, int $сид = 0): string
{
    // Каждое четвёртое написание, а не бросок монеты: на странице с десятком
    // ключей вероятность в 26 % даёт то ноль латиницы, то половину.
    $всего = preg_match_all('~%brand_name_ru%~', $html);
    if ($всего < 2) { return $html; }
    $сдвиг = crc32('латиница|' . $сид) % 4;
    $n = -1;
    return (string) preg_replace_callback('~%brand_name_ru%~',
        static function () use (&$n, $сдвиг): string {
            $n++;
            return (($n + $сдвиг) % 4) === 0 ? '%brand_name_en%' : '%brand_name_ru%';
        }, $html) ?: $html;
}

function v5AnkorPoPadezhu(string $html): string
{
    // Головы анкоров: форма по падежу. Хвост словосочетания не меняется.
    static $головы = [
        'новости'            => ['род' => 'новостей', 'дат' => 'новостям', 'твор' => 'новостями', 'предл' => 'новостях'],
        'обзор'              => ['род' => 'обзора',   'дат' => 'обзору',   'твор' => 'обзором',   'предл' => 'обзоре'],
        'информацию'         => ['род' => 'информации', 'дат' => 'информации', 'твор' => 'информацией', 'предл' => 'информации'],
        'бонусы'             => ['род' => 'бонусов', 'дат' => 'бонусам', 'твор' => 'бонусами', 'предл' => 'бонусах'],
        'промокоды'          => ['род' => 'промокодов', 'дат' => 'промокодам', 'твор' => 'промокодами', 'предл' => 'промокодах'],
        'слоты'              => ['род' => 'слотов', 'дат' => 'слотам', 'твор' => 'слотами', 'предл' => 'слотах'],
        'акции'              => ['род' => 'акций', 'дат' => 'акциям', 'твор' => 'акциями', 'предл' => 'акциях'],
        'вход'               => ['род' => 'входа', 'дат' => 'входу', 'твор' => 'входом', 'предл' => 'входе'],
        'регистрацию'        => ['род' => 'регистрации', 'дат' => 'регистрации', 'твор' => 'регистрацией', 'предл' => 'регистрации'],
        'промокод'           => ['род' => 'промокода', 'дат' => 'промокоду', 'твор' => 'промокодом', 'предл' => 'промокоде'],
        'бонус'              => ['род' => 'бонуса', 'дат' => 'бонусу', 'твор' => 'бонусом', 'предл' => 'бонусе'],
        'рабочее зеркало'    => ['род' => 'рабочего зеркала', 'дат' => 'рабочему зеркалу', 'твор' => 'рабочим зеркалом', 'предл' => 'рабочем зеркале'],
        'мобильное приложение' => ['род' => 'мобильного приложения', 'дат' => 'мобильному приложению', 'твор' => 'мобильным приложением', 'предл' => 'мобильном приложении'],
    ];
    // Анкор-инфинитив после предлога: существительное вместо глагола.
    static $глаголы = [
        'играть бесплатно'            => ['вин' => 'демо-режим', 'род' => 'демо-режима', 'дат' => 'демо-режиму', 'твор' => 'демо-режимом', 'предл' => 'демо-режиме'],
        'войти в аккаунт'             => ['вин' => 'вход в аккаунт', 'род' => 'входа в аккаунт', 'дат' => 'входу в аккаунт', 'твор' => 'входом в аккаунт', 'предл' => 'входе в аккаунт'],
        'войти в казино'              => ['вин' => 'вход в казино', 'род' => 'входа в казино', 'дат' => 'входу в казино', 'твор' => 'входом в казино', 'предл' => 'входе в казино'],
        'войти в личный кабинет'      => ['вин' => 'вход в личный кабинет', 'род' => 'входа в личный кабинет', 'дат' => 'входу в личный кабинет', 'твор' => 'входом в личный кабинет', 'предл' => 'входе в личный кабинет'],
        'войти в партнерский кабинет' => ['вин' => 'вход в партнёрский кабинет', 'род' => 'входа в партнёрский кабинет', 'дат' => 'входу в партнёрский кабинет', 'твор' => 'входом в партнёрский кабинет', 'предл' => 'входе в партнёрский кабинет'],
        'войти и активировать'        => ['вин' => 'вход и активацию', 'род' => 'входа и активации', 'дат' => 'входу и активации', 'твор' => 'входом и активацией', 'предл' => 'входе и активации'],
        'войти и играть'              => ['вин' => 'вход', 'род' => 'входа', 'дат' => 'входу', 'твор' => 'входом', 'предл' => 'входе'],
        'зарегистрироваться'          => ['вин' => 'регистрацию', 'род' => 'регистрации', 'дат' => 'регистрации', 'твор' => 'регистрацией', 'предл' => 'регистрации'],
        // Повелительные анкоры: перекрут берёт ярлык из профиля как есть и
        // ставит «до того, как зарегистрируйся». Ярлык законный, ломается
        // только сочетание с союзом или предлогом.
        'зарегистрируйся'             => ['вин' => 'регистрацию', 'род' => 'регистрации', 'дат' => 'регистрации', 'твор' => 'регистрацией', 'предл' => 'регистрации'],
        'зарегистрируйтесь'           => ['вин' => 'регистрацию', 'род' => 'регистрации', 'дат' => 'регистрации', 'твор' => 'регистрацией', 'предл' => 'регистрации'],
        'заходи'                      => ['вин' => 'вход', 'род' => 'входа', 'дат' => 'входу', 'твор' => 'входом', 'предл' => 'входе'],
        'играй'                       => ['вин' => 'игру', 'род' => 'игры', 'дат' => 'игре', 'твор' => 'игрой', 'предл' => 'игре'],
        'играй бесплатно'             => ['вин' => 'демо-режим', 'род' => 'демо-режима', 'дат' => 'демо-режиму', 'твор' => 'демо-режимом', 'предл' => 'демо-режиме'],
        'войди'                       => ['вин' => 'вход', 'род' => 'входа', 'дат' => 'входу', 'твор' => 'входом', 'предл' => 'входе'],
        'скачай'                      => ['вин' => 'загрузку', 'род' => 'загрузки', 'дат' => 'загрузке', 'твор' => 'загрузкой', 'предл' => 'загрузке'],
        'играть в слоты'              => ['вин' => 'игру в слоты', 'род' => 'игры в слоты', 'дат' => 'игре в слоты', 'твор' => 'игрой в слоты', 'предл' => 'игре в слоты'],
        'войти'                       => ['вин' => 'вход', 'род' => 'входа', 'дат' => 'входу', 'твор' => 'входом', 'предл' => 'входе'],
        'скачать приложение'          => ['вин' => 'загрузку приложения', 'род' => 'загрузки приложения', 'дат' => 'загрузке приложения', 'твор' => 'загрузкой приложения', 'предл' => 'загрузке приложения'],
    ];
    // Предлоги с жёстким управлением.
    static $жёсткие = [
        'из' => 'род', 'от' => 'род', 'до' => 'род', 'без' => 'род', 'для' => 'род', 'у' => 'род', 'ради' => 'род',
        'к' => 'дат', 'ко' => 'дат',
        'над' => 'твор', 'под' => 'твор', 'перед' => 'твор', 'между' => 'твор',
        'о' => 'предл', 'об' => 'предл', 'обо' => 'предл', 'при' => 'предл',
        'через' => 'вин', 'про' => 'вин', 'сквозь' => 'вин',
    ];
    // Управляющие слова, после которых «в/на» требуют предложного.
    $местные = 'написан\w*|указан\w*|сказан\w*|перечислен\w*|стои[тя]\w*|виде?шь|видн[оы]|лежа\w+|собран\w*'
        . '|публику\w+|прописан\w*|расписан\w*|есть|что|таблиц\w+|сроки';

    // «в разделе <анкор>» — родительный: «в разделе новости о слотах» читается
    // обрывком, нужен «в разделе новостей о слотах». Рамка частая: 38 случаев
    // на партию, и ни одно из правил управления её не ловило — предлог тут «в»,
    // а падеж диктует существительное «раздел», а не он.
    $html = (string) preg_replace_callback(
        '~\b(в\s+раздел(?:е|ах)\s+)(<a\b[^>]*>)([^<]{1,40})(</a>)~ui',
        static function (array $м) use ($головы): string {
            // Именительные формы, которых нет среди голов анкоров: ярлык
            // раздела иногда стоит в словарной форме — «в разделе информация».
            static $словарные = ['информация' => 'информации', 'регистрация' => 'регистрации',
                'зеркало' => 'зеркала', 'приложение' => 'приложения', 'программа' => 'программы',
                'касса' => 'кассы', 'поддержка' => 'поддержки'];
            $низ = mb_strtolower(trim($м[3]));
            foreach ($головы as $форма => $падежи) {
                if (!str_starts_with($низ, $форма)) { continue; }
                $хвост = mb_substr(trim($м[3]), mb_strlen($форма));
                return $м[1] . $м[2] . $падежи['род'] . $хвост . $м[4];
            }
            foreach ($словарные as $форма => $род) {
                if (!str_starts_with($низ, $форма)) { continue; }
                $хвост = mb_substr(trim($м[3]), mb_strlen($форма));
                return $м[1] . $м[2] . $род . $хвост . $м[4];
            }
            return $м[0];
        }, $html) ?: $html;

    // «в <анкор>» без глагола движения — предложный: «они в информацию о
    // казино» вместо «в информации о казино». Направление («зайти в
    // регистрацию») оставляем винительным, как и было.
    $движение = 'зайти|зайд\w+|заход\w+|перейти|перейд\w+|переход\w+|идти|иду|идёт|идет'
        . '|попасть|попад\w+|вернуться|верн\w+|войти|войд\w+|ныряй\w*|жми|нажм\w+';
    $html = (string) preg_replace_callback(
        '~(\S+\s+)?\b(в|на)\s+(<a\b[^>]*>)(информацию|регистрацию|акции|новости)([^<]{0,30})(</a>)~ui',
        static function (array $м) use ($головы, $движение): string {
            $перед = mb_strtolower(trim((string) ($м[1] ?? '')));
            if ($перед !== '' && preg_match('~^(?:' . $движение . ')$~ui', $перед)) { return $м[0]; }
            $форма = mb_strtolower($м[4]);
            if (!isset($головы[$форма]['предл'])) { return $м[0]; }
            return ($м[1] ?? '') . $м[2] . ' ' . $м[3] . $головы[$форма]['предл'] . $м[5] . $м[6];
        }, $html) ?: $html;

    // Составные союзы: «до того, как <a>зарегистрируйся</a>». Придаточное
    // требует глагола, а в ссылке стоит ярлык. Союз сворачивается в простой
    // предлог с существительным: «до регистрации», «после регистрации».
    $союзы = [
        '~\bдо того,?\s+как\s+(<a\b[^>]*>)([^<]{1,40})(</a>)~ui'      => ['до', 'род'],
        '~\bпосле того,?\s+как\s+(<a\b[^>]*>)([^<]{1,40})(</a>)~ui'   => ['после', 'род'],
        '~\bперед тем,?\s+как\s+(<a\b[^>]*>)([^<]{1,40})(</a>)~ui'    => ['перед', 'твор'],
        '~\bпрежде чем\s+(<a\b[^>]*>)([^<]{1,40})(</a>)~ui'            => ['до', 'род'],
    ];
    foreach ($союзы as $рег => [$предлог, $падеж]) {
        $html = (string) preg_replace_callback($рег, static function (array $м) use ($глаголы, $предлог, $падеж): string {
            $низ = mb_strtolower(trim($м[2]));
            $безЁ = static fn(string $x): string => str_replace(['ё', 'Ё'], ['е', 'Е'], $x);
            foreach ($глаголы as $форма => $падежи) {
                if ($безЁ($низ) === $безЁ($форма)) {
                    // Союз мог стоять в начале предложения — заглавная переходит
                    // на предлог, иначе «Перед тем как войди» даёт «перед входом».
                    $п = preg_match('~^[А-ЯЁ]~u', $м[0])
                        ? mb_strtoupper(mb_substr($предлог, 0, 1)) . mb_substr($предлог, 1)
                        : $предлог;
                    return $п . ' ' . $м[1] . ($падежи[$падеж] ?? $падежи['вин']) . $м[3];
                }
            }
            return $м[0];
        }, $html) ?: $html;
    }

    return (string) preg_replace_callback(
        '~(?<пред>[А-Яа-яЁё\-]+)?(?<пробел1>\s+)?(?<предлог>\b(?:в|во|на|о|об|обо|при|по|через|про|из|от|до|с|со|за|для|к|ко|у|над|под|перед|между|без|ради)\b)(?<пробел2>[\s,]*(?:как\s+)?)(?<ссылка><a\b[^>]*>)(?<текст>[^<]{1,60})(?<конец></a>)~ui',
        static function (array $м) use ($головы, $глаголы, $жёсткие, $местные): string {
            $предлог = mb_strtolower($м['предлог']);
            $текст   = trim($м['текст']);
            $низкий  = mb_strtolower($текст);
            $пред    = mb_strtolower(trim((string) ($м['пред'] ?? '')));

            // Какой падеж требуется.
            $падеж = $жёсткие[$предлог] ?? null;
            if ($падеж === null) {
                if ($предлог === 'с' || $предлог === 'со') {
                    // «начни с» — родительный; «сверился с», «рядом с» — творительный.
                    $падеж = preg_match('~^(начн\w*|начать|начина\w*|начал\w*)$~u', $пред) ? 'род' : 'твор';
                } elseif ($предлог === 'за') {
                    // «следи за» — творительный, иначе винительный и трогать нечего.
                    $падеж = preg_match('~^(следи\w*|следить|следят|наблюда\w*|гонят\w*)$~u', $пред) ? 'твор' : null;
                } elseif ($предлог === 'по') {
                    $падеж = 'дат';
                } elseif ($предлог === 'в' || $предлог === 'во' || $предлог === 'на') {
                    $падеж = preg_match('~^(?:' . $местные . ')$~ui', $пред) ? 'предл' : null;
                }
            }

            $целиком = $м[0];

            // Анкор-инфинитив ломает фразу после любого предлога — «в войти в
            // казино» не лучше, чем «через войти». Поэтому глагольный анкор
            // правится и там, где падеж «в/на» сам по себе не определился:
            // для них по умолчанию винительный.
            $безЁ = static fn(string $x): string => str_replace(['ё', 'Ё'], ['е', 'Е'], $x);
            foreach ($глаголы as $форма => $падежи) {
                if ($безЁ($низкий) !== $безЁ($форма)) { continue; }
                // «в/на» без управляющего слова: «зайти в вход в казино» не
                // чинится падежом, там лишний сам глагол. Снимаем «войти в» и
                // оставляем то, куда заходят: «зайти в казино».
                if ($падеж === null && preg_match('~^войти\s+(?:в|во)\s+(.+)$~ui', $текст, $хвост)) {
                    return str_replace('>' . $м['текст'] . '<', '>' . $хвост[1] . '<', $целиком);
                }
                $новый = $падежи[$падеж ?? 'вин'] ?? $падежи['вин'];
                $итог = str_replace('>' . $м['текст'] . '<', '>' . $новый . '<', $целиком);
                // «в вход» просит беглого гласного.
                return preg_replace('~\bв(\s+<a\b[^>]*>вход)~ui', 'во$1', $итог) ?? $итог;
            }
            if ($падеж === null || $падеж === 'вин') { return $целиком; }

            // Голова словосочетания: меняется только первое слово (или два).
            foreach ($головы as $голова => $падежи) {
                $длина = mb_strlen($голова);
                if (mb_strtolower(mb_substr($низкий, 0, $длина)) === $голова
                    && (mb_strlen($низкий) === $длина || mb_substr($низкий, $длина, 1) === ' ')) {
                    $новый = $падежи[$падеж] . mb_substr($текст, $длина);
                    return str_replace('>' . $м['текст'] . '<', '>' . $новый . '<', $целиком);
                }
            }
            return $целиком;
        },
        $html
    ) ?: $html;
}

/**
 * Мантра раздела не больше двух раз на абзац.
 *
 * Читая 608, видно хвост: «Хочешь без левых схем? Без левых схем. Без
 * развода. Без обещаний золотых гор. Всё честно и без левых схем. Без
 * левых схем — только ты, барабаны и твоё решение.» Четыре повтора в
 * пяти предложениях. Хвост собирается из отдельных фраз, и когда сразу
 * несколько несут мантру заголовка, они складываются стопкой.
 *
 * Проход берёт мантру из хвоста `h2` после тире и в каждом абзаце
 * оставляет два вхождения. Лишними снимаются целые предложения: сначала
 * те, что состоят из одной мантры, потом — те, где она в начале.
 * Предложения с содержанием не трогаются, даже если мантра в них есть.
 *
 * Замер: 16 абзацев на тираж в 46 наборов, все на bonus и promo.
 */
function v5MantraRazdela(string $html): string
{
    return (string) preg_replace_callback('~(<h2\b.*?)(?=<h2\b|$)~su', static function (array $разд): string {
        $часть = $разд[1];
        if (!preg_match('~<h2[^>]*>(.*?)</h2>~su', $часть, $mh)) { return $часть; }
        $заг = trim(preg_replace('~\s+~u', ' ', strip_tags($mh[1])));
        if (!str_contains($заг, '—')) { return $часть; }
        $мантра = trim(mb_substr($заг, mb_strpos($заг, '—') + 1));
        if (count(explode(' ', $мантра)) < 2 || mb_strlen($мантра) < 8) { return $часть; }
        $щит = preg_quote($мантра, '~');

        return (string) preg_replace_callback('~(<p\b[^>]*>)(.*?)(</p>)~su',
            static function (array $аб) use ($мантра, $щит): string {
                $внутри = $аб[2];
                if (preg_match_all('~' . $щит . '~ui', strip_tags($внутри)) < 3) { return $аб[0]; }
                // Предложения абзаца: режем по границе, разметку сохраняем.
                $куски = preg_split('~(?<=[.!?])\s+~u', $внутри, -1, PREG_SPLIT_NO_EMPTY);
                if (!$куски) { return $аб[0]; }
                $оставлено = 0; $итог = [];
                foreach ($куски as $к) {
                    $голый = trim(preg_replace('~\s+~u', ' ', strip_tags($к)));
                    $есть = (bool) preg_match('~' . $щит . '~ui', $голый);
                    if (!$есть) { $итог[] = $к; continue; }
                    // Предложение, которое держится на одной мантре, имеет
                    // право только на первое вхождение: «Хочешь без левых
                    // схем? Без левых схем.» — это уже заикание.
                    $безМантры = trim(preg_replace('~' . $щит . '~ui', '', $голый), " \t\n\r.,!?—–-");
                    $пустое = mb_strlen($безМантры) <= 24;
                    if ($пустое && $оставлено >= 1) { continue; }
                    if (!$пустое && $оставлено >= 2) { continue; }
                    $оставлено++; $итог[] = $к;
                }
                return $аб[1] . implode(' ', $итог) . $аб[3];
            }, $часть) ?: $часть;
    }, $html) ?: $html;
}

/**
 * Односложная точка в конце абзаца — «Всё.», «Вот.», «Так.»
 *
 * Приём сам по себе живой: «Без верификации не выведешь. Всё.» Но у нас он
 * шёл 0.264 раза на 1000 слов против корпусных 0.012–0.016 — в двадцать раз
 * гуще. Двадцатикратный перебор одного оборота — отпечаток, а не манера.
 *
 * Оставляем примерно каждый шестнадцатый: это выводит плотность к корпусной.
 * Выбор идёт счётом от сида, а не броском монеты, — на странице с тремя
 * такими концовками вероятность в 6 % давала то все три, то ни одной.
 */
/**
 * Меньше страдательного залога.
 *
 * Замер по 31 чужому набору точным списком форм: у них 0.87 страдательной
 * формы на 1000 слов при полосе 0.19–2.55, у нас 1.41. Мы внутри их полосы,
 * но выше медианы в полтора раза, и текст от этого канцелярится: «бонус
 * начисляется», «заявка обрабатывается», «список публикуется».
 *
 * Замена держит подлежащее в именительном — иначе пришлось бы оперировать
 * падеж всей группы: «бонус приходит», а не «бонус начисляют». Поэтому в
 * таблице только те глаголы, у которых есть непереходная пара с тем же
 * смыслом. Снимается каждое второе вхождение: слово у чужих живёт, и
 * выкашивать залог целиком значит менять язык, а не плотность.
 */
/**
 * Потолок ключей: «бонус», «вход», «поддержка», «турнир».
 *
 * Замер по 82 обычным наборам NEW100, поштучно по типам страниц. Перебор у нас
 * систематический: «бонус» выше их верхней четверти на семи типах из двенадцати,
 * «вход» — на десяти, «поддержка» — на пяти. Лишние вхождения заменяются
 * синонимом того же рода, чтобы не поехало согласование: бонус → подарок и приз,
 * бонусный → призовой, вход → доступ и заход, поддержка → служба,
 * турнир → марафон.
 *
 * Не трогаем анкеры (у ссылок своя мерка и свой пул), заголовки (в них ключ
 * журнала выдачи) и кавычки: в «Королевском турнире» ключ сидит внутри имени
 * пакета набора.
 */
function v5PotolokKlyuchey(string $html, string $тип, int $сид = 0): string
{
    // [цель — медиана корпуса, потолок — его верхняя четверть] на 1000 слов.
    static $нормы = [
        'бонус' => ['main' => [7.09, 8.65], 'obzor' => [7.90, 9.51], 'bonus' => [22.16, 26.27],
            'slots' => [7.72, 9.67], 'zerkalo' => [7.08, 8.51], 'registracia' => [8.99, 10.55],
            'vhod' => [7.69, 8.70], 'app' => [9.63, 11.59], 'promo' => [11.70, 13.83],
            'news' => [7.83, 9.46], 'info' => [5.61, 6.93], 'partnery' => [4.24, 5.46]],
        'вход' => ['main' => [2.23, 3.12], 'obzor' => [0.44, 0.68], 'bonus' => [0.00, 0.53],
            'slots' => [0.00, 0.50], 'zerkalo' => [4.36, 5.43], 'registracia' => [1.32, 2.37],
            'vhod' => [19.70, 26.17], 'app' => [4.44, 5.29], 'promo' => [0.00, 0.63],
            'news' => [0.69, 1.30], 'info' => [0.43, 0.60], 'partnery' => [0.00, 0.68]],
        'поддержка' => ['main' => [1.89, 2.91], 'obzor' => [2.08, 2.92], 'bonus' => [0.00, 0.72],
            'slots' => [0.00, 0.40], 'zerkalo' => [0.90, 1.38], 'registracia' => [0.47, 0.66],
            'vhod' => [2.61, 3.35], 'app' => [0.00, 0.40], 'promo' => [0.00, 0.48],
            'news' => [0.61, 0.98], 'info' => [6.41, 7.87], 'partnery' => [1.84, 2.52]],
        'турнир' => ['main' => [0.00, 0.54], 'obzor' => [0.00, 0.68], 'bonus' => [0.00, 1.00],
            'slots' => [0.00, 0.40], 'zerkalo' => [0.00, 0.40], 'registracia' => [0.00, 0.50],
            'vhod' => [0.00, 0.40], 'app' => [0.76, 1.39], 'promo' => [2.41, 3.55],
            'news' => [11.73, 15.19], 'info' => [0.00, 0.40], 'partnery' => [0.00, 0.40]],
    ];
    // Нижняя граница — их первая четверть. Потолок умел только снимать лишнее,
    // и «поддержка» ушла в недобор: 1.02 при полосе 1.11–2.08 (набор 684).
    static $полы = [
        'бонус' => ['main' => 5.81, 'obzor' => 6.16, 'bonus' => 18.42, 'slots' => 4.97,
            'zerkalo' => 6.10, 'registracia' => 8.13, 'vhod' => 6.61, 'app' => 7.76,
            'promo' => 10.13, 'news' => 6.05, 'info' => 4.91, 'partnery' => 3.50],
        'вход' => ['main' => 1.66, 'obzor' => 0.00, 'bonus' => 0.00, 'slots' => 0.00,
            'zerkalo' => 3.75, 'registracia' => 0.59, 'vhod' => 15.87, 'app' => 3.56,
            'promo' => 0.00, 'news' => 0.00, 'info' => 0.00, 'partnery' => 0.00],
        'поддержка' => ['main' => 1.19, 'obzor' => 1.70, 'bonus' => 0.00, 'slots' => 0.00,
            'zerkalo' => 0.49, 'registracia' => 0.00, 'vhod' => 1.68, 'app' => 0.00,
            'promo' => 0.00, 'news' => 0.00, 'info' => 5.34, 'partnery' => 1.24],
        'турнир' => ['main' => 0.00, 'obzor' => 0.00, 'bonus' => 0.00, 'slots' => 0.00,
            'zerkalo' => 0.00, 'registracia' => 0.00, 'vhod' => 0.00, 'app' => 0.00,
            'promo' => 1.24, 'news' => 7.46, 'info' => 0.00, 'partnery' => 0.00],
    ];
    // Обратные словари для добора: синоним возвращается ключом.
    static $доборКлюча = [
        'поддержка' => [
            // «служба поддержки» не трогаем — там ключ уже есть.
            ['~\bслужб(а|ы|е|у|ой|ам|ами|ах)\b(?!\s+поддержк)~ui', [
                ['а' => 'поддержка', 'ы' => 'поддержки', 'е' => 'поддержке', 'у' => 'поддержку',
                 'ой' => 'поддержкой', 'ам' => 'поддержкам', 'ами' => 'поддержками', 'ах' => 'поддержках'],
            ]],
            ['~\bпомощ(ь|и|ью)\b(?!\s+поддержк)~ui', [
                ['ь' => 'поддержка', 'и' => 'поддержки', 'ью' => 'поддержкой'],
            ]],
        ],
        'вход' => [
            ['~\bдоступ(|а|у|ом|е|ы|ов|ам|ами|ах)\b~ui', [
                ['' => 'вход', 'а' => 'входа', 'у' => 'входу', 'ом' => 'входом', 'е' => 'входе',
                 'ы' => 'входы', 'ов' => 'входов', 'ам' => 'входам', 'ами' => 'входами', 'ах' => 'входах'],
            ]],
            ['~\bзаход(|а|у|ом|е|ы|ов|ам|ами|ах)\b~ui', [
                ['' => 'вход', 'а' => 'входа', 'у' => 'входу', 'ом' => 'входом', 'е' => 'входе',
                 'ы' => 'входы', 'ов' => 'входов', 'ам' => 'входам', 'ами' => 'входами', 'ах' => 'входах'],
            ]],
        ],
        'бонус' => [
            ['~\bподар(ок|ка|ку|ком|ке|ки|ков|кам|ками|ках)\b~ui', [
                ['ок' => 'бонус', 'ка' => 'бонуса', 'ку' => 'бонусу', 'ком' => 'бонусом', 'ке' => 'бонусе',
                 'ки' => 'бонусы', 'ков' => 'бонусов', 'кам' => 'бонусам', 'ками' => 'бонусами', 'ках' => 'бонусах'],
            ]],
        ],
        'турнир' => [
            ['~\bмарафон(|а|у|ом|е|ы|ов|ам|ами|ах)\b~ui', [
                ['' => 'турнир', 'а' => 'турнира', 'у' => 'турниру', 'ом' => 'турниром', 'е' => 'турнире',
                 'ы' => 'турниры', 'ов' => 'турниров', 'ам' => 'турнирам', 'ами' => 'турнирами', 'ах' => 'турнирах'],
            ]],
        ],
    ];
    // Считаем все формы, включая прилагательные и глаголы: так меряет корпус.
    static $счётКлюча = ['бонус' => '~\bбонус\w*~ui', 'вход' => '~\bвход\w*~ui',
        'поддержка' => '~\bподдержк\w*~ui', 'турнир' => '~\bтурнир\w*~ui'];
    // На ключ — список правил [узор, словари]; правила перебираются по порядку,
    // пока лишние вхождения не кончатся. Меняются только существительные и
    // прилагательные: «входит» — глагол, у него своя жизнь.
    static $словариКлюча = [
        'бонус' => [
            // Составные термины не трогаем: «бонус-раунд» не должен стать
            // «подарок-раундом».
            ['~\bбонус(|а|у|ом|е|ы|ов|ам|ами|ах)\b(?!-[а-яё])~ui', [
                ['' => 'подарок', 'а' => 'подарка', 'у' => 'подарку', 'ом' => 'подарком', 'е' => 'подарке',
                 'ы' => 'подарки', 'ов' => 'подарков', 'ам' => 'подаркам', 'ами' => 'подарками', 'ах' => 'подарках'],
                ['' => 'приз', 'а' => 'приза', 'у' => 'призу', 'ом' => 'призом', 'е' => 'призе',
                 'ы' => 'призы', 'ов' => 'призов', 'ам' => 'призам', 'ами' => 'призами', 'ах' => 'призах'],
            ]],
            // «бонусный раунд» — профильный термин, его не трогаем.
            ['~\bбонусн(ый|ого|ому|ым|ом|ая|ой|ую|ые|ых|ыми)\b(?!\s+раунд)~ui', [
                ['ый' => 'призовой', 'ого' => 'призового', 'ому' => 'призовому', 'ым' => 'призовым',
                 'ом' => 'призовом', 'ая' => 'призовая', 'ой' => 'призовой', 'ую' => 'призовую',
                 'ые' => 'призовые', 'ых' => 'призовых', 'ыми' => 'призовыми'],
            ]],
        ],
        'вход' => [
            ['~\bвход(|а|у|ом|е|ы|ов|ам|ами|ах)\b(?!-[а-яё])~ui', [
                ['' => 'доступ', 'а' => 'доступа', 'у' => 'доступу', 'ом' => 'доступом', 'е' => 'доступе',
                 'ы' => 'доступы', 'ов' => 'доступов', 'ам' => 'доступам', 'ами' => 'доступами', 'ах' => 'доступах'],
                ['' => 'заход', 'а' => 'захода', 'у' => 'заходу', 'ом' => 'заходом', 'е' => 'заходе',
                 'ы' => 'заходы', 'ов' => 'заходов', 'ам' => 'заходам', 'ами' => 'заходами', 'ах' => 'заходах'],
            ]],
        ],
        'поддержка' => [
            ['~\bподдержк(а|и|е|у|ой|ам|ами|ах)\b~ui', [
                ['а' => 'служба', 'и' => 'службы', 'е' => 'службе', 'у' => 'службу', 'ой' => 'службой',
                 'ам' => 'службам', 'ами' => 'службами', 'ах' => 'службах'],
            ]],
        ],
        'турнир' => [
            ['~\bтурнир(|а|у|ом|е|ы|ов|ам|ами|ах)\b~ui', [
                ['' => 'марафон', 'а' => 'марафона', 'у' => 'марафону', 'ом' => 'марафоном', 'е' => 'марафоне',
                 'ы' => 'марафоны', 'ов' => 'марафонов', 'ам' => 'марафонам', 'ами' => 'марафонами', 'ах' => 'марафонах'],
            ]],
        ],
    ];

    // Слова считаются так же, как считался корпус: только буквенные, иначе
    // числа и эмодзи раздувают знаменатель и потолок не срабатывает.
    $слов = max(1, preg_match_all('~[А-Яа-яЁёA-Za-z]+~u', strip_tags($html)));
    $куски = preg_split('~(<[^>]*>)~u', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    if (!$куски) { return $html; }

    foreach ($нормы as $ключ => $поТипам) {
        [$цель, $потолок] = $поТипам[$тип] ?? [null, null];
        if ($цель === null) { continue; }
        $есть = preg_match_all($счётКлюча[$ключ], strip_tags(implode('', $куски)));
        $пол = $полы[$ключ][$тип] ?? 0.0;
        // Недобор: синоним возвращается ключом, пока не дойдём до медианы.
        if ($пол > 0 && $есть * 1000 / $слов < $пол) {
            $надо = (int) ceil($цель * $слов / 1000) - $есть;
            $н = abs(crc32('добор|' . $ключ . '|' . $сид));
            foreach ($доборКлюча[$ключ] ?? [] as [$узор, $словари]) {
                if ($надо <= 0) { break; }
                $вАнкере = 0; $вЗаголовке = 0;
                foreach ($куски as $и => $кусок) {
                    if ($кусок === '') { continue; }
                    if ($кусок[0] === '<') {
                        if (preg_match('~^<a\b~i', $кусок)) { $вАнкере++; }
                        elseif (preg_match('~^</a>~i', $кусок)) { $вАнкере = max(0, $вАнкере - 1); }
                        elseif (preg_match('~^<h[1-4]\b~i', $кусок)) { $вЗаголовке++; }
                        elseif (preg_match('~^</h[1-4]>~i', $кусок)) { $вЗаголовке = max(0, $вЗаголовке - 1); }
                        continue;
                    }
                    if ($надо <= 0 || $вАнкере > 0 || $вЗаголовке > 0) { continue; }
                    if (!preg_match_all($узор, $кусок, $все, PREG_SET_ORDER | PREG_OFFSET_CAPTURE)) { continue; }
                    $новый = $кусок; $сдвиг = 0;
                    foreach ($все as $м) {
                        if ($надо <= 0) { break; }
                        [$текст, $поз] = $м[0];
                        $доЭтого = substr($кусок, 0, $поз);
                        if (substr_count($доЭтого, '«') > substr_count($доЭтого, '»')) { continue; }
                        $новое = $словари[$н % count($словари)][mb_strtolower($м[1][0])] ?? null;
                        if ($новое === null) { continue; }
                        if (preg_match('~^[А-ЯЁ]~u', $текст)) {
                            $новое = mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1);
                        }
                        $новый = substr_replace($новый, $новое, $поз + $сдвиг, strlen($текст));
                        $сдвиг += strlen($новое) - strlen($текст);
                        $надо--; $н++;
                    }
                    $куски[$и] = $новый;
                }
            }
            continue;
        }
        if ($есть * 1000 / $слов <= $потолок) { continue; }
        $надо = $есть - (int) floor($цель * $слов / 1000);
        $н = abs(crc32($ключ . '|' . $сид));
        foreach ($словариКлюча[$ключ] as [$узор, $словари]) {
            if ($надо <= 0) { break; }
            $вАнкере = 0; $вЗаголовке = 0;
            foreach ($куски as $и => $кусок) {
                if ($кусок === '') { continue; }
                if ($кусок[0] === '<') {
                    if (preg_match('~^<a\b~i', $кусок)) { $вАнкере++; }
                    elseif (preg_match('~^</a>~i', $кусок)) { $вАнкере = max(0, $вАнкере - 1); }
                    elseif (preg_match('~^<h[1-4]\b~i', $кусок)) { $вЗаголовке++; }
                    elseif (preg_match('~^</h[1-4]>~i', $кусок)) { $вЗаголовке = max(0, $вЗаголовке - 1); }
                    continue;
                }
                if ($надо <= 0 || $вАнкере > 0 || $вЗаголовке > 0) { continue; }
                if (!preg_match_all($узор, $кусок, $все, PREG_SET_ORDER | PREG_OFFSET_CAPTURE)) { continue; }
                $новый = $кусок; $сдвиг = 0;
                foreach ($все as $м) {
                    if ($надо <= 0) { break; }
                    [$текст, $поз] = $м[0];
                    $доЭтого = substr($кусок, 0, $поз);
                    if (substr_count($доЭтого, '«') > substr_count($доЭтого, '»')) { continue; }
                    // «служба поддержки» не должна стать «службой службы».
                    if ($ключ === 'поддержка' && preg_match('~служб\w*\s+$~ui', $доЭтого)) { continue; }
                    $новое = $словари[$н % count($словари)][mb_strtolower($м[1][0])] ?? null;
                    if ($новое === null) { continue; }
                    if (preg_match('~^[А-ЯЁ]~u', $текст)) {
                        $новое = mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1);
                    }
                    $новый = substr_replace($новый, $новое, $поз + $сдвиг, strlen($текст));
                    $сдвиг += strlen($новое) - strlen($текст);
                    $надо--; $н++;
                }
                $куски[$и] = $новый;
            }
        }
    }
    return implode('', $куски);
}

/**
 * Один джекпот на абзац.
 *
 * Замер по 71 тысяче абзацев корпуса (NEW100 и NEW50_5): абзацев, где рядом
 * стоят два разных джекпота, там ноль. У нас такие набирались — «джекпот
 * достигает 9.3 млн» и через предложение «разыгрывается джекпот в 550к»:
 * сетевой джекпот набора и джекпот страницы попадали в один абзац. Лишнее
 * значение подменяется первым, включая его голые повторы в том же абзаце
 * («Ни 550к, ни ноль…» — про то же число).
 */
function v5OdinDzhekpotVAbzatse(string $html): string
{
    // Тот же узор, которым меряет смысл: «джекпот … до|в|— N млн/тыс/к».
    $узор = '~джекпот\w*[^.!?¶]{0,24}?(?:до|в|—|составляет|достигает)\s*(\d+(?:[.,]\d+)?\s*(?:млн|тыс|к))\b~ui';
    return (string) preg_replace_callback('~(<(?:p|li)\b[^>]*>)(.*?)(</(?:p|li)>)~su',
        static function (array $бл) use ($узор): string {
            $тело = $бл[2];
            if (!preg_match_all($узор, strip_tags($тело), $м) || count($м[1]) < 2) { return $бл[0]; }
            $норм = static fn(string $x): string => preg_replace('~\s+~u', ' ', mb_strtolower(trim(str_replace(',', '.', $x))));
            $первое = $м[1][0];
            $лишние = [];
            foreach (array_slice($м[1], 1) as $з) {
                if ($норм($з) !== $норм($первое)) { $лишние[$норм($з)] = $з; }
            }
            if (!$лишние) { return $бл[0]; }
            foreach ($лишние as $з) {
                $тело = (string) preg_replace('~' . preg_quote($з, '~') . '~ui', $первое, $тело);
            }
            return $бл[1] . $тело . $бл[3];
        }, $html) ?: $html;
}

/**
 * Вложенная ссылка — «<a>новости <a>казино</a></a>».
 *
 * Браузер такую разметку распускает по-своему, валидатор её не принимает, а у
 * чужих наборов вложенных ссылок ноль на все 31. У нас выходило по шесть-семь
 * на набор: добор ссылок оборачивал слово внутри уже готового анкора. Проход
 * оставляет внешнюю ссылку и снимает внутреннюю, текст сохраняя целиком.
 */
function v5RazvernutVlozhennye(string $html): string
{
    $внутри = '(?:[^<]|<(?!/?a\b))*';
    for ($i = 0; $i < 3; $i++) {
        $новый = preg_replace(
            '~(<a\b[^>]*>)(' . $внутри . ')<a\b[^>]*>(' . $внутри . ')</a>(' . $внутри . ')</a>~su',
            '$1$2$3$4</a>', $html);
        if ($новый === null || $новый === $html) { break; }
        $html = $новый;
    }
    return $html;
}

function v5MenshePassiva(string $html, int $сид = 0): string
{
    static $пары = [
        'начисляется'    => 'приходит',      'начисляются'    => 'приходят',
        'зачисляется'    => 'приходит',      'зачисляются'    => 'приходят',
        'выплачивается'  => 'приходит',      'выплачиваются'  => 'приходят',
        'публикуется'    => 'выходит',       'публикуются'    => 'выходят',
        'списывается'    => 'уходит',        'списываются'    => 'уходят',
        'указывается'    => 'стоит',         'указываются'    => 'стоят',
        'проверяется'    => 'проходит проверку', 'проверяются' => 'проходят проверку',
        'обрабатывается' => 'идёт в работу', 'обрабатываются' => 'идут в работу',
    ];
    $ключи = implode('|', array_keys($пары));
    $n = 0;
    return (string) preg_replace_callback('~\b(' . $ключи . ')\b~u',
        static function (array $м) use (&$n, $пары, $сид): string {
            $n++;
            if ((crc32('пассив|' . $сид) + $n) % 2 !== 0) { return $м[0]; }
            $новое = $пары[mb_strtolower($м[1])] ?? null;
            if ($новое === null) { return $м[0]; }
            return preg_match('~^[А-ЯЁ]~u', $м[1])
                ? mb_strtoupper(mb_substr($новое, 0, 1)) . mb_substr($новое, 1) : $новое;
        }, $html) ?: $html;
}

function v5OdnoslovnyFinal(string $html, int $сид = 0): string
{
    return (string) preg_replace_callback(
        '~([^<>]{0,40}[.!?…]\s*)(Всё|Вот|Так|Точка|Итог)\.(\s*(?:</(?:p|li|strong|em)>|$))~u',
        static function (array $м) use ($сид): string {
            // Решение считается от самого места, а не от счётчика: проход идёт
            // дважды — в генераторе и в перекруте, — и на втором заходе номера
            // сдвигались, выживший срезался, и партия выходила с круглым нулём
            // при корпусных 0.012–0.016 на 1000 слов. Ноль там, где у чужих
            // живая полоса, — такой же отпечаток, как и двадцатикратный перебор.
            if (crc32('финал|' . $сид . '|' . trim($м[1])) % 16 === 0) { return $м[0]; }
            return rtrim($м[1]) . $м[3];
        }, $html) ?: $html;
}

function v5OtvetBezVoprosa(string $html): string
{
    $связка = '~^(\s*(?:<strong>)?\s*)(Потому что|Вот почему|Именно поэтому|Поэтому|Отсюда|Причина банальная|Причина проста\w*|Ответ простой|Ответ коротк\w*|Дело в том, что|Всё просто)([,:—–-]?\s+)~u';
    return (string) preg_replace_callback('~(<h2\b.*?)(?=<h2\b|$)~su', static function (array $разд) use ($связка): string {
        $часть = $разд[1];
        // Вопрос где угодно в разделе — в заголовке, в подзаголовке, в прозе.
        if (str_contains(strip_tags($часть), '?')) { return $часть; }
        return (string) preg_replace_callback('~<p\b[^>]*>(.*?)</p>~su', static function (array $аб) use ($связка): string {
            $внутри = $аб[1];
            $новое = preg_replace_callback($связка, static function (array $м): string {
                // Первая буква остатка поднимается в заглавную.
                return $м[1];
            }, $внутри, 1, $счёт);
            if (!$счёт) { return $аб[0]; }
            $новое = preg_replace_callback('~^(\s*(?:<strong>)?\s*)(\p{Ll})~u',
                static fn(array $м): string => $м[1] . mb_strtoupper($м[2]), $новое ?? $внутри, 1);
            return str_replace($внутри, (string) $новое, $аб[0]);
        }, $часть) ?: $часть;
    }, $html) ?: $html;
}

/**
 * Один анкор на абзац. Читая набор, видно пару подряд: «бонусы до 286 % к
 * твоему депозиту могут стать трамплином. Зато бонусы на 286 % при первом
 * пополнении дают…» — одна и та же ссылка дважды в четырёх строках.
 *
 * Замер: у нас повтор анкора внутри абзаца в 5.1 % абзацев со ссылками, у
 * корпуса из 102 наборов — два случая на двадцать тысяч, то есть 0.0 %.
 *
 * Второе и последующие вхождения теряют ссылку, но не текст: фраза остаётся
 * целой, уходит только повторная разметка. Сравнение регистронезависимое и по
 * очищенному тексту — «Слоты» и «слоты» это один анкор.
 */
function v5OdinAnkorVAbzatse(string $html): string
{
    return (string) preg_replace_callback('~<p\b[^>]*>.*?</p>~su', static function (array $аб): string {
        $абзац = $аб[0];
        $встречен = [];
        return (string) preg_replace_callback('~<a\b[^>]*>(.*?)</a>~su', static function (array $сс) use (&$встречен): string {
            $текст = trim(preg_replace('~\s+~u', ' ', strip_tags($сс[1])) ?? '');
            $ключ = mb_strtolower($текст);
            if ($ключ === '' || mb_strlen($ключ) <= 3) { return $сс[0]; }
            if (!isset($встречен[$ключ])) { $встречен[$ключ] = true; return $сс[0]; }
            return $сс[1];
        }, $абзац);
    }, $html) ?: $html;
}

/**
 * Один процент на список. Чтение показало пару соседних пунктов: «бонус 500 %
 * даёт больше попыток на старте» и сразу «моментальный пакет бонусов до 500 %
 * — старт с ветерком». Число то же, мысль та же, а читается как сбой набора.
 *
 * Замер: у нас такой дубль в 30 % списков на slots и в 9 % по всем страницам,
 * у корпуса из 102 наборов — 1 % и 0 %. Пункты списка собираются из разных
 * записей пула, и прорезь {ПРОЦ} у них заполняется одним значением набора,
 * поэтому совпадение неизбежно — снимать его надо после сборки.
 *
 * Правило: в пределах одного списка значение остаётся в первом пункте, из
 * остальных уходит только число, сама фраза живёт дальше («пакет бонусов —
 * старт с ветерком»). Числа ниже пятидесяти не трогаем: это кэшбэк, доля
 * возврата и ревшара, там повтор осмыслен.
 */
function v5OdinProcentVSpiske(string $html): string
{
    return (string) preg_replace_callback('~<(ul|ol)\b[^>]*>.*?</\1>~su', static function (array $сп): string {
        $список = $сп[0];
        $встречен = [];
        return (string) preg_replace_callback('~<li\b[^>]*>.*?</li>~su', static function (array $м) use (&$встречен): string {
            $пункт = $м[0];
            return (string) preg_replace_callback('~([–—-]\s*)?(?:\s*(?:до|в)\s+)?(?:<strong>)?\s*(\d{2,4})\s*%(?:</strong>)?~u',
                static function (array $ч) use (&$встречен): string {
                    $знач = (int) $ч[2];
                    if ($знач < 50) { return $ч[0]; }
                    // Хвост диапазона не снимаем: «часто 10–20%» превращалось в
                    // «часто 10–» — оборванное тире хуже повтора числа.
                    if (($ч[1] ?? '') !== '') { return $ч[0]; }
                    if (!isset($встречен[$знач])) { $встречен[$знач] = true; return $ч[0]; }
                    return '';
                }, $пункт);
        }, $список);
    }, $html) ?: $html;
}

function v5OdinProcentPaketa(string $html, string $имяПакета, string $процент, string $имяПрограммы = ''): string
{
    // Канон страницы: либо число из паспорта набора, либо самое частое пакетное
    // значение страницы. Единое число на весь набор сажало fact_values (разных
    // фактов на странице 3 при цели 6): проценты — заметная часть числовых
    // фактов, и у чужих наборов значений пакета 3–10 на набор при 1–4 на страницу.
    // Голое «бонус N%» тоже пакетное: в наборе 511 рядом с пакетом 355 % стояли
    // «Бонус 400%», «бонусы до 286%» и «Бонус до 1000%». Отсекают его не слова
    // в предложении, а левое соседство: кэшбэк, релоад, фриспины, установка,
    // второй депозит и ревшара стоят прямо перед своим числом.
    $пакет = '~(?:пакет|приветственн|перв\w+\s+депозит|к\s+депозиту|на\s+старте|к\s+старту|при\s+регистрации'
           . '|стартов\w*|подар\w*|бонус\w*'
           . ($имяПакета !== '' ? '|' . preg_quote(mb_strtolower($имяПакета), '~') : '') . ')~ui';
    // Свои проценты есть и у других предложений: RTP, кэшбэк, вейджер, ревшара,
    // VIP-программа, второй и третий депозит, релоад, турнир, бонус за установку.
    $чужое = '~(?:rtp|отдач|возврат|к[эе]шб[эе]к|вейджер|комисси|ревшар|доля\s+от|процент\s+от|установк'
           // Вклад игры в отыгрыш — своё число: «слоты засчитывают 100%,
           // рулетка часто 10–20%». Проход видел в предложении слово «бонус» и
           // ставил туда канон пакета: «слоты засчитывают 250%».
           . '|засчитыва\w*|вклад\w*|учитыва\w*|доля\s+игр'
           . '|vip|вип|второй\s+депозит|трет[иь]\w*\s+депозит|релоад|турнир|налог|фриспин|фрибет|страховк'
           . ($имяПрограммы !== '' ? '|' . preg_quote(mb_strtolower($имяПрограммы), '~') : '') . ')~ui';
    $куски = preg_split('~(<[^>]*>)~u', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    [$плоский, $смещения] = v5PloskiyTekst($куски);
    // Пакетное ли это число: слово про пакет в предложении есть, а чужого слова
    // слева вплотную нет. Левое соседство важнее расстояния: в «отдача автоматов
    // здесь 96%, пакет до 231%» ближе оказывался «пакет», и RTP становился 231 %.
    $пакетное = static function (int $вПлоском, string $текст) use ($плоский, $пакет, $чужое): bool {
        $окно = v5PredlozhenieVokrug($плоский, $вПлоском);
        if (!preg_match($пакет, $окно)) { return false; }
        // Левое соседство решает: число принадлежит тому слову, что стоит перед
        // ним. Окно — тридцать пять знаков (не байт: у кириллицы знак в два
        // байта, и байтовое окно вдвое короче нужного).
        $слева = mb_substr(substr($плоский, 0, $вПлоском), -35);
        if (preg_match($чужое, $слева)) { return false; }
        // Хозяин числа бывает и справа: «96.4 % отдачи, до 286 % бонуса» — слово
        // «бонуса» в предложении есть, слева от первого числа чужого слова нет,
        // и проход переписывал отдачу пакетным каноном. В выдачу это ушло как
        // «286 % отдачи»: один случай на десять наборов, но он бросается в глаза.
        // Справа смотрим короче — там хозяин стоит сразу за процентом.
        // Отсчёт — от конца совпадения, а не от его начала: у числа справа
        // сначала идут его же цифры. «Три сухих числа: 96.4 % отдачи, 11 минут
        // до денег, до 333 % на первый депозит» — первое число пакетным не
        // считается, и в выдачу больше не уходит «333 % отдачи».
        $справа = mb_substr(substr($плоский, $вПлоском + strlen($текст)), 0, 22);
        return !preg_match('~^\s*%?\s*(?:rtp|отдач|возврат|кэшбэк|вейджер|комисси|ревшар)~ui', $справа);
    };
    // Первый проход — собрать кандидатов. Канон выбирается как самое частое
    // значение не ниже пятидесяти: пакет в 15–30 % — это масштаб кэшбэка и
    // ревшары, и «Пакет «Северное сияние» до 20%» рядом с «кэшбэк 20%» читался
    // как поломка (чтение набора 511).
    $счёт = [];
    foreach ($куски as $и => $кусок) {
        if ($кусок === '' || ($кусок[0] ?? '') === '<' || !str_contains($кусок, '%')) { continue; }
        if (!preg_match_all('~(?<![\d.,])(\d{2,4})(\s*)%~u', $кусок, $все, PREG_SET_ORDER | PREG_OFFSET_CAPTURE)) { continue; }
        foreach ($все as $m) {
            if (!$пакетное(($смещения[$и] ?? 0) + $m[0][1], $m[0][0])) { continue; }
            $счёт[$m[1][0]] = ($счёт[$m[1][0]] ?? 0) + 1;
        }
    }
    $канон = $процент !== '' ? $процент : null;
    if ($канон === null && $счёт) {
        $крупные = array_filter($счёт, fn($n, $з) => (int) $з >= 50, ARRAY_FILTER_USE_BOTH);
        $выбор = $крупные ?: $счёт;
        arsort($выбор);
        $канон = (string) array_key_first($выбор);
    }
    if ($канон === null) { return $html; }
    foreach ($куски as $и => $кусок) {
        if ($кусок === '' || ($кусок[0] ?? '') === '<' || !str_contains($кусок, '%')) { continue; }
        if (!preg_match_all('~(?<![\d.,])(\d{2,4})(\s*)%~u', $кусок, $все, PREG_SET_ORDER | PREG_OFFSET_CAPTURE)) { continue; }
        $сдвиг = 0; $новый = $кусок;
        foreach ($все as $m) {
            [$текст, $поз] = $m[0];
            if ($m[1][0] === $канон) { continue; }
            if (!$пакетное(($смещения[$и] ?? 0) + $поз, $текст)) { continue; }
            $новый = substr_replace($новый, $канон . $m[2][0] . '%', $поз + $сдвиг, strlen($текст));
            $сдвиг += strlen($канон . $m[2][0] . '%') - strlen($текст);
        }
        $куски[$и] = $новый;
    }
    return implode('', $куски);
}
